:root {
      /* Light theme. Not built on pure white: the page is a soft gray-green base and
         cards/panels are true white on top, so surfaces separate and glare drops
         (standard light-mode elevation practice - GitHub/Material do the same). */
      /* Jeddah Corniche Circuit (light counterpart): cool asphalt-gray page, white cards,
         timing green deepened for AA contrast on light surfaces. */
      --bg:#f0f2f3; --s1:#ffffff; --s2:#e5e9ea; --s3:#eceff0; --in-bg:#ffffff;
      --green:#008f52; --green-h:#007d48; --green-d:#00713f;
      --ac-fill:#00b467; --ac-fill-h:#00a25d; /* large fills (buttons); dark overrides desaturate them */
      --red:#a33b2e; --orange:#8a5c14; --blue:#2f63ad; --purple:#7a46c2;
      --text:#0f1215; --muted:#4f565c; --muted-l:#767e85; --border:rgba(15,18,21,.15);
      color-scheme:light;
      --accent2:rgba(0,138,80,.36); --warn:rgba(15,18,21,.38);
      --photo-bg:#ffffff; /* product photos are shot on white */
      --line2:rgba(15,18,21,.35); --acink:#04140c; --acsoft:rgba(0,143,82,.1);
      --foot:#0f1215; --footink:#f2f5f2; --footmut:#9aa1a7;
      /* rgb-triple helpers so tinted overlays (badges, hovers, borders) stay theme-correct */
      --green-rgb:0,143,82; --tint-rgb:15,18,21; --red-rgb:163,59,46; --warn-rgb:138,92,20; --purple-rgb:122,70,194; --blue-rgb:47,99,173;
      /* Design tokens: 8px spacing grid, radius steps, type scale, neutral elevation, motion */
      --sp-1:4px; --sp-2:8px; --sp-3:12px; --sp-4:16px; --sp-5:20px; --sp-6:24px; --sp-8:32px;
      --r-xs:2px; --r-sm:3px; --r-md:4px; --r-lg:6px; --r-xl:7px; --r-pill:999px;
      --fs-xs:12px; --fs-sm:13px; --fs-base:14px; --fs-md:16px; --fs-lg:20px; --fs-xl:26px; --fs-2xl:34px;
      --sh-1:0 1px 2px rgba(16,19,18,.06); --sh-2:0 3px 10px rgba(16,19,18,.09); --sh-3:0 10px 30px rgba(16,19,18,.15);
      --ease:cubic-bezier(.2,.8,.2,1); --dur:.18s;
      --font-body:'Barlow',sans-serif; --font-display:'Barlow Condensed','Barlow',sans-serif; --font-mono:'Chakra Petch','Barlow',sans-serif;
    }
    /* Dark theme - toggled via [data-theme="dark"] on <html> */
    :root[data-theme="dark"]{
      /* Jeddah Corniche Circuit: asphalt page, carbon surfaces, timing-green accent.
         Brand colors only: green / white / black. */
      --bg:#08090b; --s1:#101318; --s2:#161a21; --s3:#1d222b; --in-bg:#161a21;
      --green:#00e585; --green-h:#2eeb99; --green-d:#00e585;
      --ac-fill:#00cf78; --ac-fill-h:#0adf85; /* desaturated for big fills: saturated greens vibrate on dark */
      --red:#d4705f; --orange:#d4a04c; --blue:#4aa8f8; --purple:#a06af0;
      --text:#f2f5f2; --muted:#8b939b; --muted-l:#626a72; --border:#232830;
      color-scheme:dark;
      --accent2:rgba(0,229,133,.55); --warn:rgba(255,255,255,.55);
      --photo-bg:var(--s3); /* backdrop behind product photos (shot on dark) */
      --line2:rgba(242,245,242,.32); --acink:#04140c; --acsoft:rgba(0,229,133,.1);
      --foot:#060708; --footink:#f2f5f2; --footmut:#8b939b;
      --green-rgb:0,229,133; --tint-rgb:242,245,242; --red-rgb:212,112,95; --warn-rgb:212,160,76; --purple-rgb:160,106,240; --blue-rgb:74,168,248;
      --sh-1:0 1px 2px rgba(16,19,18,.06); --sh-2:0 4px 14px rgba(16,19,18,.08); --sh-3:0 14px 44px rgba(16,19,18,.14);
    }
    /* Hero art (hero.webp) is white-on-transparent - keep its dark chip until a real
       photo replaces it (see design handoff item 5). Topbar uses logo-dark.png instead. */
    .landing-hero-card img{background:#0c0e0c;}
    :root[data-theme="dark"] .landing-hero-card img{background:none;}
    /* Light theme: topbar + ticket read as elevated white surfaces above the gray page
       (they use var(--bg) generically, which is now the page gray). Dark is untouched. */
    :root:not([data-theme="dark"]) #topbar{background:var(--s1);}
    :root:not([data-theme="dark"]) .ticket-card{background:var(--s1);}
    /* Dark elevation ladder (Material dark guidance): higher surfaces get lighter, since
       shadows are invisible on dark. page bg < topbar/cards (s1) < modals/dialogs (s2). */
    :root[data-theme="dark"] #topbar{background:var(--s1);}
    :root[data-theme="dark"] .modal-box,:root[data-theme="dark"] .auth-box,:root[data-theme="dark"] .pin-box,:root[data-theme="dark"] .booth-popup-box{background:var(--s2);}
    *,*::before,*::after{box-sizing:border-box;margin:0;padding:0;}
    body{font-family:var(--font-body);background:var(--bg);color:var(--text);min-height:100vh;min-height:100dvh;font-size:14px;-webkit-font-smoothing:antialiased;
      background-image:radial-gradient(ellipse 80% 50% at 50% -10%, rgba(var(--green-rgb),.05), transparent 60%);}
    :focus-visible{outline:2px solid var(--green);outline-offset:2px;}
    @media (prefers-reduced-motion: reduce){
      /* 1e-5s, not .01ms: clean-css (the build's app.css) turned .01ms into NaNs, an invalid value, so riders lost this rule (round two) */
      *,*::before,*::after{animation-duration:1e-5s!important;transition-duration:1e-5s!important;}
    }

    #topbar{position:sticky;top:0;z-index:100;
      background:var(--bg);
      border-bottom:1px solid var(--border);
      backdrop-filter:blur(20px);-webkit-backdrop-filter:blur(20px);
      padding:0 28px;height:64px;display:flex;align-items:center;justify-content:space-between;gap:12px;}
    .topbar-logo{display:flex;align-items:center;gap:12px;text-decoration:none;}
    .topbar-logo img{height:44px;width:auto;max-width:160px;object-fit:contain;}
    @media(max-width:767px){.topbar-logo img{height:32px;max-width:110px;}}
    .topbar-right{display:flex;align-items:center;gap:10px;}
    .view-badge{font-size:11px;font-weight:700;padding:5px 12px;border-radius:3px;text-transform:uppercase;letter-spacing:.7px;}
    .view-badge.staff{background:rgba(var(--green-rgb),.15);color:var(--green);border:1px solid rgba(var(--green-rgb),.35);}
    .view-badge.customer{background:rgba(var(--green-rgb),.1);color:var(--green);border:1px solid rgba(var(--green-rgb),.25);}
    .topbar-btn{display:flex;align-items:center;gap:6px;padding:7px 16px;border-radius:3px;border:1px solid rgba(var(--tint-rgb),.09);background:rgba(var(--tint-rgb),.04);color:var(--muted-l);font-family:var(--font-body);font-size:13px;font-weight:700;cursor:pointer;transition:background .2s,color .2s,border-color .2s,transform .2s,box-shadow .2s,opacity .2s;}
    .btn-primary.topbar-reserve{padding:9px 20px;font-size:13.5px;}
    .topbar-btn:hover{border-color:rgba(var(--green-rgb),.4);color:var(--text);background:rgba(var(--green-rgb),.06);}
    .topbar-btn.danger:hover{border-color:rgba(var(--red-rgb),.5);color:var(--red);background:rgba(var(--red-rgb),.06);}
    .topbar-btn.undo-btn{color:var(--green);border-color:rgba(var(--green-rgb),.3);}
    .topbar-btn.undo-btn:hover{border-color:rgba(var(--green-rgb),.55);background:rgba(var(--green-rgb),.08);color:var(--green);}
    @keyframes undoPulse{0%,100%{opacity:1;}60%{opacity:.72;}} /* opacity-only: stays on the compositor */

    .tab-nav{background:var(--s1);
      border-bottom:1px solid var(--border);
      padding:0 16px;display:flex;justify-content:center;gap:2px;overflow-x:auto;scrollbar-width:none;}
    .tab-nav::-webkit-scrollbar{display:none;}
    .tab-btn{padding:15px 20px;min-height:48px;background:none;border:none;border-bottom:2px solid transparent;
      color:var(--muted);font-family:var(--font-body);font-size:14px;font-weight:700;
      cursor:pointer;white-space:nowrap;transition:color .2s,border-color .2s;
      touch-action:manipulation;-webkit-tap-highlight-color:transparent;}
    .tab-btn:hover{color:rgba(var(--tint-rgb),.75);}
    .tab-btn.active{color:var(--green);border-bottom-color:var(--green);}

    #view-landing,#view-customer,#view-staff{display:none;}
    #view-landing.active,#view-customer.active,#view-staff.active{display:block;}

    #landing-body{
      display:block;width:100%;max-width:1100px;margin:0 auto;
      padding:56px 40px 64px;
      background:transparent;
    }

    .landing-hero-grid{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:56px;align-items:center;}
    .landing-hero-copy{display:flex;flex-direction:column;align-items:flex-start;text-align:left;}
    .landing-main-title{font-size:44px;font-weight:600;letter-spacing:-1.4px;line-height:1.08;margin-bottom:18px;color:var(--text);}
    .landing-main-title span{font-family:var(--font-body);font-weight:700;color:var(--green-d);}
    .landing-subtitle{font-size:15.5px;color:var(--muted);font-weight:500;text-align:left;margin-bottom:26px;line-height:1.65;max-width:400px;}

    .landing-hero-card{
      width:100%;
      background:var(--s1);
      border:1px solid var(--border);
      border-radius:7px;overflow:hidden;cursor:pointer;
      transition:border-color .28s;
      position:relative;
      padding:0;text-align:start;display:block;
    }
    .landing-hero-card:hover{
      border-color:var(--green);
    }
    .landing-hero-card img{width:100%;height:380px;object-fit:cover;display:block;opacity:.94;transition:opacity .28s;}
    .landing-hero-card:hover img{opacity:1;}
    .landing-hero-card-cta{
      position:absolute;bottom:0;left:0;right:0;
      padding:24px 22px 20px;
      background:linear-gradient(to top,rgba(0,0,0,.6) 0%,transparent 100%);
      display:flex;align-items:center;justify-content:flex-end;
    }
    html[dir="rtl"] .landing-hero-card-cta{justify-content:flex-start;}
    .landing-hero-cta-btn{
      width:44px;height:44px;border-radius:50%;
      background:var(--ac-fill);
      display:flex;align-items:center;justify-content:center;
      color:var(--acink);font-size:18px;font-weight:700;
      transition:transform .28s cubic-bezier(.2,.8,.2,1);
      flex-shrink:0;
    }
    .landing-hero-card:hover .landing-hero-cta-btn{transform:scale(1.1) translateX(3px);}
    html[dir="rtl"] .landing-hero-card:hover .landing-hero-cta-btn{transform:scale(1.1) translateX(-3px);}

    .landing-footer{margin-top:40px;text-align:center;}
    .staff-access-btn{background:none;border:none;color:var(--muted);font-family:var(--font-body);font-size:12px;font-weight:600;cursor:pointer;padding:8px 16px;border-radius:3px;transition:background .2s,color .2s,border-color .2s,transform .2s,box-shadow .2s,opacity .2s;opacity:1;}
    .staff-access-btn:hover{color:var(--green-d);opacity:1;}
    /* for arrows the browser does not mirror (← →); not for ‹ › « », which right-to-left text mirrors by itself */
    .mirror-rtl{display:inline-block;}
    html[dir="rtl"] .mirror-rtl{transform:scaleX(-1);}
    /* Customer page back (top of .view-main): wizard step back, else the event picker. */
    .cust-back-btn{display:inline-flex;align-items:center;gap:6px;background:none;border:none;color:var(--muted);font-family:var(--font-body);font-size:13px;font-weight:800;cursor:pointer;padding:0 4px;margin-bottom:14px;transition:color .15s;}
    .cust-back-btn:hover{color:var(--text);}
    :is(html[lang="ar"],html[lang="ur"]) .cust-back-btn{font-family:'IBM Plex Sans Arabic',sans-serif;}

    /* Inline field validation: icon + message under the field (never color-only) */
    .field-err{display:flex;align-items:center;gap:5px;color:var(--red);font-size:11.5px;font-weight:600;margin-top:6px;line-height:1.4;}
    /* ── The field and group error messages (_fieldErr, _groupErr): their icon, wherever a message lands:
       without inline styles (2026-09-29, the customer pages' pass of moving style="..." into classes, so the
       policy can drop style-src 'unsafe-inline'; the other blocks of that pass sit beside their own areas'
       rules, each scoped by the id its markup is drawn under, so it outranks the class rules as the inline
       style did). No one id holds these messages; the rule is scoped by .field-err, and no other rule sets the
       icon's flex-shrink. */
    .field-err .cu-shrink0{flex-shrink:0;}
    input.field-invalid,select.field-invalid{border-color:var(--red)!important;}
    .auth-box .auth-field input.field-invalid{border-bottom-color:var(--red)!important;}


    /* Event picker (signed-in landing): clickable cards, no Reserve buttons. */
    .landing-auth-cta{margin-top:8px;}
    .landing-events-title{font-size:12px;font-weight:800;letter-spacing:1.6px;text-transform:uppercase;color:var(--muted);margin:44px 0 14px;}
    /* grid-auto-rows:1fr — every card is the height of the tallest, whether three sit in a
       row, two and one wrap, or they stack on a phone. */
    .landing-events-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(260px,1fr));gap:14px;}
    .landing-event-card{position:relative;text-align:start;background:var(--s1);border:1px solid var(--line2);border-radius:8px;padding:20px 22px 18px;cursor:pointer;font-family:var(--font-body);color:var(--text);transition:border-color .2s,transform .15s,box-shadow .2s;overflow:hidden;}
    .landing-event-card::before{content:'';position:absolute;top:0;left:0;right:0;height:3px;background:var(--green);}
    .landing-event-card.community::before{background:#4aa8f8;}
    .landing-event-card:hover{border-color:rgba(var(--green-rgb),.5);transform:translateY(-2px);box-shadow:0 10px 26px rgba(0,0,0,.25);}
    .landing-event-card.community:hover{border-color:rgba(74,168,248,.55);}
    .landing-event-card:active{transform:translateY(0);}
    .lec-title{font-family:var(--font-display);font-weight:800;font-style:italic;text-transform:uppercase;font-size:22px;letter-spacing:.4px;line-height:1.1;}
    .lec-meta{font-size:12px;font-weight:700;color:var(--muted);margin-top:7px;}
    .landing-events-grid{align-items:stretch;}
    .landing-event-card{display:flex;flex-direction:column;justify-content:center;}
    :is(html[lang="ar"],html[lang="ur"]) .landing-event-card{font-family:'IBM Plex Sans Arabic',sans-serif;}
    :is(html[lang="ar"],html[lang="ur"]) .lec-title{font-family:'IBM Plex Sans Arabic',sans-serif;font-style:normal;font-size:19px;}
    /* Signed-in landing = ONLY the event picker: hero, ghost, stripes and strip hide. */
    #landing-body.events-only .landing-hero-grid,#landing-body.events-only .landing-ghost,#landing-body.events-only .sector-stripes{display:none;}
    #landing-body.events-only .landing-events-title{margin-top:10px;}
    /* v2 event cards: a poster — the mark in a band across the top, the name and meta under it.
       The three cards are read as one set, so what is shared is the geometry: the same padding,
       the same band height, the same gap. Every logo then sits on one line and every name starts
       on another, which no row layout could do here — the marks' proportions are nothing alike
       (the National Day lockup is 2.2:1, the Micromobility mark all but square), and a name
       beside a mark starts wherever that mark happens to end.
       It was a row until Sep 2026, with the National Day card alone breaking to a poster because
       its lockup and its name would not fit side by side in a third of the picker. */
    .lec2{flex-direction:column;align-items:flex-start;justify-content:flex-start;gap:16px;padding:26px 28px;border-radius:12px;min-height:132px;}
    .lec2 .lec2-logo{order:-1;} /* the copy comes first in the markup; the mark leads */
    .lec2::before{display:none;}
    .lec2 .lec-title{font-size:24px;font-style:normal;letter-spacing:.3px;}
    .lec2 .lec-meta{font-size:13px;margin-top:8px;}
    .lec2-copy{display:flex;flex-direction:column;min-width:0;}
    /* The band is what is fixed, not the mark: each logo fills the band's height and takes the
       width its own proportions ask for, never wider than the card. */
    .lec2-logo{height:62px;max-width:100%;flex-shrink:0;display:inline-flex;align-items:center;justify-content:flex-start;}
    .lec2-logo img{height:100%;width:auto;max-width:100%;object-fit:contain;display:block;}
    /* the wordmark half of the logo flips with the theme */
    html[data-theme="dark"] .mm-on-light{display:none;}
    html:not([data-theme="dark"]) .mm-on-dark{display:none;}
    :is(html[lang="ar"],html[lang="ur"]) .lec2 .lec-title{font-size:21px;}
    @media (max-width:560px){
      .lec2{padding:20px;gap:14px;min-height:104px;}
      .lec2 .lec-title{font-size:20px;}
      .lec2-logo{height:54px;}
    }
    .spots-low{color:var(--orange);}

    @keyframes modalFadeIn{from{opacity:0}to{opacity:1}}
    @keyframes modalSlideUp{from{transform:translateY(28px) scale(.97);opacity:0}to{transform:translateY(0) scale(1);opacity:1}}
    .modal-backdrop{animation:modalFadeIn .22s ease both;}
    .modal-box{animation:modalSlideUp .28s cubic-bezier(.2,.8,.2,1) both;}

    .sess-summary-bar{display:flex;gap:8px;margin-bottom:18px;flex-wrap:wrap;}
    .sess-bar-mobile{display:none;}  
    .sess-summary-chip{
      display:flex;align-items:center;gap:10px;
      background:var(--s1);
      border:1px solid var(--border);border-radius:var(--sf-r-ctl);
      padding:10px 14px;cursor:pointer;transition:background .2s,color .2s,border-color .2s,transform .2s,box-shadow .2s,opacity .2s;
      /* auto basis, not 0: an equal split gave every chip the same width whatever was in it,
         so the Saturday ride -- the only one carrying two labelled times -- was the one that
         had to truncate. Sizing from content lets it take the room it needs from the short
         ones, and the bar still wraps when there is not enough to go round. */
      /* and a ceiling, or a chip left alone on a wrapped row stretches the whole width and
         strands its status badge a foot away from the text it belongs to. */
      flex:1 1 auto;min-width:160px;max-width:460px;}
    /* The chips are real buttons (2026-10-05): the button's own font, colour, alignment and spacing give
       way to the page's, so they read as the <div>s they were. Their parts are spans: the fill needs a box. */
    button.sess-summary-chip{font:inherit;color:inherit;text-align:inherit;letter-spacing:inherit;text-transform:inherit;margin:0;}
    .sess-summary-chip:hover{border-color:rgba(var(--green-rgb),.35);background:var(--s2);}
    .sess-summary-chip.active-sess{border-color:rgba(var(--green-rgb),.3);}
    .sess-chip-info{display:flex;flex-direction:column;gap:2px;flex:1;min-width:0;}
    /* nowrap without an overflow rule does not stay inside the column -- it paints straight
       over the status badge next to it. The Saturday ride shows two times ("Gathering 5:45 AM
       · Start 6:00 AM") and was long enough to reach it. Same treatment .sess-chip-event
       already had; the full line is in the chip's title. */
    .sess-chip-date{font-size:var(--sf-fs-xs);font-weight:600;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;}
    .sess-chip-counts{font-size:var(--sf-fs-xs);color:var(--muted);font-weight:600;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;}
    .sess-chip-bar{height:4px;border-radius:var(--sf-r-xs);background:var(--border);overflow:hidden;margin-top:6px;}
    .sess-chip-fill{display:block;height:100%;border-radius:var(--sf-r-xs);background:var(--green);transition:width .25s;}
    .sess-chip-badge{flex-shrink:0;}
    /* Community (Saturday Social Ride) sessions read blue at a glance, JCC stays green. */
    .sess-summary-chip.community{border-color:rgba(74,168,248,.45);background:rgba(74,168,248,.06);}
    .sess-summary-chip.community.active-sess{border-color:#4aa8f8;box-shadow:0 0 0 1px rgba(74,168,248,.35);}
    .sess-chip-event{font-size:var(--sf-fs-xs);font-weight:600;color:#4aa8f8;text-transform:none;letter-spacing:0;margin-bottom:3px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;}
    @media(max-width:767px){.sess-summary-bar{gap:6px;}.sess-summary-chip{min-width:140px;padding:8px 10px;}}

    .undo-bar{
      display:flex;align-items:center;gap:12px;
      background:#1e1e1e;border:1px solid rgba(var(--green-rgb),.3);border-radius:7px;
      padding:12px 16px;pointer-events:all;min-width:260px;max-width:380px;
      box-shadow:var(--sh-2);
      position:relative;overflow:hidden;}
    .undo-bar-text{flex:1;font-size:13px;font-weight:700;color:var(--text);line-height:1.3;}
    .undo-bar-action{background:var(--ac-fill);color:var(--acink);border:none;border-radius:3px;
      padding:6px 14px;font-family:var(--font-body);font-size:12px;font-weight:700;
      cursor:pointer;flex-shrink:0;transition:background .18s,color .18s,border-color .18s,transform .18s,box-shadow .18s,opacity .18s;letter-spacing:.2px;}
    .undo-bar-action:hover{background:var(--ac-fill-h);transform:scale(1.04);}
    /* Write failures: same strip, red, and it stays until dismissed or retried. */
    .err-bar{border-color:rgba(var(--red-rgb),.55);background:#2a1414;}
    .err-bar .undo-bar-action{background:var(--red);color:#fff;}
    .err-bar .undo-bar-action:hover{background:var(--red);opacity:.88;}
    .err-bar-detail{display:block;margin-top:4px;font-size:11px;font-weight:600;color:var(--muted-l);
      word-break:break-word;}

    .refresh-indicator{display:flex;align-items:center;gap:5px;font-size:var(--sf-fs-xs);color:var(--muted);font-weight:600;letter-spacing:0;}
    .refresh-dot{width:6px;height:6px;border-radius:50%;background:var(--green);animation:pulse 2s infinite;}
    @keyframes pulse{0%,100%{opacity:1;transform:scale(1)}50%{opacity:.4;transform:scale(.8)}}

    .view-main{max-width:1160px;margin:0 auto;padding:28px 28px;}
    #view-staff .view-main{max-width:min(1600px,96vw);}
    body.view-staff #app-footer{display:none;}
    /* ── Mini footer ─────────────────────────────────────────────────────────
       The rentals pages carry only what a rider booking a session needs: brand,
       three ways to reach the booth, where and when it is, three policy links,
       four socials, the legal line. The full footer (newsletter, shop columns,
       payment logos) belongs to the marketing site, not here.
       Deliberately DARK on the light site — the dark footer surface is locked
       design language. Fonts are the site's self-hosted Space Grotesk / IBM
       Plex Sans Arabic (already loaded; the CSP allows no Google Fonts). */
    #app-footer.mini-footer{
      background:#111511;color:#d5dbd6;border-top:1px solid rgba(255,255,255,.12);
      padding:22px 7vw 14px;margin-top:auto;font-size:13px;} /* auto: body is a flex column, so the footer sits at the page bottom; the 48px of air above it sits on the views */
    .mf-inner{max-width:1440px;margin:0 auto;display:flex;align-items:center;
      justify-content:space-between;gap:18px 28px;flex-wrap:wrap;}
    .mf-brand{display:flex;align-items:center;gap:12px;min-width:0;}
    .mf-logo{height:36px;width:auto;}
    .mf-info{display:flex;flex-direction:column;gap:4px;min-width:0;}
    .mf-contact{display:flex;align-items:center;gap:8px;flex-wrap:wrap;}
    .mf-contact a{color:#d5dbd6;text-decoration:none;font-weight:600;
      display:inline-flex;align-items:center;min-height:44px;}
    .mf-contact a:hover{color:#03ff89;}
    /* Privacy Notice (showPrivacyNotice): long legal text, so it scrolls inside the box and
       its tables scroll sideways on a phone instead of squeezing the columns to nothing. */
    .pv-box{max-width:760px;width:100%;max-height:88vh;overflow-y:auto;}
    .pv-head{display:flex;justify-content:space-between;align-items:flex-start;gap:12px;margin-bottom:10px;}
    .pv-upd{font-size:12px;color:var(--muted);margin-top:4px;}
    .pv-x{background:none;border:none;color:var(--muted);cursor:pointer;font-size:26px;line-height:1;padding:0 2px;}
    .pv-note{font-size:12.5px;font-weight:700;color:var(--muted-l);background:rgba(var(--tint-rgb),.05);border-radius:6px;padding:8px 10px;margin-bottom:10px;}
    .pv-body{font-size:13.5px;line-height:1.65;color:var(--text);}
    .pv-h{font-size:15px;font-weight:800;margin:18px 0 6px;}
    .pv-p{margin:0 0 8px;}
    .pv-ul{margin:0 0 8px;padding-inline-start:20px;}
    .pv-ul li{margin-bottom:4px;}
    .pv-tw{overflow-x:auto;margin:4px 0 10px;}
    .pv-t{width:100%;border-collapse:collapse;font-size:12.5px;}
    .pv-t th,.pv-t td{border:1px solid rgba(var(--tint-rgb),.12);padding:7px 8px;text-align:start;vertical-align:top;}
    .pv-t th{font-weight:800;background:rgba(var(--tint-rgb),.05);}
    .pv-body a{color:var(--green);font-weight:700;}
    .pv-link{background:none;border:none;padding:0;font:inherit;color:var(--green);font-weight:700;text-decoration:underline;cursor:pointer;}
    /* ── The Privacy Notice (showPrivacyNotice), drawn into #privacy-backdrop: without inline styles
       (2026-09-29, the customer pages' pass; scoped by that id). */
    #privacy-backdrop .cu-m0{margin:0;}
    /* On a phone three columns leave the longest one - what the data is for - a word wide.
       Each row becomes a small card instead: the first cell as its title, the others under
       their column's name. */
    @media (max-width:600px){
      .pv-t thead{display:none;}
      .pv-t,.pv-t tbody,.pv-t tr,.pv-t td{display:block;width:100%;}
      .pv-t tr{border:1px solid rgba(var(--tint-rgb),.12);border-radius:8px;padding:8px 10px;margin-bottom:8px;}
      .pv-t td{border:none;padding:3px 0;}
      .pv-t td:first-child{font-weight:800;}
      .pv-t td:not(:first-child)::before{content:attr(data-label);display:block;font-size:10.5px;font-weight:800;letter-spacing:.3px;color:var(--muted);text-transform:uppercase;margin-bottom:1px;}
    }
    .mf-dot{color:#8a938c;}
    .mf-addr{color:#8a938c;text-decoration:none;display:inline-flex;align-items:center;min-height:24px;}
    .mf-addr:hover{color:#03ff89;}
    .mf-hours{color:#8a938c;}
    .mf-social{display:flex;align-items:center;gap:4px;}
    /* 44px touch targets around 40px visual circles: the circle is the look,
       the anchor is the finger's landing zone. */
    .mf-social a{display:flex;align-items:center;justify-content:center;
      width:44px;height:44px;text-decoration:none;flex-shrink:0;}
    .mf-circle{display:flex;align-items:center;justify-content:center;
      width:40px;height:40px;border-radius:50%;background:#077A4B;color:#FBF9F4;
      transition:background .22s,transform .22s;}
    .mf-circle svg{width:18px;height:18px;}
    .mf-social a:hover .mf-circle{background:#0FA463;transform:translateY(-2px);}
    .mf-social a:focus-visible .mf-circle{outline:2px solid #03ff89;outline-offset:2px;}
    /* Latin-rendered runs (phone, email, VAT) hold their direction inside RTL. */
    .mf-ltr{direction:ltr;unicode-bidi:embed;}
    .mf-bottom{max-width:1440px;margin:12px auto 0;padding-top:10px;
      border-top:1px solid rgba(255,255,255,.12);
      display:flex;align-items:center;justify-content:center;gap:8px;flex-wrap:wrap;
      color:#8a938c;font-size:12px;}
    .mf-bottom .footer-copy{color:#8a938c;}
    @media(max-width:767px){
      #app-footer.mini-footer{padding:16px 16px 12px;}
      .mf-inner{flex-direction:column;align-items:flex-start;gap:8px;}
      /* Each contact is its own full-width 44px row — the dot separators exist for the
         single desktop line and only produce dangling punctuation once things wrap. */
      .mf-contact{flex-direction:column;align-items:stretch;gap:0;width:100%;}
      .mf-contact .mf-dot{display:none;}
      .mf-contact a{min-height:44px;width:100%;}
      .mf-addr{min-height:44px;}
      .mf-social{padding-top:2px;}
      .mf-bottom{justify-content:flex-start;text-align:start;row-gap:2px;}
      .mf-bottom .mf-dot{display:none;}   /* same dangling-dot cure once the legal line wraps */
    }
    .footer-copy{font-size:10.5px;color:var(--muted);font-weight:600;letter-spacing:.2px;}
    .tab-panel{display:none;}
    .tab-panel.active{display:block;}
    .page-title{font-size:23px;font-weight:700;margin-bottom:4px;letter-spacing:-1.5px;}
