    .pin-backdrop{position:fixed;inset:0;background:rgba(16,19,18,.5);backdrop-filter:blur(16px);-webkit-backdrop-filter:blur(16px);z-index:300;display:flex;align-items:center;justify-content:center;padding:20px;}
    .pin-box{background:var(--s1);border:1px solid var(--border);border-radius:7px;padding:36px 32px;width:100%;max-width:340px;text-align:center;box-shadow:0 1px 3px rgba(16,19,18,.06);}
