      .topbar-logo img{height:28px;max-width:96px;}
      .cust-topbar-email{display:none;}
      .cust-topbar-name{font-size:12px;max-width:76px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;}
      .lang-toggle{padding:6px 9px;font-size:11px;flex-shrink:0;}
      .topbar-btn{padding:6px 10px;font-size:11px;flex-shrink:0;min-height:36px;}
      .topbar-right{gap:5px;flex-shrink:0;}
      .view-badge{font-size:10px;padding:4px 8px;letter-spacing:.3px;}

      .tab-nav{padding:0 4px;justify-content:stretch;}
      .tab-btn{padding:12px 10px;font-size:11px;min-height:44px;flex:1;text-align:center;white-space:nowrap;}

      #customer-tab-nav{display:none;}

      .view-main{padding:12px 14px 24px;}
      .page-title{font-size:20px;margin-bottom:3px;}
      .page-sub{font-size:12px;margin-bottom:12px;line-height:1.4;}
      .section-header{flex-direction:column;align-items:stretch;gap:10px;margin-bottom:14px;}
      .section-header > div:first-child{width:100%;}
      .section-header > button,
      .section-header > div:last-child:not(:first-child){width:100%;display:flex;gap:8px;flex-wrap:wrap;}
      .section-header .btn-primary,
      .section-header .btn-secondary{flex:1;text-align:center;justify-content:center;padding:10px 12px;font-size:var(--sf-fs-sm);}
      .page-title{font-size:20px;}
      .page-sub{font-size:12px;line-height:1.4;margin-bottom:4px;}

      #view-customer .view-main{padding-bottom:calc(74px + env(safe-area-inset-bottom));}
      #view-staff .view-main{padding-bottom:24px;}
      #app-footer{padding-bottom:calc(70px + env(safe-area-inset-bottom));}

      #landing-body{padding:28px 16px 48px;text-align:center;}
      .landing-hero-grid{grid-template-columns:1fr;gap:28px;}
      .landing-hero-copy{align-items:center;text-align:center;}
      .landing-subtitle{text-align:center;margin-left:auto;margin-right:auto;}
      .landing-main-title{font-size:28px;margin-bottom:18px;line-height:1.1;}
      .landing-hero-card{border-radius:6px;}
      .landing-hero-card img{height:220px;}
      .landing-hero-cta-btn{width:42px;height:42px;font-size:18px;}
      .landing-footer{margin-top:20px;}

      .form-section{padding:16px;border-radius:7px;}
      .form-title{font-size:15px;margin-bottom:14px;}
      .form-row{grid-template-columns:1fr;gap:10px;margin-bottom:10px;}
      .inline-form{padding:16px;border-radius:var(--sf-r-ctl,var(--sf-r-ctl));}
      .form-group label{font-size:12px;}
      input[type="text"],input[type="tel"],input[type="number"],input[type="email"],
      input[type="date"],input[type="time"],input[type="password"],select{
        padding:12px 14px;font-size:16px;border-radius:4px;min-height:46px;
      }
      select{padding-inline-end:34px;} /* the shorthand above took back the room the chevron sits in */
      .filter-select{height:40px;font-size:var(--sf-fs-sm);min-height:var(--sf-ctl-size);}

      .stats-row{display:grid;grid-template-columns:repeat(2,1fr);gap:8px;margin-bottom:14px;flex-wrap:unset;}
      .stats-row{gap:6px;margin-bottom:10px;}
      .stat-card{padding:10px 12px;min-width:0;border-radius:var(--sf-r-xs);}
      .stat-num{font-size:var(--sf-fs-xl);line-height:1.1;}
      .stat-label{font-size:var(--sf-fs-xs);letter-spacing:0;margin-top:2px;}

      .session-picker-wrap{margin-bottom:16px;}
      .session-cards-grid{gap:8px;}
      .sess-card{padding:12px;padding-inline-start:calc(12px + var(--sc-gut));min-height:58px;}
      .sess-card-date{font-size:15px;}
      .sess-card-spots{font-size:11px;}

      .sess-bar-desktop{display:none!important;}  
      .sess-bar-mobile{display:block;}             

      .hide-mobile{display:none!important;}
      .table-wrapper{border-radius:var(--sf-r-ctl);overflow-x:auto;-webkit-overflow-scrolling:touch;}
      .queue-table{min-width:680px;}
      .queue-table th{padding:8px 8px;font-size:var(--sf-fs-xs);letter-spacing:0;white-space:nowrap;}
      .queue-table td{padding:9px 8px;white-space:nowrap;}
      .queue-num-cell{font-size:var(--sf-fs-lg);}
      .rider-name{font-size:var(--sf-fs-sm);}
      .rider-sub{font-size:var(--sf-fs-xs);}
      .sess-admin-table{min-width:480px;}
      .sess-admin-table th,.sess-admin-table td{padding:9px 10px;font-size:var(--sf-fs-xs);}
      .actions-cell{display:flex;gap:4px;flex-wrap:nowrap;align-items:stretch;}
      .btn-sm{padding:6px 10px;font-size:11px;min-height:34px;white-space:nowrap;}

      .btn-primary,.btn-secondary{min-height:46px;font-size:14px;}

      .toggle-group{gap:6px;flex-wrap:wrap;}
      .toggle-btn{padding:8px 12px;font-size:13px;min-height:40px;min-width:0;}

      .qty-stepper{gap:12px;}
      .qty-btn{width:36px;height:36px;font-size:20px;}
      .qty-val{font-size:20px;}

      .hist-action-btns{width:100%;flex-shrink:unset;}
      .hist-action-btns .btn-secondary{flex:1;text-align:center;padding:9px 10px;font-size:var(--sf-fs-xs);}

      .filter-row{gap:6px;margin-bottom:10px;overflow-x:auto;flex-wrap:nowrap;padding-bottom:4px;}
      .filter-row::-webkit-scrollbar{display:none;}
      .search-input{width:110px!important;}
      .search-wrap{flex-shrink:0;}

      .price-preview{flex-direction:column;gap:4px;align-items:flex-start;padding:12px 14px;}
      .price-preview-total{font-size:18px;}
      .price-preview-breakdown{font-size:12px;line-height:1.5;}

      .ticket-card{margin-top:20px;}
      .ticket-header{padding:16px 14px 14px;}

      .bike-assign-grid{grid-template-columns:repeat(2,1fr);}

      /* Every pop-up sits in the middle of the screen on a phone as on a desk (the owner, 2026-09-30:
         "always center pages that pop up"), not as a sheet stuck to the bottom edge. */
      .modal-backdrop{padding:12px;align-items:center;}
      .modal-box{
        padding:20px 16px;border-radius:var(--r-xl);
        max-height:88dvh;width:100%;max-width:100%;
      }
      .modal-title{font-size:16px;margin-bottom:4px;}
      .modal-sub{font-size:12px;margin-bottom:12px;}
      .modal-footer{flex-direction:column-reverse;gap:8px;}
      .modal-footer .btn-primary,.modal-footer .btn-secondary{width:100%;text-align:center;padding:13px;}

      .pin-box{padding:24px 18px;border-radius:7px;}
      .auth-backdrop{
        align-items:center;padding:12px;
        overflow:hidden; 
      }
      .auth-box{
        padding:20px 16px 24px;
        border-radius:var(--r-xl);width:100%;max-width:100%;margin:0;
        overflow-y:auto;          
        -webkit-overflow-scrolling:touch;
        overscroll-behavior:contain;
        max-height:88dvh;
        height:auto;
      }
      .auth-logo{max-height:44px;}
      .auth-title{font-size:18px;}
      .auth-sub{font-size:12px;margin-bottom:14px;}
      .auth-switch{margin-bottom:14px;}
      .auth-field{margin-bottom:10px;}
      .auth-submit{min-height:50px;font-size:16px;}

      .queue-mobile-view{display:block;}
      .queue-table-desktop-wrap{display:none;}
      .q-card .btn-sm{flex:1;padding:10px 12px;font-size:var(--sf-fs-xs);min-height:var(--sf-ctl-size);text-align:center;justify-content:center;}

      .undo-bar{min-width:0;width:calc(100vw - 28px);}

      .empty-state{padding:28px 16px;font-size:13px;}

      .toast{font-size:12px;padding:10px 14px;white-space:normal;
        max-width:calc(100vw - 28px);text-align:center;}
      #toast-container{
        width:100%;align-items:center;
        bottom:calc(70px + env(safe-area-inset-bottom) + 8px);
        left:0;transform:none;padding:0 14px;
      }
    }

    @media(max-width:390px){
      .view-main{padding:10px 12px 20px;}
      .landing-main-title{font-size:22px;}
      .stats-row{grid-template-columns:repeat(2,1fr);}
      .toggle-btn{padding:6px 9px;font-size:12px;}
      .tab-btn{padding:10px 8px;font-size:10px;flex:1;}
      .ticket-num{font-size:48px;}
      .topbar-right{gap:4px;}
      .lang-toggle{padding:5px 6px;font-size:10px;}
      #topbar{gap:4px;}
      .queue-table{min-width:620px;}
      .filter-select{font-size:var(--sf-fs-xs);height:38px;}
      .btn-sm{padding:5px 8px;font-size:11px;}
    }

    /* ── Sessions (phones <=480px): stack the admin tables into label/value cards so every
       session is fully visible with vertical-only scrolling. No contained horizontal table scroll.
       Desktop/tablet are untouched (these rules only apply under 480px). The sessions list moved
       into #sess-host on the Bookings tab and back to its own #tab-sessions section (2026-11-06); the
       rules follow the id, or the deleted-sessions and promo-code tables scroll sideways again. ── */
    @media(max-width:480px){
      #tab-sessions .table-wrapper{overflow-x:visible;border:none;border-radius:0;}
      #tab-sessions .sess-admin-table,
      #tab-sessions .sess-admin-table tbody,
      #tab-sessions .sess-admin-table tr,
      #tab-sessions .sess-admin-table td{display:block;width:100%;max-width:100%;min-width:0;box-sizing:border-box;}
      #tab-sessions .sess-admin-table thead{position:absolute;width:1px;height:1px;padding:0;margin:-1px;overflow:hidden;clip:rect(0 0 0 0);border:0;}
      #tab-sessions .sess-admin-table tr{background:var(--s1);border:1px solid var(--border);border-radius:var(--sf-r-ctl);margin-bottom:10px;padding:2px;overflow:hidden;}
      #tab-sessions .sess-admin-table td{border:none;border-bottom:1px solid rgba(var(--tint-rgb),.05);padding:8px 14px;font-size:var(--sf-fs-sm);text-align:start;overflow-wrap:anywhere;}
      #tab-sessions .sess-admin-table td:last-child{border-bottom:none;}
      #tab-sessions .sess-admin-table td::before{content:attr(data-label);display:block;font-size:var(--sf-fs-xs);font-weight:600;letter-spacing:0;text-transform:none;color:var(--muted);margin-bottom:3px;}
      #tab-sessions .sess-admin-table td[colspan]{text-align:center;}
      #tab-sessions .sess-admin-table td[colspan]::before{display:none;}
      #tab-sessions .sess-admin-table td.cell-actions::before{display:none;}
      #tab-sessions .sess-admin-table td.cell-actions .actions-cell{gap:8px;}
      #tab-sessions .sess-admin-table td.cell-actions .btn-sm{flex:1 1 calc(50% - 5px);min-width:0;padding:10px;font-size:var(--sf-fs-xs);}
      /* keep the "new session" add-form fleet-count grid contained (admin entry), not page-wide */
      #tab-sessions .inline-form table{min-width:0;}
    }

    /* ── iOS touch & feedback polish (HIG: 44pt targets, no grey tap-flash, press feedback) ── */
    .btn-primary,.btn-secondary,.btn-sm,.topbar-btn,.lang-toggle,.tab-btn,.toggle-btn,.filter-select,.pay-toggle,.cust-bnav-btn{
      -webkit-tap-highlight-color:transparent;touch-action:manipulation;
    }
    .btn-primary:active,.btn-secondary:active{transform:scale(.97);}
    @media(max-width:767px){
      .topbar-btn,.lang-toggle{min-height:44px;}      /* HIG minimum touch target */
      .actions-cell .btn-sm{min-height:44px;}          /* session/booking row actions stay tappable */
    }

    /* ── Staff Dashboard ── */
    .dash-kpi{display:flex;flex-direction:column;align-items:flex-start;gap:2px;text-align:start;background:linear-gradient(155deg,rgba(var(--tint-rgb),.045),var(--s1) 62%);border:1px solid var(--border);border-radius:var(--sf-r-ctl);padding:18px 20px;cursor:pointer;font-family:var(--font-body);box-shadow:0 1px 3px rgba(16,19,18,.06);transition:transform .18s ease,border-color .18s ease,box-shadow .18s ease;}
    .dash-kpi:hover{transform:translateY(-3px);border-color:rgba(var(--green-rgb),.28);box-shadow:0 12px 28px rgba(16,19,18,.12);}
    @media(max-width:480px){.dash-kpi{padding:14px 16px;}}

    /* ── Sessions two-pane (iPad/desktop list+detail) + master-detail (phone) ── */
    .sess-twopane{display:grid;grid-template-columns:minmax(260px,340px) 1fr;gap:16px;align-items:start;}
    .sess-list-pane{min-width:0;}
    .sess-list-scroll{display:flex;flex-direction:column;gap:8px;max-height:calc(100vh - 300px);max-height:calc(100dvh - 300px);overflow-y:auto;padding-inline-end:2px;-webkit-overflow-scrolling:touch;}
    .sess-lc{display:block;width:100%;text-align:start;background:var(--s1);border:1px solid var(--border);border-radius:var(--sf-r-ctl);padding:12px 14px;cursor:pointer;font-family:var(--font-body);transition:border-color .15s,background .15s;}
    .sess-lc:hover{border-color:rgba(var(--green-rgb),.35);background:var(--s2);}
    .sess-lc.selected{border-color:var(--green);background:rgba(var(--green-rgb),.08);}
    .sess-lc-top{display:flex;align-items:center;justify-content:space-between;gap:10px;margin-bottom:6px;}
    .sess-lc-date{font-size:15px;font-weight:600;letter-spacing:-.2px;}
    .sess-lc-meta{font-size:11px;color:var(--muted);font-weight:600;margin-bottom:8px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;}
    .sess-lc-meta .sg-chip,.sess-chip-top .sg-chip{font-size:9px;font-weight:600;padding:1px 6px;text-transform:none;letter-spacing:0;} /* who can book, the size of the event's own chip (2026-10-27) */
    .sess-lc-bar{height:4px;border-radius:var(--sf-r-xs);background:var(--border);overflow:hidden;margin-bottom:6px;}
    .sess-lc-bar>div{height:100%;border-radius:var(--sf-r-xs);transition:width .25s;}
    .sess-lc-count{font-size:var(--sf-fs-xs);color:var(--muted-l);font-weight:600;}
    /* On the picked session's green wash (and the picked layout button's) the muted and green inks fell to 4.2-4.4:1 (a11y gate, staff round s10) */
    html:not([data-staff-theme="dark"]) body.view-staff .sess-lc.selected .sess-lc-count{color:var(--muted);}
    html:not([data-staff-theme="dark"]) body.view-staff .sess-lc.selected .badge-open,html:not([data-staff-theme="dark"]) body.view-staff .sess-view-toggle .view-toggle-btn.active{color:var(--green-h);}
    .sess-detail-pane{background:var(--s1);border:1px solid var(--border);border-radius:var(--sf-r-ctl);padding:20px;min-width:0;}
    .sess-back-btn{display:none;background:none;border:none;color:var(--green);font-family:var(--font-body);font-size:var(--sf-fs-md);font-weight:600;cursor:pointer;padding:0 0 12px;align-items:center;gap:4px;min-height:44px;}
    .sess-detail-head{display:flex;align-items:flex-start;justify-content:space-between;gap:12px;margin-bottom:16px;}
    .sess-detail-date{font-size:var(--sf-fs-xl);font-weight:600;letter-spacing:-.4px;}
    .sess-detail-day{font-size:var(--sf-fs-xs);color:var(--muted);font-weight:600;margin-top:3px;overflow:hidden;text-overflow:ellipsis;}
    .sess-detail-sg{margin-top:6px;}
    .sess-detail-stats{display:flex;gap:10px;flex-wrap:wrap;margin-bottom:16px;}
    .sess-detail-stats>div{background:var(--s3);border:1px solid rgba(var(--tint-rgb),.06);border-radius:var(--sf-r-xs);padding:10px 14px;min-width:74px;}
    .sess-ds-num{font-size:var(--sf-fs-xl);font-weight:600;line-height:1.1;}
    .sess-ds-lbl{font-size:var(--sf-fs-xs);font-weight:600;color:var(--muted);text-transform:none;letter-spacing:0;margin-top:3px;}
    .sess-ds-fleet{flex:2;min-width:120px;}
    .sess-ds-fleetval{font-size:var(--sf-fs-sm);font-weight:600;line-height:1.3;}
    .sess-detail-actions{display:flex;gap:8px;flex-wrap:wrap;margin-bottom:18px;}
    .sess-detail-rtitle{font-size:var(--sf-fs-xs);font-weight:600;text-transform:none;letter-spacing:0;color:var(--muted);margin-bottom:10px;}
    .sess-detail-riders{display:flex;flex-direction:column;gap:6px;}
    .sess-rider{display:flex;align-items:center;gap:10px;padding:9px 12px;background:var(--s2);border:1px solid rgba(var(--tint-rgb),.05);border-radius:var(--sf-r-xs);}
    .sess-rider-q{font-size:var(--sf-fs-xs);font-weight:600;color:var(--muted);min-width:30px;flex-shrink:0;}
    .sess-rider-info{flex:1;min-width:0;}
    .sess-rider-name{font-size:var(--sf-fs-md);font-weight:600;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;}
    .sess-rider-bike{font-size:var(--sf-fs-xs);color:var(--green);font-weight:600;margin-top:1px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;}
    .sess-detail-empty{display:flex;align-items:center;justify-content:center;min-height:220px;}
    @media(max-width:767px){
      .sess-twopane{grid-template-columns:1fr;}
      .sess-list-scroll{max-height:none;overflow:visible;}
      .sess-twopane.has-detail .sess-list-pane{display:none;}
      .sess-twopane:not(.has-detail) .sess-detail-pane{display:none;}
      .sess-back-btn{display:inline-flex;}
      .sess-detail-pane{padding:16px;}
    }

    /* ── Sessions, the booking window and the promo codes without inline styles (2026-09-28, pass 3
       of moving style="..." into classes, so the policy can drop style-src 'unsafe-inline'): the
       list and its detail, the deleted group, the new- and edit-session forms (the bike pickers,
       the fleet counts, the add-ons, the waitlist cap, the breakfast stop, the route), the booking
       window card and the promo codes, all drawn into #tab-sessions. Each rule is scoped by that id,
       so it outranks every class rule (the body.view-staff layer included) as the inline style did.
       Three name it twice: #tab-sessions .sess-admin-table td (and td[colspan]) on phones, and
       body.view-staff #tab-queue .page-title, also set what the promo code table's limits and
       empty cells and its title set. A value known only at run time rides in data-cssv
       (_cssvApply): a bike's colour (--ss-bg) and how full a session is (--ss-w); the bar's colour
       is one of three by how full it is. The pickers' type labels are one quiet colour (no
       per-type accents), as they were. background:none written in a template is
       background:transparent none here: the same value, which the build's minifier keeps. */
    #tab-sessions .ss-mb10{margin-bottom:10px;}
    #tab-sessions .ss-mb14{margin-bottom:14px;}
    #tab-sessions .ss-mb16{margin-bottom:16px;}
    #tab-sessions .ss-mb18{margin-bottom:18px;}
    #tab-sessions .ss-mb20{margin-bottom:20px;}
    #tab-sessions .ss-mb24{margin-bottom:24px;}
    #tab-sessions .ss-mt4{margin-top:4px;}
    #tab-sessions .ss-mt6{margin-top:6px;}
    #tab-sessions .ss-mt18{margin-top:18px;}
    #tab-sessions .ss-mt28{margin-top:28px;}
    #tab-sessions .ss-minw0{min-width:0;}
    #tab-sessions .ss-fs12{font-size:var(--sf-fs-xs);}
    #tab-sessions .ss-fs16{font-size:var(--sf-fs-lg);}
    #tab-sessions .ss-b800{font-weight:600;}
    #tab-sessions .ss-c-green{color:var(--green);}
    #tab-sessions .ss-c-muted{color:var(--muted);}
    #tab-sessions .ss-c-red{color:var(--red);}
    #tab-sessions .ss-c-text{color:var(--text);}
    #tab-sessions .ss-head-btns{display:flex;align-items:center;gap:8px;flex-wrap:wrap;}
    #tab-sessions .ss-fill{width:var(--ss-w);}
    #tab-sessions .ss-fill-ok{background:#0c7a3d;}
    #tab-sessions .ss-fill-high{background:#8a5c14;}
    #tab-sessions .ss-fill-full{background:#a33b2e;}
    #tab-sessions .ss-noriders{padding:18px;font-size:var(--sf-fs-sm);}
    #tab-sessions .ss-p8{padding:8px;}
    #tab-sessions .ss-dash{color:var(--muted);font-weight:600;}
    #tab-sessions .ss-left{color:var(--muted);font-size:var(--sf-fs-xs);}
    #tab-sessions .ss-fleet{font-size:var(--sf-fs-xs);color:var(--muted);margin-top:2px;}
    #tab-sessions .ss-meta{font-size:var(--sf-fs-xs);color:var(--muted);}
    #tab-sessions .ss-del-toggle{display:flex;align-items:center;gap:8px;background:transparent none;border:none;cursor:pointer;font-family:var(--font-body);font-size:var(--sf-fs-sm);font-weight:600;color:var(--muted);padding:0;margin-bottom:12px;}
    #tab-sessions .ss-purge-row{display:flex;justify-content:flex-end;margin-bottom:10px;}
    #tab-sessions .ss-del-row{opacity:.65;}
    /* the forms */
    #tab-sessions .ss-edit{margin-bottom:24px;border-color:rgba(var(--green-rgb),.25);}
    #tab-sessions .ss-mw110{max-width:110px;}
    #tab-sessions .ss-mw140{max-width:140px;}
    #tab-sessions .ss-mw240{max-width:240px;}
    #tab-sessions .ss-mw340{max-width:340px;}
    /* places per bike type beside the bike count (2026-11-11): one small box per type, the sum said when over the total */
    #tab-sessions .ss-tcap{border:0;padding:0;margin:0 0 16px;min-width:0;}
    #tab-sessions .ss-tcap legend{padding:0;margin-bottom:6px;font-size:var(--staff-fs-sm);font-weight:600;color:var(--muted);}
    #tab-sessions .ss-tcap-row{display:flex;flex-wrap:wrap;gap:8px 12px;}
    #tab-sessions .ss-tcap-f{display:flex;flex-direction:column;gap:4px;width:96px;}
    #tab-sessions .ss-tcap-over{margin:6px 0 0;font-size:var(--staff-fs-sm);font-weight:600;color:var(--warn);}
    #tab-sessions .ss-tcap-over:empty{display:none;}
    #tab-sessions .ss-datewarn{font-size:var(--sf-fs-xs);color:var(--muted-l);margin-top:5px;font-weight:600;}
    #tab-sessions .ss-times{display:flex;align-items:center;gap:8px;margin-top:4px;}
