    /* Pull-to-refresh indicator */
    #ptr-ind{position:fixed;top:env(safe-area-inset-top,0);left:50%;transform:translateX(-50%) translateY(-64px);z-index:9998;width:38px;height:38px;border-radius:50%;background:var(--s2);border:1px solid var(--border);box-shadow:0 4px 14px rgba(16,19,18,.1);display:flex;align-items:center;justify-content:center;opacity:0;transition:opacity .2s ease;pointer-events:none;}
    #ptr-ind .ptr-spin{width:18px;height:18px;border-radius:50%;border:2.5px solid var(--border);border-top-color:var(--green);}
    #ptr-ind.refreshing .ptr-spin{animation:ptrspin .7s linear infinite;}
    @keyframes ptrspin{to{transform:rotate(360deg);}}

    /* Phone fixes: Fleet header "Add Bike" button must never overflow (wraps to its own full-width row);
       session-detail action buttons go 2-up so none get clipped. */
    @media(max-width:480px){
      #tab-bikes .section-header > div:last-child{flex-wrap:wrap;gap:8px;width:100%;}
      #tab-bikes .section-header .view-toggle{flex:0 0 auto;}
      #tab-bikes .section-header .btn-primary{flex:1 1 100%;min-height:44px;}
      .sess-detail-actions .btn-sm{flex:1 1 calc(50% - 4px);min-height:44px;}
    }

    /* RTL phones: the base rule (html[dir="rtl"] .section-header{flex-direction:row}) keeps the header a
       horizontal row, pushing the action button and the page off-screen. Stack it like LTR so nothing overflows. */
    @media(max-width:767px){
      html[dir="rtl"] .section-header{flex-direction:column;align-items:stretch;}
      html[dir="rtl"] .section-header>div{text-align:start;}
      /* Dialog buttons stack on a phone in Arabic and Urdu too (the old RTL row-reverse outranked the
         phone rule and kept a squeezed row; that rule is gone, this keeps the stacked order). */
      html[dir="rtl"] .modal-footer{flex-direction:column-reverse;}
    }
    /* Wide tables scroll inside their own wrapper instead of widening the whole page */
    .table-wrapper{max-width:100%;}

    .analytics-kpi-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:12px;margin-bottom:24px;}
    @media(max-width:1023px){.analytics-kpi-grid{grid-template-columns:repeat(2,1fr);}}
    @media(max-width:480px){.analytics-kpi-grid{grid-template-columns:1fr 1fr;gap:8px;}}
