    /* Accessibility: visible keyboard focus (mouse clicks stay clean via :focus-visible) */
    :focus-visible{outline:2px solid var(--green);outline-offset:2px;border-radius:4px;}
    a:focus-visible,button:focus-visible,input:focus-visible,select:focus-visible,textarea:focus-visible,[tabindex]:focus-visible,[role="button"]:focus-visible{outline:2px solid var(--green);outline-offset:2px;}
    :root[data-theme="light"] :focus-visible{outline-color:var(--green-d);}
    /* Respect users who ask for less motion */
    @media (prefers-reduced-motion: reduce){
      *,*::before,*::after{animation-duration:1e-6s !important;animation-iteration-count:1 !important;transition-duration:1e-6s !important;scroll-behavior:auto !important;}
    }

    /* Low-stock count badge on the Inventory staff tab */
    /* Thumb-reachable primary action: the sale total + Record button stick to the bottom of the
   viewport on phones so a long cart never buries the main action. Styled like the topbar. */
@media (max-width:720px){
  .mm-cart-foot,.mm-reg-foot{position:sticky;bottom:0;z-index:20;margin-top:8px;
    padding:8px 4px calc(8px + env(safe-area-inset-bottom));
    background:var(--bg);border-top:1px solid var(--border);
    -webkit-backdrop-filter:blur(14px);backdrop-filter:blur(14px);
    box-shadow:0 -10px 20px -12px rgba(0,0,0,.55);}
}
    /* Perf: let the browser skip rendering + layout for off-screen cards (big analytics lists).
   contain-intrinsic-size 'auto <len>' remembers the real size once rendered, so the
   scrollbar stays stable. Not on .sess-card: the session picker is a grid of 1fr rows, and an
   off-screen card's 100px placeholder set the height of EVERY row - the cards opened at twice
   their size and collapsed under the rider's finger once the last one scrolled into view. */
.chart-card{content-visibility:auto;contain-intrinsic-size:auto 240px;}
    .tab-badge{display:inline-flex;align-items:center;justify-content:center;min-width:16px;height:16px;padding:0 4px;border-radius:3px;background:var(--orange);color:#1a1200;font-size:10px;font-weight:700;line-height:1;vertical-align:middle;}

    /* ── iPhone / iOS UI enhancements ─────────────────────────────────────── */
    /* Prevent Safari's zoom-on-focus: any focusable control under 16px makes iOS
       zoom in and shift the layout. 16px on touch widths stops it (!important to
       beat inline font-sizes on some fields). */
    @media (max-width: 767px) {
      input, select, textarea { font-size: 16px !important; }
    }
    /* Installed PWA: the translucent status bar lets content sit under the notch /
       Dynamic Island. Reserve that space at the top of the sticky header. */
    @media all and (display-mode: standalone) {
      #topbar { padding-top: env(safe-area-inset-top); height: calc(64px + env(safe-area-inset-top)); }
    }
    @media all and (display-mode: standalone) and (max-width: 767px) {
      #topbar { height: calc(52px + env(safe-area-inset-top)); }
    }
    /* Comfortable tap targets for the customer's primary controls on phones. */
    @media (max-width: 767px) {
      .btn-primary, .btn-secondary { min-height: 46px; }
    }

    /* ── Display numerals: Chakra Petch (race-timing numerals), tabular so digits align ── */
    .landing-main-title span,.queue-num-cell,.pos-badge,.ticket-num,
    .stat-num,.rides-stat-num,.analytics-kpi-value,
    .sess-ds-num,.hl-value,.price-preview-total,.type-count-input,
