#race-gate .defe-reg-yn{margin-top:14px;}
#race-gate .defe-reg-no{margin-top:12px;}
#race-gate .pg-btn{margin-top:14px;}
/* Victory Lap: a ticket, or buy one (#vl-ticket-gate, renderVtGate, 2026-10-23): the question with both
   answers; buying shows the organiser's bank details, their letter and the receipt upload. */
#vl-ticket-gate .auth-backdrop{overflow-y:auto;overscroll-behavior:contain;padding:20px 14px;z-index:199;}
#vl-ticket-gate .vt-box{position:relative;}
#vl-ticket-gate .vt-box:focus,#vl-ticket-gate .vt-box:focus-visible{outline:none;}
#vl-ticket-gate .vt-x{position:absolute;top:10px;inset-inline-end:10px;}
#vl-ticket-gate .vt-q{margin-top:16px;font-weight:600;}
.vt-yn{display:grid;gap:8px;margin-top:14px;}
.vt-yn .toggle-btn{min-height:48px;border-radius:0;}
.vt-bank{display:grid;margin-top:14px;border:1px solid var(--line);background:var(--card);}
.vt-row{display:grid;grid-template-columns:minmax(0,1fr) auto;align-items:center;gap:2px 10px;padding:10px 12px;}
.vt-row+.vt-row{border-top:1px solid var(--line);}
.vt-k{grid-column:1/-1;font-size:12px;font-weight:600;color:var(--muted);}
.vt-v{font-size:15px;font-weight:700;overflow-wrap:anywhere;unicode-bidi:isolate;}
.vt-cp{border-radius:0;}
.vt-pdf{display:flex;align-items:center;justify-content:center;gap:8px;min-height:44px;margin-top:10px;border-radius:0;text-decoration:none;}
.vt-rc{display:grid;gap:8px;margin-top:16px;}
.vt-rc-l{font-size:14px;font-weight:700;}
.vt-pick{display:flex;align-items:center;justify-content:center;gap:8px;min-height:44px;border-radius:0;cursor:pointer;}
.vt-pick:focus-within{outline:2px solid var(--green);outline-offset:2px;}
.vt-prev{display:block;max-width:100%;max-height:240px;margin:0 auto;border:1px solid var(--line);object-fit:contain;}
.vt-done{display:flex;align-items:center;gap:8px;font-size:13.5px;font-weight:600;color:#06603b;}
#vl-ticket-gate .pg-btn{margin-top:14px;}
.vt-foot{display:flex;justify-content:space-between;gap:10px;margin-top:12px;}
.vt-link{display:inline-flex;align-items:center;gap:4px;min-height:40px;padding:0 4px;background:none;border:0;font:inherit;font-size:14px;font-weight:600;color:var(--muted);cursor:pointer;text-decoration:underline;}
.sg-list{list-style:none;display:flex;flex-direction:column;gap:8px;margin-top:10px;border:1px solid var(--line);border-radius:12px;padding:14px;background:var(--card);}
.sg-list li{display:flex;align-items:center;gap:10px;font-weight:600;font-size:14px;line-height:1.35;color:var(--ink);overflow-wrap:anywhere;}
.sg-list .cu-ic{flex-shrink:0;color:var(--go);}
.sg-note{margin-top:10px;font-size:12.5px;line-height:1.45;color:var(--ink-2);}
.rg-bfn{margin-top:-4px;font-size:12px;line-height:1.4;color:var(--ink-2);}
/* Community row: a rider's social profiles, staff-side */
.soc-links{display:flex;gap:6px;margin-top:4px;flex-wrap:wrap;}
.soc-link{display:inline-flex;align-items:center;gap:5px;height:24px;padding:0 9px 0 7px;border-radius:var(--sf-r-pill,var(--sf-r-pill));border:1px solid var(--border);color:var(--text);text-decoration:none;font-size:var(--staff-fs-sm,12px);font-weight:600;}
.soc-link svg{width:12px;height:12px;flex-shrink:0;color:var(--muted);}
.soc-link:hover{color:var(--green);border-color:var(--green);}
.soc-link:hover svg{color:var(--green);}
.ig-chip{background:transparent;font-family:inherit;cursor:pointer;}
.ig-chip.ig-none{color:var(--muted);border-style:dashed;}
/* Against the community's average (2026-10-09): --igh is the hue (0 red, 50 yellow, 135 green), --iga how deep the
   tint is; the text keeps the page's ink, the triangle and the border carry the colour. */
.ig-chip.ig-tone{border-color:hsl(var(--igh) 70% 38% / .8);background:hsl(var(--igh) 85% 48% / var(--iga));}
.ig-chip.ig-tone .ig-arw{color:hsl(var(--igh) 80% 30%);flex:none;}
/* the staff dark theme only: data-theme="dark" is on every page (the head script), so keyed on it these light inks
   painted the triangle at 62% lightness on the white paper too (about 1.7:1 at the yellow, the average) */
html[data-staff-theme="dark"] .ig-chip.ig-tone{border-color:hsl(var(--igh) 65% 55% / .85);}
html[data-staff-theme="dark"] .ig-chip.ig-tone .ig-arw{color:hsl(var(--igh) 75% 62%);}
.ca-soc{display:inline-flex;flex-wrap:wrap;gap:6px;align-items:center;}
.soc-field{display:flex;align-items:center;gap:6px;}
.soc-field input{flex:1;min-width:0;}
.soc-open{flex-shrink:0;font-size:var(--staff-fs-sm,12px);font-weight:800;color:var(--green);text-decoration:none;white-space:nowrap;padding:6px 4px;}
.soc-open:hover{text-decoration:underline;}
    /* ── The social fields (_socFieldsHtml) on the account page and in the staff customer form
       (#new-acct-modal): without inline styles (2026-09-29, the customer pages' pass; scoped by that id). */
    #new-acct-modal .cu-fs11,#tab-account .cu-fs11{font-size:11px;}
    #new-acct-modal .cu-m0,#tab-account .cu-m0{margin:0;}
    #new-acct-modal .cu-soc-grid,#tab-account .cu-soc-grid{display:grid;grid-template-columns:1fr 1fr;gap:8px;margin-top:6px;}
/* the sentence by the + / - when a JCC party would pass the account's three */
.qty-cap-note{font-size:12px;font-weight:700;color:var(--orange);text-align:end;max-width:220px;line-height:1.35;}
/* the signed-in avatar + name in the header is the way to My Account */
.cust-topbar-link{display:flex;align-items:center;gap:10px;background:none;border:none;padding:4px 6px;margin:0 -6px;border-radius:8px;cursor:pointer;font-family:var(--font-body);text-align:start;color:inherit;min-width:0;}
.cust-topbar-link:hover{background:rgba(var(--green-rgb),.08);}
.cust-topbar-link:hover .cust-topbar-name{color:var(--green);}
.cust-topbar-name{display:block;}
@media(min-width:768px){.cust-topbar-email{display:block;}} /* phones keep the email out of the header (the 767px rule hides it; a bare display:block here outranked it) */
/* Reserved: a waiting rider with a bike held for them - its own colour, apart from plain Waiting */
.badge-reserved{color:#1d4ed8;}
body.view-staff .badge-reserved{color:#1e40af;}
.queue-table tbody tr.row-reserved{background:rgba(29,78,216,.05);}
body.view-staff .queue-table tbody tr.row-reserved{background:rgba(29,78,216,.05);}
.q-card.row-reserved{background:rgba(29,78,216,.04);border-color:rgba(29,78,216,.3);}
body.view-staff .q-card.row-reserved{background:rgba(29,78,216,.04);border-color:rgba(29,78,216,.3);}
/* ── Staff queue, second pass ── */
@media (max-width:767px){
  body.view-staff :is(#tab-queue,#tab-waitlist,#tab-sessions) .page-title{font-size:var(--sf-fs-lg);margin-bottom:0;letter-spacing:-.5px;}
  body.view-staff :is(#tab-queue,#tab-waitlist,#tab-sessions) .section-header{margin-bottom:12px;}
  body.view-staff :is(#tab-queue,#tab-waitlist,#tab-sessions) .section-header>div:first-child{display:flex;align-items:baseline;gap:10px;}
  body.view-staff :is(#tab-queue,#tab-waitlist) .refresh-indicator{margin-top:0 !important;}
  /* Every queue action stays on the phone. They do not fit side by side on a 390px screen and
     wrapping them stacked four rows of buttons above the roster, so the row scrolls sideways
     instead — the first two or three are in reach, the rest a swipe away. */
  .sf-head-actions{flex-wrap:nowrap !important;justify-content:flex-start !important;
    overflow-x:auto;-webkit-overflow-scrolling:touch;scrollbar-width:none;padding-bottom:2px;}
  .sf-head-actions::-webkit-scrollbar{display:none;}
  .sf-head-actions>*{flex:0 0 auto;}
  /* Print Report carries its own padding, not .btn-sm's — match the rest of the strip */
  .sf-head-actions>button{min-height:44px;display:inline-flex;align-items:center;gap:6px;}
}
/* tonight's ride leads the strip and takes the room; the others stay compact beside it */
.sess-summary-chip.today-sess{flex:1 1 340px;max-width:none;padding:14px 16px;border-color:rgba(var(--green-rgb),.35);}
.sess-summary-chip.today-sess .sess-chip-date{font-size:var(--sf-fs-md);font-weight:600;}
/* the finished part of the night, folded to one line */
.queue-table tbody tr.fold-row td{padding:6px 12px;background:var(--s3);}
.fold-btn{background:none;border:1px dashed var(--border);border-radius:var(--sf-r-pill,var(--sf-r-pill));padding:6px 14px;font-family:var(--font-body);font-size:var(--sf-fs-xs);font-weight:600;color:var(--muted);cursor:pointer;}
.fold-btn:hover{color:var(--text);border-color:var(--text);}
.fold-card{display:block;width:100%;margin:6px 0 10px;}
/* a party as one row; members come out on Show riders */
.party-toggle{background:none;border:none;padding:4px 0 0;font-family:var(--font-body);font-size:var(--staff-fs-sm,12px);font-weight:600;color:var(--green);cursor:pointer;white-space:nowrap;}
.party-toggle:hover{text-decoration:underline;}
.queue-table tbody tr.party-row td{vertical-align:middle;}

/* tablets: the table scrolls sideways inside its box; the booking number stays put */
@media (min-width:768px) and (max-width:1023px){
  .queue-table-desktop-wrap .queue-table th:first-child,.queue-table-desktop-wrap .queue-table td:first-child{position:sticky;inset-inline-start:0;z-index:3;background:var(--s1);box-shadow:1px 0 0 var(--border);}
  html[dir="rtl"] .queue-table-desktop-wrap .queue-table th:first-child,html[dir="rtl"] .queue-table-desktop-wrap .queue-table td:first-child{box-shadow:-1px 0 0 var(--border);}
  /* The other header cells are z-index 3 as well and come later in the row, so they painted
     over the pinned "#" as they scrolled under it. The pinned one sits a layer above them,
     in the header colour rather than the row colour. */
  .queue-table-desktop-wrap .queue-table th:first-child{z-index:4;}
  body.view-staff .queue-table-desktop-wrap .queue-table thead th:first-child{background:var(--sf-head);}
}
/* the chips' delta against the same night last week */
.stat-delta{font-style:normal;font-size:var(--staff-fs-sm,12px);font-weight:600;margin-inline-start:6px;color:var(--muted-l);}
.stat-delta.up{color:var(--green);}
.stat-delta.down{color:var(--orange);}
/* bikes out past two hours */
.overdue-banner{display:flex;align-items:center;justify-content:space-between;gap:10px;margin:0 0 12px;padding:9px 14px;background:rgba(var(--warn-rgb),.1);border:1px solid rgba(var(--warn-rgb),.35);border-radius:var(--sf-r-ctl);font-size:var(--sf-fs-sm);font-weight:600;color:var(--orange);}
.am-missing{color:var(--orange);font-weight:600;}
/* Ask to correct (staff): the report builder's layout, pointed at an account's fields */
.am-fix{color:var(--orange);font-weight:600;display:flex;align-items:center;gap:4px;}
.am-sx{color:var(--red);font-weight:600;display:flex;align-items:baseline;gap:8px;flex-wrap:wrap;white-space:normal;}
.am-fine{background:none;border:1px solid var(--border);border-radius:var(--sf-r-pill,var(--sf-r-pill));padding:1px 9px;font:inherit;font-size:var(--staff-fs-sm,12px);font-weight:600;color:var(--muted);cursor:pointer;}
.am-fine:hover{color:var(--text);border-color:var(--muted);}
.fl-sx{font-size:var(--staff-fs-sm,12px);font-weight:600;color:var(--red);line-height:1.35;white-space:normal;}
.am-flag.on,.fl-open.on{color:var(--orange);border-color:var(--orange);}
.fl-open{display:inline-flex;align-items:center;gap:6px;white-space:nowrap;}
.fl-cf-head{display:flex;align-items:center;justify-content:space-between;gap:10px;flex-wrap:wrap;}
.cf-head-btns{display:inline-flex;align-items:center;gap:6px;flex-wrap:wrap;}
.cf-head-btns .btn-sm{display:inline-flex;align-items:center;gap:6px;white-space:nowrap;}
/* Why a rider cancelled: under the badge on the roster, in Bookings & history, in Analytics */
.cx-why{font-size:var(--staff-fs-sm,12px);color:var(--muted);font-weight:600;margin-top:3px;max-width:200px;white-space:normal;overflow-wrap:anywhere;}
.ah-rider-sub .cx-why{display:inline;margin:0;font-size:inherit;}
.cx-pick{margin-top:12px;font-weight:600;color:var(--text);}
.cx-pick-lbl{font-size:var(--staff-fs-sm,12px);font-weight:600;letter-spacing:0;text-transform:none;color:var(--muted);margin-bottom:6px;}
.cx-chips{display:flex;flex-wrap:wrap;gap:6px;}
.cx-chip{border:1px solid var(--border);background:var(--s1);color:var(--text);border-radius:var(--sf-r-pill,var(--sf-r-pill));padding:5px 10px;font:inherit;font-size:var(--sf-fs-xs);font-weight:600;cursor:pointer;text-align:start;}
.cx-chip:hover{border-color:var(--muted);}
.cx-chip.on{border-color:var(--red);background:rgba(var(--red-rgb),.1);color:var(--red);}
.cx-note{margin-top:8px;width:100%;font-size:var(--sf-fs-sm);}
.cx-words-title{font-size:var(--staff-fs-sm,12px);font-weight:600;letter-spacing:0;text-transform:none;color:var(--muted);margin:14px 0 6px;}
.cx-word{font-size:var(--sf-fs-sm);color:var(--text);padding:6px 0;border-bottom:1px solid var(--border);overflow-wrap:anywhere;}
.cx-word span{font-size:var(--staff-fs-sm,12px);color:var(--muted);margin-inline-start:6px;}
/* A Petromin night on Bookings is one card (2026-11-12, the user: "put them in one session card with tiles to choose
   which panel we want or which company we want"): the night's lines, then a row of tiles - its Bookings, and each
   company's registrations with the company's mark. It is a group of buttons, not a button: no pointer of its own. On
   the Bookings grid it takes two columns, the night's lines in the first and the tiles two by two in the second, so it
   stands no taller than the cards beside it (a grid row grows every card in it to its tallest: the tiles under the
   lines made the whole row 158px, against the four short lines the user asked for on 2026-11-10). */
.sess-summary-chip.pm-night{cursor:default;flex-direction:column;align-items:stretch;}
.sess-summary-chip.pm-night:hover{background:var(--s1);}
body.view-staff :is(#tab-queue,#tab-waitlist) .sess-bar-desktop .sess-summary-chip.pm-night{grid-column:span 2;display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:0 10px;align-items:start;}
body.view-staff :is(#tab-queue,#tab-waitlist) .sess-bar-desktop .pm-night .pm-tiles{grid-template-columns:1fr 1fr;gap:4px;margin-top:0;}
.pm-tiles{display:grid;grid-template-columns:repeat(auto-fit,minmax(84px,1fr));gap:6px;margin-top:6px;}
.pm-tile{display:flex;flex-direction:column;align-items:flex-start;justify-content:space-between;gap:1px;min-width:0;min-height:34px;margin:0;padding:2px 7px;
  border:1px solid var(--sf-line,var(--border));border-radius:var(--sf-r-ctl);background:var(--sf-card,var(--s1));color:var(--text);
  font:inherit;text-align:start;letter-spacing:inherit;text-transform:none;cursor:pointer;}
.pm-tile:hover{border-color:rgba(var(--green-rgb),.45);}
.pm-tile.on{border-color:var(--green);box-shadow:inset 0 0 0 1px var(--green);background:rgba(var(--green-rgb),.08);}
.pm-tile:focus-visible{outline:2px solid var(--green);outline-offset:2px;}
.pm-tile-h{display:flex;align-items:center;min-height:16px;max-width:100%;}
/* the marks sit on a white plate of their own, so a dark card keeps them legible */
.pm-tile-logo{display:block;height:12px;width:auto;max-width:100%;object-fit:contain;background:#fff;border-radius:var(--sf-r-xs,4px);padding:2px 4px;box-sizing:content-box;}
.pfs-form-logo{display:block;height:18px;width:auto;max-width:100%;object-fit:contain;background:#fff;border-radius:var(--sf-r-xs,4px);padding:2px 4px;box-sizing:content-box;}
.pm-tile-lbl{font-size:var(--sf-fs-xs,12px);font-weight:600;color:var(--text);white-space:nowrap;overflow:hidden;text-overflow:ellipsis;max-width:100%;}
.pm-tile-n{font-size:var(--sf-fs-xs,11px);line-height:1.15;font-weight:600;color:var(--muted);white-space:nowrap;overflow:hidden;text-overflow:ellipsis;max-width:100%;font-variant-numeric:tabular-nums;}
.pm-tile.on .pm-tile-n{color:var(--green);}
/* The Petromin page's heading carries the marks of the company on show (all of them when every company is) */
.pm-title{display:flex;align-items:center;gap:10px;flex-wrap:wrap;}
.pm-logo-lg{height:36px;width:auto;display:block;flex-shrink:0;}
/* Form steps: which form's steps (Petromin or Dukan) */
.pfs-forms{display:flex;gap:8px;margin:2px 0 10px;}
.pfs-form{display:flex;align-items:center;justify-content:center;min-height:40px;min-width:88px;padding:6px 10px;margin:0;border:1px solid var(--sf-line,var(--border));border-radius:var(--sf-r-ctl);background:var(--sf-card,var(--s1));cursor:pointer;font:inherit;}
.pfs-form.on{border-color:var(--green);box-shadow:inset 0 0 0 1px var(--green);}
.pfs-form:focus-visible{outline:2px solid var(--green);outline-offset:2px;}
/* The Petromin page without inline styles (2026-09-28, the inventory pass of moving style="..."
   into classes, so the policy can drop style-src 'unsafe-inline'): renderRiders' list, drawn into
   #pm-host. Each rule is scoped by that id, so it outranks every class rule (the body.view-staff
   layer included) as the inline style did. The booking pop-up and the walk-in form are beside
   .rw-dup. */
#pm-host .iv-party{border-inline-start:2px solid rgba(var(--green-rgb),.2);}
#pm-host .iv-bno{font:inherit;font-variant-numeric:tabular-nums;font-weight:600;cursor:pointer;border:0;} /* the font shorthand first: after it, it reset the digits' width (2026-10-07) */
#pm-host .iv-pof{font-size:var(--staff-fs-sm,12px);color:var(--muted);margin-top:3px;}
#pm-host .iv-pcount{font-size:var(--staff-fs-sm,12px);color:var(--green);font-weight:600;margin-top:3px;}
#pm-host .iv-pbtn{margin-top:4px;white-space:nowrap;}
#pm-host .iv-sub{font-size:var(--staff-fs-sm,12px);color:var(--muted);}
/* 2026-10-09 (M20): the registration's employee id against its company's list */
#pm-host .iv-roster{display:inline-block;margin-top:3px;padding:1px 6px;border-radius:var(--sf-r-xs);font-size:var(--staff-fs-sm,12px);font-weight:600;border:1px solid currentColor;}
#pm-host .iv-roster.ok{color:var(--green);}
#pm-host .iv-roster.left{color:var(--orange);}
#pm-host .iv-roster.no{color:var(--red);}
#pm-host .iv-fs12{font-size:var(--sf-fs-xs);}
#pm-host .iv-link{color:var(--green);}
#pm-host .iv-muted{color:var(--muted);}
#pm-host .iv-nowrap{white-space:nowrap;}
#pm-host .iv-types{display:flex;gap:4px;flex-wrap:wrap;}
#pm-host .iv-p8{padding:8px;}
#pm-host .iv-o7{opacity:.7;}
/* two ids: body.view-staff #tab-queue .section-header sets the margin on phones */
#pm-host#pm-host .iv-mb8{margin-bottom:8px;}
#pm-host .iv-mb0{margin-bottom:0;}
#pm-host .iv-pm-btns{display:flex;gap:8px;align-items:center;flex-shrink:0;}
/* Returning several bikes at once: one row per bike, OK unless tapped otherwise */
.br-box{max-width:560px;}
.br-list{margin-top:12px;border-top:1px solid var(--border);}
.br-row{display:flex;align-items:center;justify-content:space-between;gap:8px 10px;padding:9px 0;border-bottom:1px solid var(--border);flex-wrap:wrap;}
.br-who{display:flex;align-items:center;gap:10px;min-width:0;flex:1 1 200px;}
.br-num{font-size:var(--sf-fs-md);min-width:40px;}
.br-name{min-width:0;font-weight:600;font-size:var(--sf-fs-sm);overflow-wrap:anywhere;}
.br-bike{font-size:var(--staff-fs-sm,12px);color:var(--muted);font-weight:600;}
.br-owe{font-size:var(--staff-fs-sm,12px);font-weight:600;color:var(--orange);white-space:nowrap;margin-inline-start:auto;}
.br-segs{display:inline-flex;border:1px solid var(--border);border-radius:var(--sf-r-ctl,var(--sf-r-ctl));overflow:hidden;flex-shrink:0;}
.br-seg{background:none;border:0;border-inline-start:1px solid var(--border);padding:6px 10px;font:inherit;font-size:var(--staff-fs-sm,12px);font-weight:600;color:var(--muted);cursor:pointer;white-space:nowrap;}
.br-seg:first-child{border-inline-start:0;}
.br-seg:hover{color:var(--text);}
.br-seg.on.ok{background:rgba(var(--green-rgb),.12);color:var(--green);}
.br-seg.on.needs_check{background:rgba(var(--warn-rgb),.14);color:var(--orange);}
.br-seg.on.damaged{background:rgba(var(--red-rgb),.12);color:var(--red);}
.br-pay{margin-top:14px;padding:12px;border:1px solid rgba(var(--warn-rgb),.4);border-radius:var(--sf-r-ctl,var(--sf-r-ctl));background:rgba(var(--warn-rgb),.06);}
.br-pay-q{font-weight:600;font-size:var(--sf-fs-sm);color:var(--text);}
/* Bookings & history (staff): one account's current bookings over its past ones */
.am-hist{display:inline-flex;align-items:center;justify-content:center;gap:4px;min-width:50px;}
.am-hist.on,.am-cw-btn.on,body.view-staff .am-hist.on,body.view-staff .am-cw-btn.on{color:var(--green);border-color:rgba(var(--green-rgb),.55);}
body.view-staff .am-hist.on,body.view-staff .am-cw-btn.on{color:var(--sf-green-ink,var(--green));}
.am-hist-n{font-size:var(--staff-fs-sm,12px);font-weight:600;line-height:1;}
.ah-box{max-width:620px;}
.ah-head{display:flex;align-items:flex-start;justify-content:space-between;gap:10px;}
.ah-who{min-width:0;}
.ah-who .modal-title{margin-bottom:2px;overflow-wrap:anywhere;}
.ah-who .modal-sub{margin-bottom:0;overflow-wrap:anywhere;}
