/* the rider's two groups: one per row, so 'Intermediates’ group · 40 km' is read whole on a phone */
#reg-group-wrap .rg-grid{grid-template-columns:1fr}
.ca-pwd-box{display:flex;align-items:center;justify-content:space-between;gap:10px;flex-wrap:wrap;padding:10px 14px;border-radius:var(--sf-r-card,var(--sf-r-card));border:1px dashed rgba(var(--green-rgb),.5);background:rgba(var(--green-rgb),.06);margin-bottom:12px}
.ca-pwd-box span{font-size:var(--staff-fs-sm,12px);font-weight:600;letter-spacing:0;text-transform:uppercase;color:var(--muted)}
.ca-pwd{font-family:ui-monospace,SFMono-Regular,Menlo,Consolas,monospace;font-size:var(--sf-fs-xl);letter-spacing:0}
