.ca-msg-box .ca-wa-opt{display:flex;align-items:center;gap:8px;margin:0 0 10px;font-size:var(--sf-fs-sm);font-weight:600;letter-spacing:0;text-transform:none;color:var(--text);cursor:pointer}
