.ca-fx-fields{margin-bottom:14px}
.ca-fx-note textarea{width:100%;min-height:64px;resize:vertical;box-sizing:border-box;font:inherit}
/* The applicant's page (#app-fix) wears the correction request's card; the staff note is a quote */
.afx-note{margin:14px 0 16px;padding:10px 12px;border-radius:8px;background:#f4f5f2;border-inline-start:3px solid #e08a00;font-size:13.5px;line-height:1.5;color:#1c2126;overflow-wrap:anywhere}
