/* A learn-to-ride sign-up's priority (2026-10-04): four choices on the card, the one picked filled
   in its colour; Critical and High also mark the card's edge. */
:is(#tab-community,#tab-customers,#tab-analytics) .la-prio{display:flex;align-items:center;flex-wrap:wrap;gap:6px;margin-top:10px}
:is(#tab-community,#tab-customers,#tab-analytics) .la-prio-l{font-size:var(--staff-fs-sm,12px);font-weight:600;letter-spacing:0;text-transform:none;color:var(--muted);margin-inline-end:4px}
:is(#tab-community,#tab-customers,#tab-analytics) .la-prio-o{--pc:var(--muted);display:inline-flex;align-items:center;gap:6px;min-height:30px;padding:0 12px;border-radius:var(--sf-r-pill,var(--sf-r-pill));border:1.5px solid var(--border);background:transparent;color:var(--text);font:inherit;font-size:var(--sf-fs-sm);font-weight:600;line-height:1.2;cursor:pointer}
