@media(max-width:767px){:is(#tab-community,#tab-customers,#tab-analytics) .la-prio-l{flex-basis:100%}:is(#tab-community,#tab-customers,#tab-analytics) .la-prio-o{min-height:44px;padding:0 11px}}
