.sm-company{font-weight:600;color:var(--muted)}
.sm-text{white-space:pre-wrap;overflow-wrap:anywhere;font-size:var(--sf-fs-md);line-height:1.55;margin:10px 0 4px;padding:10px 12px;border-radius:var(--sf-r-ctl,var(--sf-r-ctl));background:var(--s3)}
.sm-quote{white-space:pre-wrap;overflow-wrap:anywhere;font-size:var(--sf-fs-sm);line-height:1.5;color:var(--muted-l);padding:8px 12px;border-inline-start:3px solid var(--border);margin-bottom:12px;max-height:140px;overflow:auto}
body .ca-msg-box textarea.sm-reply{min-height:200px;height:200px}
/* Ambassadors (renderAmbassadors): rewards waiting to be handed over. */
.amb-dim{color:var(--muted);font-weight:600}
.amb-reds{margin-top:10px;padding:10px 12px;border-radius:var(--sf-r-ctl,var(--sf-r-ctl));background:rgba(var(--green-rgb),.07);display:flex;flex-direction:column;gap:8px}
.amb-reds > span{font-size:var(--staff-fs-sm,12px);font-weight:600;letter-spacing:0;text-transform:none;color:var(--muted)}
.amb-red{display:flex;align-items:center;gap:8px;flex-wrap:wrap;font-size:var(--sf-fs-sm)}
.amb-red small{color:var(--muted);font-weight:600}
.amb-red-btns{display:inline-flex;gap:6px;margin-inline-start:auto}
/* Vendors (renderVendors, 2026-10-03): the calendar, the competing requests, the venue and date
   dialogs and the tier editor. The cards are the Applications card (ca-*); these add the rest. */
#tab-vendors .vendor-n{display:inline-flex;align-items:center;justify-content:center;min-width:18px;height:18px;padding:0 6px;border-radius:var(--sf-r-ctl,var(--sf-r-ctl));background:var(--orange);color:#fff;font-size:var(--staff-fs-sm,12px);font-weight:600;box-sizing:border-box}
/* the dark desk's --orange is a light amber: white on it read 1.85:1 (bug hunt 2026-10-28) */
html[data-staff-theme="dark"] body.view-staff .apps-kind-n,html[data-staff-theme="dark"] body.view-staff #tab-vendors .vendor-n{color:#1a1200;}
#tab-vendors .vendor-body{margin-top:14px}
.vendor-cal-bar{display:flex;align-items:center;gap:8px;flex-wrap:wrap;margin-bottom:10px}
.vendor-month{font-weight:600;font-size:var(--sf-fs-md);min-width:140px;text-align:center}
.vendor-chev{display:block}
.vendor-next .vendor-chev,.vendor-down .vendor-chev{transform:rotate(180deg)}
.vendor-up .vendor-chev{transform:rotate(90deg)}
.vendor-down .vendor-chev{transform:rotate(-90deg)}
:is(html[lang="ar"],html[lang="ur"]) .vendor-prev .vendor-chev{transform:rotate(180deg)}
:is(html[lang="ar"],html[lang="ur"]) .vendor-next .vendor-chev{transform:none}
.vendor-cal{display:grid;grid-template-columns:repeat(7,minmax(0,1fr));gap:4px}
.vendor-wd{font-size:var(--staff-fs-sm,12px);font-weight:600;color:var(--muted);text-align:center;padding:4px 0;text-transform:none;letter-spacing:0}
#tab-vendors .vendor-day{display:flex;flex-direction:column;align-items:flex-start;gap:2px;min-height:74px;padding:6px 7px;border-radius:var(--sf-r-ctl,var(--sf-r-ctl));border:1px solid var(--border);background:var(--s1);color:var(--text);font:inherit;font-size:var(--staff-fs-sm,12px);text-align:start;min-width:0;overflow:hidden;box-sizing:border-box}
#tab-vendors button.vendor-day{cursor:pointer;transition:border-color .15s,background .15s}
#tab-vendors button.vendor-day:hover,#tab-vendors button.vendor-day:focus-visible{border-color:var(--green)}
#tab-vendors .vendor-day.vendor-blank{border:0;background:transparent}
#tab-vendors .vendor-day.st-off{background:var(--s2);color:var(--muted);border-style:dashed} /* was opacity .6: the day's number fell under 4.5:1 (2026-10-09) */
#tab-vendors .vendor-day.st-open{border-color:rgba(var(--green-rgb),.45)}
#tab-vendors .vendor-day.st-confirmed{background:rgba(var(--green-rgb),.12);border-color:var(--green)}
#tab-vendors .vendor-day.st-closed{background:var(--s3);color:var(--muted)}
#tab-vendors .vendor-day.past{color:var(--muted)} /* was opacity .55: a past Saturday's number fell under 4.5:1 and failed the a11y audit once 10 Oct went by (2026-10-11) */
#tab-vendors .vendor-day.today .vendor-dn{color:var(--green)}
.vendor-dn{font-weight:600;font-size:var(--sf-fs-sm)}
.vendor-ds{font-weight:600}
.vendor-dv{font-weight:600;overflow-wrap:anywhere;line-height:1.3}
.vendor-dp{font-weight:600;color:var(--orange)}
.vendor-grp{padding:12px 0;border-bottom:1px solid var(--border)}
.vendor-grp-h{display:flex;align-items:center;gap:10px;flex-wrap:wrap;margin-bottom:8px;font-size:var(--sf-fs-md)}
.vendor-cmp-n{font-size:var(--sf-fs-xs);font-weight:600;color:var(--orange)}
.vendor-cmp{display:grid;grid-template-columns:repeat(auto-fill,minmax(240px,1fr));gap:10px}
.vendor-bk{padding:10px 12px;border:1px solid var(--border);border-radius:var(--sf-r-card,var(--sf-r-card));background:var(--s1)}
.vendor-bk[data-status="pending"]{border-color:rgba(var(--warn-rgb),.45)}
.vendor-bk[data-status="confirmed"]{border-color:var(--green)}
.vendor-note{margin-top:6px;font-size:var(--sf-fs-sm);line-height:1.45;padding:6px 10px;border-radius:var(--sf-r-ctl,var(--sf-r-ctl));background:var(--s3);white-space:pre-wrap;overflow-wrap:anywhere}
.vendor-dlg.vendor-ven-dlg,.vendor-dlg.vendor-day-dlg{max-width:680px}
.vendor-dlg input[type="date"]{background:var(--s3);border:1px solid var(--border);border-radius:var(--sf-r-xs);padding:11px 14px;color:var(--text);font-family:var(--font-body);font-size:var(--sf-fs-md);width:100%;box-sizing:border-box}
.vendor-form{display:grid;grid-template-columns:repeat(auto-fill,minmax(200px,1fr));gap:0 12px}
.vendor-lbl{font-size:var(--staff-fs-sm,12px);font-weight:800;letter-spacing:.6px;text-transform:uppercase;color:var(--muted);margin:10px 0 6px}
.vendor-mt6{margin-top:6px}
.vendor-sec-h{font-weight:600;font-size:var(--sf-fs-md);margin:18px 0 8px;padding-top:12px;border-top:1px solid var(--border)}
.vendor-ride{margin:4px 0 0;padding:8px 12px;border-radius:var(--sf-r-ctl,var(--sf-r-ctl));background:rgba(var(--green-rgb),.07);font-size:var(--sf-fs-sm);line-height:1.5}
.vendor-ride>span{display:block;font-size:var(--staff-fs-sm,12px);font-weight:600;letter-spacing:0;text-transform:none;color:var(--muted)}
.vendor-bks{display:flex;flex-direction:column;gap:8px}
.vendor-tbl{overflow-x:auto}
.vendor-users{width:100%;border-collapse:collapse;font-size:var(--sf-fs-sm)}
.vendor-users th{text-align:start;font-size:var(--staff-fs-sm,12px);font-weight:600;color:var(--muted);padding:6px 8px;border-bottom:1px solid var(--border);white-space:nowrap}
.vendor-users td{padding:7px 8px;border-bottom:1px solid var(--border);vertical-align:middle}
.vendor-u-act{display:flex;gap:6px;flex-wrap:wrap;justify-content:flex-end}
/* a login on its temporary password: until when (muted), or past it (red: Reset password sends a new one) */
.vendor-u-temp{margin-top:2px;font-size:var(--staff-fs-sm,12px);font-weight:600;color:var(--muted);white-space:normal}
.vendor-u-temp.vendor-u-exp{color:var(--red);font-weight:600}
.vendor-add-user{display:flex;gap:8px;flex-wrap:wrap;align-items:center;margin-top:10px}
.vendor-add-user input{flex:1 1 160px;min-width:0}
.vendor-add-user select{flex:0 0 auto}
.vendor-pw{margin:4px 0 12px}
.vendor-late{display:inline-flex;align-items:center;padding:2px 8px;margin-inline-end:6px;border-radius:var(--sf-r-pill,var(--sf-r-pill));background:rgba(239,68,68,.12);color:var(--red);font-size:var(--staff-fs-sm,12px);font-weight:600;white-space:nowrap}
.vendor-tell-row{margin:0 0 6px}
.vendor-tell-item+.vendor-tell-item{border-top:1px solid var(--border);padding-top:12px}
body .vendor-dlg .vendor-tell-item textarea.vendor-pw-msg{min-height:130px}
body .vendor-dlg textarea.vendor-pw-msg{width:100%;min-height:170px;box-sizing:border-box;resize:vertical;background:var(--s3);border:1px solid var(--border);border-radius:var(--sf-r-ctl,var(--sf-r-ctl));color:var(--text);padding:12px;font-family:var(--font-body);font-size:var(--sf-fs-sm);line-height:1.5}
.vendor-blines{list-style:none;margin:0;padding:0;display:flex;flex-direction:column;gap:4px;font-size:var(--sf-fs-sm)}
.vendor-bline{display:flex;align-items:center;gap:10px;flex-wrap:wrap}
#tab-vendors .vendor-chk{display:inline-flex;align-items:center;gap:8px;font-size:var(--sf-fs-sm);font-weight:600;cursor:pointer;margin-inline-end:14px}
#tab-vendors .vendor-chk input{-webkit-appearance:checkbox;appearance:checkbox;width:16px;height:16px;min-height:0;margin:0;flex:none;accent-color:var(--green)}
.vendor-modes{display:flex;flex-wrap:wrap;gap:8px 0}
.vendor-bens{display:flex;flex-direction:column;gap:8px}
.vendor-ben{display:flex;gap:8px;flex-wrap:wrap;align-items:center}
.vendor-ben input{flex:1 1 200px;min-width:0}
.vendor-ben-btns{display:inline-flex;gap:4px}
#tab-vendors .vendor-ben-btn{min-width:32px;padding-inline:8px;display:inline-flex;align-items:center;justify-content:center}
#tab-vendors .vendor-ben-btn:disabled{opacity:.4;cursor:default}
#tab-vendors .vendor-tier{padding:16px 4px}
@media(max-width:600px){#tab-vendors .vendor-day{min-height:54px;padding:4px;font-size:var(--staff-fs-sm,12px)}#tab-vendors .vendor-dv,#tab-vendors .vendor-dp{display:none}}
/* Vendors feedback (2026-10-03): the venues' rating as drawn stars, the turnout, what went well and what could be better */
.vendor-stars{display:inline-flex;align-items:center;gap:1px;flex:none;vertical-align:middle}
.vendor-star{display:block;color:var(--muted)}
.vendor-star path{fill:none;stroke:currentColor;stroke-width:1.6;stroke-linejoin:round}
.vendor-star.on{color:var(--orange)}
.vendor-star.on path{fill:currentColor}
.vendor-sr{position:absolute;width:1px;height:1px;margin:-1px;padding:0;border:0;overflow:hidden;clip-path:inset(50%);white-space:nowrap}
#tab-vendors .vendor-fb-rf{margin-top:8px;align-items:center}
.vendor-fb-rl{font-size:var(--staff-fs-sm,12px);font-weight:600;letter-spacing:0;text-transform:none;color:var(--muted);margin-inline-end:4px}
.vendor-fb-sum{display:flex;align-items:center;gap:10px;flex-wrap:wrap;margin:6px 0;font-size:var(--sf-fs-md)}
.vendor-fb-sum .vendor-star{width:16px;height:16px}
.vendor-fb-n{font-size:var(--sf-fs-sm)}
.vendor-fb-wait{font-size:var(--sf-fs-sm);color:var(--muted);margin:0 0 10px}
.vendor-fb-turn{margin-top:6px;font-size:var(--sf-fs-sm);display:flex;align-items:baseline;gap:6px;flex-wrap:wrap}
.vendor-fb-turn .vendor-lbl{margin:0}
.vendor-fb-at{margin-top:8px}
.vendor-bline .vendor-stars{margin-inline-start:auto}
.vendor-fb>.ca-head{display:flex;align-items:flex-start;gap:10px}
.vendor-fb>.ca-head>.ws-grow{flex:1;min-width:0}
/* Riders' breakfast ratings shared with the vendor (2026-10-03): the averages, the reasons with a tick each, what was shared */
.vendor-rg{padding:10px 12px;border:1px solid var(--border);border-radius:var(--sf-r-card,var(--sf-r-card));background:var(--s1);margin-bottom:8px}
.vendor-rg-day{font-weight:600;font-size:var(--sf-fs-sm);margin-bottom:4px}
.vendor-rg-n,.vendor-rg-at{font-size:var(--sf-fs-sm);font-weight:600}
.vendor-rg-at{color:var(--green)}
.vendor-rg-avgs{display:flex;flex-direction:column;gap:2px;margin:6px 0;font-size:var(--sf-fs-sm)}
.vendor-rg-avg{display:flex;justify-content:space-between;gap:10px}
.vendor-rg-avg.sub{padding-inline-start:12px;color:var(--muted)}
.vendor-rg-whys{display:flex;flex-direction:column;gap:8px}
#confirm-modal .vendor-rg-why{display:flex;align-items:flex-start;gap:8px;font-size:var(--sf-fs-sm);cursor:pointer}
#confirm-modal .vendor-rg-why input{-webkit-appearance:checkbox;appearance:checkbox;width:16px;height:16px;min-height:0;margin:2px 0 0;flex:none;accent-color:var(--green)}
.vendor-rg-why>span{flex:1;min-width:0}
.vendor-rg-said{margin-top:6px;font-size:var(--sf-fs-sm)}
.vendor-rg-explain{margin-top:10px}
.vendor-rg-shared{margin-top:10px;padding-top:10px;border-top:1px dashed var(--border)}
/* Workshop, Messages and Ambassadors without inline styles (2026-09-28, pass 2 of moving the
   style="..." attributes into classes, so the policy can drop style-src 'unsafe-inline'). The three
   lists share one card, so they share these; each rule is scoped by the section's id (or by
   #confirm-modal for their dialogs) and so outranks every class rule, as the inline style did.
   A stage colour is one of three (WS_ST_CLS in app.src.html): the word's ink and its dot. */
:is(#tab-workshop,#tab-messages,#tab-ambassadors) .ws-grow{flex:1;min-width:0;}
:is(#tab-workshop,#tab-messages,#tab-ambassadors) .ws-mt0{margin-top:0;}
:is(#tab-workshop,#tab-messages,#tab-ambassadors) .ws-mt10{margin-top:10px;}
:is(#tab-workshop,#tab-messages,#tab-ambassadors) .ws-c-orange{color:var(--orange);}
:is(#tab-workshop,#tab-messages,#tab-ambassadors) .ws-c-green{color:var(--green);}
:is(#tab-workshop,#tab-messages,#tab-ambassadors) .ws-c-muted{color:var(--muted);}
:is(#tab-workshop,#tab-messages,#tab-ambassadors) .ws-bg-orange{background:var(--orange);}
:is(#tab-workshop,#tab-messages,#tab-ambassadors) .ws-bg-green{background:var(--green);}
:is(#tab-workshop,#tab-messages,#tab-ambassadors) .ws-bg-muted{background:var(--muted);}
#confirm-modal .ws-m0{margin:0;}
#confirm-modal .ws-flex1{flex:1;}

/* A temporary password must be replaced before anything else (_pwdMustShow). */
#pwd-gate .auth-backdrop{background:var(--bg);backdrop-filter:none;-webkit-backdrop-filter:none;z-index:9580;align-items:flex-start;padding:16px;overflow:auto}
@media (min-width:768px){#pwd-gate .auth-backdrop{padding-top:88px}}
#pwd-gate .pm-out{display:block;margin:14px auto 0;background:none;border:0;color:#4f565c;font-family:var(--font-body);font-weight:700;font-size:14px;text-decoration:underline;cursor:pointer}
/* Change password from My Account (_accPwdOpen, 2026-10-03): the forced change's box, centred, with a
   close button and show/hide on each password box. */
#acc-pwd-modal .pg-box{position:relative;max-height:calc(100vh - 24px);max-height:calc(100dvh - 24px);overflow-y:auto;}
#acc-pwd-modal .ap-x{position:absolute;top:10px;inset-inline-end:10px;width:40px;height:40px;display:flex;align-items:center;justify-content:center;background:transparent none;border:0;border-radius:999px;color:#4f565c;cursor:pointer;padding:0;}
#acc-pwd-modal .pg-kicker{padding-inline-end:40px;}
/* Show/hide on a rider's password box (_pwEyeBtn, 2026-11-11): My Account, the forced change, sign-up and the
   check-up. The button sits inside the box's end, centred on any box height; :is(#_x,*) lifts each rule over the boxes' own (.auth-field input, .pg-field input) and the rider buttons'. */
.pw-wrap{position:relative;}
.pw-wrap input[type]:is(#_x,*){padding-inline-end:48px;}
.pw-wrap .pw-eye:is(#_x,*){position:absolute;top:0;bottom:0;margin:auto 0;inset-inline-end:4px;width:40px;height:40px;display:flex;align-items:center;justify-content:center;background:transparent none;border:0;border-radius:8px;color:var(--muted);cursor:pointer;padding:0;min-height:0;box-shadow:none;}
#acc-pwd-modal .ap-hint{margin-top:8px;font-size:12.5px;color:#4f565c;}
#acc-pwd-modal .pg-msg:not(:empty){margin-top:10px;}
#acc-pwd-modal .ap-done{display:flex;gap:8px;align-items:flex-start;color:#0f1215;}
#acc-pwd-modal .ap-done .cu-ic{flex:none;margin-top:2px;color:#008f52;}

/* ── Filter button and folded search, 2026-09-22 ──
   A view's filter dropdowns open under its Filter button (_fPanel), each with its name above it; the
   button sits in the list's toolbar row and the panel takes a line of its own under that row, only while
   open (2026-11-08). On phones a page's search bar is a search button until tapped (_srchCls/_srchBtn). */
.filter-more{display:flex;flex-wrap:wrap;gap:10px 12px;align-items:flex-end;flex:0 0 100%;grid-column:1/-1;margin:0;padding:12px;text-align:start;
  border:1px solid var(--border);border-radius:var(--sf-r-ctl,var(--sf-r-ctl));background:var(--s1);}
body.view-staff .filter-more{border-color:var(--sf-ctl);background:var(--sf-card);}
.filter-adv{display:none;flex:0 0 100%;width:100%;margin-bottom:10px;}
.filter-more>.filter-adv{margin-bottom:0;}
.filter-more:not(.open){display:none;}
.filter-adv.open{display:block;}
.filter-adv-in{display:flex;flex-wrap:wrap;gap:10px 12px;align-items:flex-end;}
.filter-toggle[aria-expanded="true"] .f-arrow{transform:rotate(180deg);}
.f-arrow{display:inline-block;line-height:1;}
.filter-field{display:flex;flex-direction:column;gap:5px;min-width:150px;margin:0;}
.filter-field-lbl{font-size:var(--staff-fs-sm,12px);font-weight:600;letter-spacing:0;text-transform:none;color:var(--muted);}
:is(html[lang="ar"],html[lang="ur"]) .filter-field-lbl{letter-spacing:0;text-transform:none;}
.filter-field select{width:100%;}
.filter-multi{position:relative;}
.filter-multi>summary.filter-select{display:flex;align-items:center;width:100%;max-width:240px;list-style:none;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;}
.filter-multi>summary::-webkit-details-marker{display:none;}
.filter-multi-list{position:absolute;z-index:40;top:calc(100% + 4px);inset-inline-start:0;min-width:100%;max-height:300px;overflow:auto;
  padding:6px;border:1px solid var(--border);border-radius:var(--sf-r-xs);background:var(--s1);box-shadow:0 8px 24px rgba(0,0,0,.18);}
body.view-staff .filter-multi-list{border-color:transparent;background:var(--sf-card);border-radius:var(--sf-r-card);box-shadow:var(--sf-sh-3);}
.filter-multi-opt{display:flex;align-items:center;gap:8px;padding:6px;font-size:var(--sf-fs-sm);font-weight:600;letter-spacing:0;text-transform:none;color:var(--text);white-space:nowrap;cursor:pointer;}
@media (max-width:767px){.filter-field-wide{grid-column:1/-1;}.filter-multi-list{position:static;margin-top:4px;box-shadow:none;}.filter-multi-opt{white-space:normal;}}
.filter-multi-opt input{-webkit-appearance:checkbox;appearance:checkbox;width:16px;height:16px;min-height:0;margin:0;flex:none;accent-color:var(--green);}
.srch-btn{display:none;}
@media (max-width:767px){
  .filter-more,.filter-adv-in{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));}
  .filter-more>.filter-toggle,.filter-more>.filter-adv{grid-column:1/-1;justify-content:center;}
  .filter-field{min-width:0;}
  .search-wrap.srch-fold:not(.open){flex:0 0 auto!important;width:auto!important;min-width:0!important;max-width:none!important;}
  .search-wrap.srch-fold:not(.open)>:not(.srch-btn){display:none!important;}
  .search-wrap.srch-fold:not(.open)>.srch-btn{display:inline-flex;align-items:center;justify-content:center;
    width:44px;height:44px;padding:0;border:1px solid var(--border);border-radius:var(--sf-r-ctl,var(--sf-r-ctl));background:var(--s2);color:var(--text);cursor:pointer;}
  body.view-staff .search-wrap.srch-fold:not(.open)>.srch-btn{border-color:var(--sf-ctl);background:var(--sf-card);}
  .srch-btn svg{position:static!important;transform:none!important;opacity:1!important;}
  .search-wrap.srch-fold.open{flex:1 1 100%!important;max-width:none!important;}
  body.view-staff .search-wrap.srch-fold.open .search-input{width:100%!important;}
  .search-wrap.srch-fold.open .search-clear{display:inline-flex!important;}
}
/* Every staff table sorts by any column (_mountTableSorts): the name is the button, the arrow the order */
body.view-staff th.th-sort{cursor:pointer;user-select:none;white-space:nowrap;}
body.view-staff th.th-sort:hover{color:var(--text);}
body.view-staff th.th-sort:focus-visible{outline:2px solid var(--sf-green-ink,var(--green));outline-offset:-2px;}
body.view-staff th.th-sort[aria-sort="ascending"]::after{content:" ↑";}
body.view-staff th.th-sort[aria-sort="descending"]::after{content:" ↓";}
body.view-staff th.th-sort[aria-sort="ascending"],body.view-staff th.th-sort[aria-sort="descending"]{color:var(--sf-green-ink,var(--green));}

/* ── Walk-in and Scan float on a phone ──
   The night's two busiest actions sit above the roster instead of riding away with the header and
   the filter bar: icons only (a walker, a ticket), a thumb apart, bottom corner. Neither shows on
   a desktop, where both buttons are on the page already, nor over any modal. */
.fab-row{display:none;}
@media (max-width:767px){
  body.view-staff .fab-row{
    position:fixed;inset-inline-end:14px;bottom:calc(16px + env(safe-area-inset-bottom));z-index:320;
    display:flex;gap:12px;align-items:center;
  }
  body.view-staff .fab-btn{
    display:inline-flex;align-items:center;justify-content:center;width:58px;height:58px;padding:0;
    border:none;border-radius:50%;cursor:pointer;box-shadow:0 8px 24px rgba(0,0,0,.35);
  }
  body.view-staff .fab-btn:active{transform:scale(.95);}
  body.view-staff .walkin-fab{background:var(--sf-card,#fff);color:var(--text);border:1px solid var(--sf-ctl);}
  body.view-staff .scan-fab{background:var(--sf-green-ink,var(--green));color:#fff;}
  /* both live on the page too: on a phone the floating pair is the one to use */
  body.view-staff .filter-row .scan-inline{display:none;}
  body.view-staff .sf-head-actions .walkin-head{display:none;}
  body.view-staff :is(#tab-queue,#tab-waitlist){padding-bottom:92px;}
}
body.has-modal .fab-row{display:none !important;}
