.am-seln{font-size:var(--sf-fs-sm);font-weight:600;color:var(--orange);margin-inline-end:auto;white-space:nowrap;}
.am-selgo{display:inline-flex;align-items:center;gap:6px;}
/* 2026-10-09 (M16/M20): acting on a selection, and the employee-list import (both in #confirm-modal) */
