@media (max-width:767px){
  #auth-modal.as-page .auth-backdrop{padding:20px 16px calc(48px + env(safe-area-inset-bottom));}
  #auth-modal.as-page .auth-box{padding:4px 0 0;border-radius:0;width:100%;max-width:100%;}
}

/* The session picker is the view's context, not a filter: it stands in the bar, named, at every
   width, while the rest of the filters stay behind the Filter button. */
.filter-sess{display:inline-flex;align-items:center;gap:8px;min-width:0;margin:0;}
