#checkin-modal .bkm-stepn{margin-inline-end:4px;}
#checkin-modal .bkm-nsnote{margin:14px 0 6px;font-size:var(--sf-fs-sm);font-weight:600;color:var(--orange);}
#checkin-modal .bkm-cbf{margin:12px 0 10px;}
