}
@media(max-width:1023px){
  body.view-staff :is(#tab-queue,#tab-waitlist) [data-ck="bulk"]{
    left:12px!important;right:12px;transform:none!important;
    bottom:calc(84px + env(safe-area-inset-bottom))!important;
    flex-wrap:wrap;justify-content:center;row-gap:6px;
  }
  body.view-staff :is(#tab-queue,#tab-waitlist) [data-ck="bulk"] .btn-sm{flex:0 1 auto;}
}

