  body.view-staff .cal-add{opacity:.7;width:24px;height:24px;}
}

/* ── Sessions, second round (2026-11-06 review, _n6r*): the calendar's fill and week, the alerts, the detail's lines and rota ── */
body.view-staff .cal-sess{position:relative;}
body.view-staff .cal-sess .n6r-cbar{position:absolute;inset-inline-start:0;bottom:0;height:2px;width:var(--n6r-w,0);background:var(--green);}
body.view-staff .cal-sess.n6r-f-none{background:rgba(var(--tint-rgb),.03);}
body.view-staff .cal-sess.n6r-f-high{background:rgba(245,179,1,.14);}
body.view-staff .cal-sess.n6r-f-high .n6r-cbar{background:var(--orange);}
body.view-staff .cal-sess.n6r-f-full{background:rgba(163,59,46,.12);}
body.view-staff .cal-sess.n6r-f-full .n6r-cbar{background:var(--red);}
body.view-staff .cal-sess[draggable="true"]{cursor:grab;}
body.view-staff .cal-dnum .rq-wx,body.view-staff .n6r-wk-h .rq-wx{font-weight:600;color:var(--muted);font-size:var(--sf-fs-xs);}
body.view-staff .cal-dnum .rq-wx-warn,body.view-staff .n6r-wk-h .rq-wx-warn{font-weight:600;color:var(--orange);font-size:var(--sf-fs-xs);}
body.view-staff .n6r-calmode{display:inline-flex;gap:4px;margin-inline-start:auto;}
body.view-staff .n6r-wk-days{display:flex;flex-direction:column;gap:6px;}
body.view-staff .n6r-wk-day{border:1px solid var(--sf-line2);border-radius:var(--sf-r-ctl);padding:6px 8px;background:var(--sf-card);}
body.view-staff .n6r-wk-day.past{background:var(--sf-head);}
body.view-staff .n6r-wk-day.today{border-color:var(--green);box-shadow:inset 0 0 0 1px var(--green);}
body.view-staff .n6r-wk-h{display:flex;align-items:center;gap:8px;font-size:var(--sf-fs-sm);margin-bottom:4px;}
body.view-staff .n6r-wk-h .cal-add{margin:0;margin-inline-start:auto;opacity:1;width:32px;height:32px;border-radius:var(--sf-r-xs);}
body.view-staff .n6r-wk-list{display:flex;flex-direction:column;gap:4px;}
body.view-staff .n6r-wk .cal-name,body.view-staff .n6r-wk .cal-sess em{display:inline;}
body.view-staff .n6r-wk .cal-sess{min-height:36px;}
#tab-sessions .n6r-alerts{display:flex;flex-direction:column;gap:6px;margin:0 0 12px;}
#tab-sessions .n6r-al{display:flex;align-items:center;gap:6px;flex-wrap:wrap;font-size:var(--sf-fs-sm);padding:6px 10px;border-radius:var(--sf-r-xs);border-inline-start:3px solid var(--blue);background:var(--s2);}
#tab-sessions .n6r-al-red{border-inline-start-color:var(--red);}
#tab-sessions .n6r-al-amber{border-inline-start-color:var(--orange);}
#tab-sessions .n6r-flag{display:inline-block;font-size:var(--sf-fs-xs);font-weight:600;padding:1px 6px;border-radius:var(--sf-r-xs);background:var(--s3);color:var(--text);white-space:nowrap;}
#tab-sessions .n6r-flag-full{background:rgba(245,179,1,.18);color:var(--orange);}
#tab-sessions .n6r-flag-low{background:rgba(47,99,173,.12);color:var(--blue);}
#tab-sessions .n6r-flag-over{background:rgba(163,59,46,.12);color:var(--red);}
#tab-sessions .n6r-line{font-size:var(--sf-fs-sm);margin:6px 0;display:flex;align-items:center;gap:6px;flex-wrap:wrap;}
#tab-sessions .n6r-stats{display:flex;gap:10px;flex-wrap:wrap;margin:0 0 12px;}
#tab-sessions .n6r-stats>div{background:var(--sf-head);border:1px solid var(--sf-sep);border-radius:var(--sf-r-ctl);padding:10px 14px;min-width:74px;} /* the night's own figures' look (.sess-detail-stats), a box of its own */
#tab-sessions .n6r-box{border:1px solid var(--border);border-radius:var(--sf-r-xs);padding:8px 10px;margin:8px 0;}
#tab-sessions .n6r-h{font-size:var(--sf-fs-xs);font-weight:600;color:var(--muted);margin-bottom:6px;}
#tab-sessions .n6r-rota-row{display:flex;gap:8px;align-items:flex-start;font-size:var(--sf-fs-sm);margin-bottom:4px;}
#tab-sessions .n6r-rl{flex:0 0 84px;font-weight:600;}
#tab-sessions .n6r-rn{display:flex;gap:4px;flex-wrap:wrap;}
#tab-sessions .n6r-chip{display:inline-flex;align-items:center;gap:4px;padding:1px 4px 1px 8px;border:1px solid var(--border);border-radius:var(--sf-r-xs);}
#tab-sessions .n6r-x{background:transparent none;border:0;padding:2px;min-height:0;cursor:pointer;color:var(--muted);display:inline-flex;}
#tab-sessions .n6r-rota-add{display:flex;gap:6px;flex-wrap:wrap;margin-top:6px;}
#tab-sessions .n6r-rota-add select,#tab-sessions .n6r-rota-add input{flex:1 1 120px;min-width:0;}
body.view-staff .n6r-rota-line{font-size:var(--sf-fs-sm);color:var(--muted);margin:-4px 0 8px;display:flex;gap:6px;flex-wrap:wrap;}
body.view-staff .n6r-rota-line b{color:var(--text);}
#confirm-modal .n6r-dlg{max-width:560px;width:calc(100% - 32px);max-height:calc(100dvh - 48px);overflow-y:auto;}
#confirm-modal .n6r-dlg .form-group .btn-sm{margin-top:6px;}
#confirm-modal .n6r-ta{width:100%;}
#confirm-modal .n6r-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(140px,1fr));gap:8px 12px;margin:8px 0;}
#confirm-modal .n6r-hint,#tab-sessions .n6r-hint{font-size:var(--sf-fs-sm);color:var(--muted);margin:6px 0;}
#confirm-modal .n6r-warn{font-size:var(--sf-fs-sm);font-weight:600;color:var(--red);min-height:1em;margin:6px 0;}
#confirm-modal .n6r-cp{display:flex;flex-direction:column;gap:6px;font-size:var(--sf-fs-md);margin:6px 0 4px;}
@media(max-width:767px){
  #tab-sessions .n6r-al .btn-sm{min-height:44px;}
  body.view-staff .n6r-calmode .btn-sm{min-height:44px;}
}

/* ── Community > Birthdays: today's card, month chart, countdown list, wishes ── */
    body.view-staff .bd-tab-n{display:inline-flex;align-items:center;gap:3px;}
