body.view-staff .bd-chip.soon{background:rgba(245,179,1,.16);color:var(--text);}
body.view-staff .bd-chip.today{background:rgba(var(--green-rgb),.16);color:var(--green);}
body.view-staff .bd-ms,body.view-staff .bd-ride{display:inline-block;margin-inline-start:4px;padding:1px 6px;border-radius:var(--sf-r-xs);font-size:var(--staff-fs-sm);font-weight:600;color:var(--text);white-space:nowrap;}
body.view-staff .bd-ms{background:rgba(74,168,255,.18);}
body.view-staff .bd-ride{background:rgba(255,107,139,.18);}
body.view-staff .bd-wish-cell{display:inline-flex;align-items:center;gap:6px;}
