  background:rgba(var(--green-rgb),.1);border:1px solid rgba(var(--green-rgb),.3);color:var(--green);}
body.view-staff .bd-wa.off{opacity:.4;cursor:not-allowed;background:var(--s2);border-color:var(--border);color:var(--muted);}
body.view-staff .bd-wish{min-height:32px;padding:0 10px;border-radius:var(--sf-r-ctl);border:1px solid var(--border);background:var(--s1);color:var(--muted);font:inherit;font-size:var(--sf-fs-xs);font-weight:600;cursor:pointer;white-space:nowrap;}
body.view-staff .bd-wish.on{border-color:rgba(var(--green-rgb),.4);background:rgba(var(--green-rgb),.1);color:var(--green);}
