body.view-staff .bd-months{display:grid;grid-template-columns:repeat(12,minmax(0,1fr));gap:6px;align-items:end;height:130px;margin-top:10px;}
body.view-staff .bd-mon{display:flex;flex-direction:column;align-items:center;justify-content:flex-end;gap:4px;height:100%;min-width:0;padding:0;border:0;background:none;cursor:pointer;font:inherit;color:var(--muted);}
