/* ── The ticket through the night, the countdown, the route, Your rides, the closest badges (2026-10-01) ──
   Stages: four dots on one line, the ones reached filled, the current one ringed; on the night
   ticket they are neon. The route draws the circuit as one stroke with the start as a dot. */
body:not(.view-staff) .tk-stages{display:flex;list-style:none;margin:12px 0 4px;padding:0;gap:0;}
body:not(.view-staff) .tk-stages li{flex:1 1 0;min-width:0;display:flex;flex-direction:column;align-items:flex-start;gap:3px;position:relative;padding-top:14px;font-size:var(--fs-12);color:var(--ink-2);}
body:not(.view-staff) .tk-stages li::before{content:'';position:absolute;top:4px;inset-inline:0;height:2px;background:var(--line);}
body:not(.view-staff) .tk-stages li.on::before{background:var(--go);}
body:not(.view-staff) .tk-stages li:last-child::before{inset-inline-end:auto;width:10px;}
body:not(.view-staff) .tk-st-dot{position:absolute;top:0;inset-inline-start:0;width:10px;height:10px;border-radius:50%;background:var(--card);border:2px solid var(--line-2);box-sizing:border-box;}
body:not(.view-staff) .tk-stages li.on .tk-st-dot{background:var(--go);border-color:var(--go);}
body:not(.view-staff) .tk-stages li.cur .tk-st-dot{box-shadow:0 0 0 3px var(--go-wash);}
body:not(.view-staff) .tk-stages li.on{color:var(--ink-2);}
body:not(.view-staff) .tk-stages li.cur .tk-st-l{color:var(--ink);font-weight:700;}
body:not(.view-staff) .tk-st-l{line-height:1.25;padding-inline-end:6px;}
body:not(.view-staff) .tk-st-s{font-size:var(--fs-12);color:var(--ink-2);font-variant-numeric:tabular-nums;max-width:100%;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;padding-inline-end:6px;}
body:not(.view-staff) .tk-cd{display:flex;align-items:center;gap:7px;margin:0 0 10px;font-size:var(--fs-15);font-weight:600;color:var(--go);font-variant-numeric:tabular-nums;}
body:not(.view-staff) .land-today .tk-cd.land-today-cd{margin:4px 0 0;font-size:var(--fs-13);}
body:not(.view-staff) .tk-route{display:flex;align-items:center;justify-content:space-between;gap:14px;margin:12px 0;padding:12px 14px;border:1px solid var(--line);border-radius:var(--r-ctl);}
body:not(.view-staff) .tk-rt-txt{min-width:0;display:grid;gap:2px;}
body:not(.view-staff) .tk-rt-k{font-size:var(--fs-12);color:var(--ink-2);}
body:not(.view-staff) .tk-rt-n{font-size:var(--fs-15);font-weight:700;color:var(--ink);}
body:not(.view-staff) .tk-rt-m{font-size:var(--fs-13);color:var(--ink-2);font-variant-numeric:tabular-nums;}
body:not(.view-staff) .tk-rt-done{display:flex;align-items:center;gap:5px;font-size:var(--fs-13);font-weight:600;color:var(--go);}
body:not(.view-staff) .tk-rt-a{font-size:var(--fs-13);font-weight:600;color:var(--go);}
body:not(.view-staff) .tk-rt-osm{font-size:var(--fs-12);color:var(--ink-2);margin-top:2px;}
body:not(.view-staff) .tk-rt-map{flex:none;width:30px;height:118px;overflow:visible;}
body:not(.view-staff) .tk-rt-map path{fill:none;stroke:var(--go);stroke-width:2.4;stroke-linejoin:round;stroke-linecap:round;}
body:not(.view-staff) .tk-rt-map circle{fill:var(--card);stroke:var(--ink);stroke-width:1.6;}
body:not(.view-staff) :is(#tab-myrides,#tab-register) .ticket-card:is(.tk-live,.tk-th) .tk-stages li{color:var(--night-ink-2);}
body:not(.view-staff) :is(#tab-myrides,#tab-register) .ticket-card:is(.tk-live,.tk-th) .tk-stages li::before{background:var(--night-line);}
body:not(.view-staff) :is(#tab-myrides,#tab-register) .ticket-card:is(.tk-live,.tk-th) .tk-stages li.on::before{background:var(--neon);}
body:not(.view-staff) :is(#tab-myrides,#tab-register) .ticket-card:is(.tk-live,.tk-th) .tk-st-dot{background:var(--night);border-color:var(--night-ink-2);}
body:not(.view-staff) :is(#tab-myrides,#tab-register) .ticket-card:is(.tk-live,.tk-th) .tk-stages li.on .tk-st-dot{background:var(--neon);border-color:var(--neon);}
body:not(.view-staff) :is(#tab-myrides,#tab-register) .ticket-card:is(.tk-live,.tk-th) .tk-stages li.cur .tk-st-dot{box-shadow:0 0 0 3px var(--night-line);}
body:not(.view-staff) :is(#tab-myrides,#tab-register) .ticket-card:is(.tk-live,.tk-th) .tk-stages li.cur .tk-st-l{color:var(--night-ink);}
body:not(.view-staff) :is(#tab-myrides,#tab-register) .ticket-card:is(.tk-live,.tk-th) .tk-st-s{color:var(--night-ink-2);}
body:not(.view-staff) :is(#tab-myrides,#tab-register) .ticket-card:is(.tk-live,.tk-th) .tk-cd{color:var(--neon);}
body:not(.view-staff) :is(#tab-myrides,#tab-register) .ticket-card:is(.tk-live,.tk-th) .tk-route{border-color:var(--night-line);}
body:not(.view-staff) :is(#tab-myrides,#tab-register) .ticket-card:is(.tk-live,.tk-th) :is(.tk-rt-k,.tk-rt-m,.tk-rt-osm){color:var(--night-ink-2);}
body:not(.view-staff) :is(#tab-myrides,#tab-register) .ticket-card:is(.tk-live,.tk-th) .tk-rt-n{color:var(--night-ink);}
body:not(.view-staff) :is(#tab-myrides,#tab-register) .ticket-card:is(.tk-live,.tk-th) :is(.tk-rt-a,.tk-rt-done){color:var(--neon);}
body:not(.view-staff) :is(#tab-myrides,#tab-register) .ticket-card:is(.tk-live,.tk-th) .tk-rt-map path{stroke:var(--neon);}
body:not(.view-staff) :is(#tab-myrides,#tab-register) .ticket-card:is(.tk-live,.tk-th) .tk-rt-map circle{fill:var(--night);stroke:var(--night-ink);}
body:not(.view-staff) :is(.myr,.myr-c){margin:0 0 8px;padding:18px 22px;background:var(--card);border:1px solid transparent;border-radius:var(--r-card);box-shadow:var(--pl-1);}
body:not(.view-staff) .myr-h{font-size:var(--fs-15);font-weight:700;color:var(--ink);margin-bottom:10px;}
body:not(.view-staff) .myr-weeks{display:grid;grid-template-columns:repeat(26,minmax(0,1fr));gap:3px;}
body:not(.view-staff) .myr-weeks i{display:block;aspect-ratio:1;max-height:14px;border-radius:3px;background:var(--card-3);}
body:not(.view-staff) .myr-weeks i.on{background:var(--go);}
body:not(.view-staff) .myr-wl{font-size:var(--fs-15);color:var(--ink-2);}
body:not(.view-staff) .myr-f{display:grid;margin:12px 0 0;}
body:not(.view-staff) .myr-f>div{display:flex;justify-content:space-between;gap:16px;padding:9px 0;border-top:1px solid var(--line);}
body:not(.view-staff) .myr-f dt{font-size:var(--fs-15);color:var(--ink-2);}
body:not(.view-staff) .myr-f dd{margin:0;font-size:var(--fs-15);font-weight:600;color:var(--ink);font-variant-numeric:tabular-nums;text-align:end;}
/* Stats' more of the record (2026-11-09, _myrMore): rides by month as twelve thin columns on one baseline, the value
   on the highest one's cap; the lists under it; Badges earned, a row that opens Badges. */
body:not(.view-staff) .myr-f.myr-f0{margin-top:0;}
body:not(.view-staff) .myr-mo-c{display:grid;grid-template-columns:repeat(12,minmax(0,1fr));gap:2px;margin:6px 0 0;padding:0;list-style:none;}
body:not(.view-staff) .myr-mo-c li{min-width:0;}
body:not(.view-staff) .myr-mo-a{display:flex;flex-direction:column;align-items:center;justify-content:flex-end;height:96px;border-bottom:1px solid var(--line);}
body:not(.view-staff) .myr-mo-b{display:block;width:min(16px,80%);height:var(--h,0);min-height:2px;border-radius:4px 4px 0 0;background:var(--go);}
body:not(.view-staff) .myr-mo-b.z{display:none;}
body:not(.view-staff) .myr-mo-v{margin-bottom:4px;font-size:var(--fs-13);font-weight:600;color:var(--ink);font-variant-numeric:tabular-nums;}
body:not(.view-staff) .myr-mo-l{display:flex;justify-content:center;min-height:16px;margin-top:6px;font-size:var(--fs-12);color:var(--ink-2);white-space:nowrap;}
body:not(.view-staff) .myr-bd{display:flex;align-items:center;gap:10px;width:100%;min-height:56px;font:inherit;color:var(--ink);text-align:start;cursor:pointer;}
body:not(.view-staff) .myr-bd-t{flex:1;font-size:var(--fs-15);font-weight:700;}
body:not(.view-staff) .myr-bd-n{font-size:var(--fs-15);font-weight:600;font-variant-numeric:tabular-nums;}
body:not(.view-staff) .myr-bd .cu-ic{color:var(--ink-2);}
/* The account page's switch (2026-11-09): Account, Stats, Badges, a soft segmented control like the wide screen's
   section strip; on a phone it spans the page and the three share it. */
body:not(.view-staff) #tab-account .acc-views{display:flex;gap:2px;width:fit-content;max-width:100%;margin:14px 0 4px;padding:4px;border-radius:999px;background:var(--card-3);}
body:not(.view-staff) #tab-account .acc-view{display:inline-flex;align-items:center;justify-content:center;min-height:44px;padding:0 20px;border:0;border-radius:999px;background:transparent;color:var(--ink-2);font:inherit;font-size:var(--fs-15);font-weight:500;cursor:pointer;}
body:not(.view-staff) #tab-account .acc-view:hover{color:var(--ink);}
body:not(.view-staff) #tab-account .acc-view.active{background:var(--card);color:var(--ink);font-weight:600;box-shadow:var(--pl-1);}
@media(max-width:767px){
  body:not(.view-staff) #tab-account .acc-views{width:100%;}
  body:not(.view-staff) #tab-account .acc-view{flex:1 1 0;min-width:0;padding:0 8px;}
}
body:not(.view-staff) .bd-next{display:grid;gap:8px;margin:10px 0 12px;}
body:not(.view-staff) .bd-next-h{font-size:var(--fs-13);color:var(--ink-2);}
body:not(.view-staff) .bd-next-row{display:flex;align-items:center;gap:12px;width:100%;padding:12px 14px;background:var(--card);border:1px solid transparent;border-radius:var(--r-card);box-shadow:var(--pl-1);text-align:start;color:var(--ink);cursor:pointer;}
body:not(.view-staff) .bd-next-row:hover{border-color:var(--line-2);}
body:not(.view-staff) .bd-next-row .bdg-m.bd-next-ic{width:34px;height:34px;}
body:not(.view-staff) .bd-next-t{flex:1;min-width:0;display:grid;gap:2px;}
body:not(.view-staff) .bd-next-t strong{font-size:var(--fs-15);}
body:not(.view-staff) .bd-next-t small{font-size:var(--fs-12);color:var(--ink-2);}
body:not(.view-staff) .bd-next-bar{display:block;height:4px;margin-top:4px;background:var(--card-3);border-radius:2px;overflow:hidden;}
body:not(.view-staff) .bd-next-bar i{display:block;height:100%;width:var(--cu-w);background:var(--go);}
body:not(.view-staff) .bd-next-n{flex:none;font-size:var(--fs-13);font-weight:700;color:var(--ink-2);font-variant-numeric:tabular-nums;}
/* ── Fit the screen, one button size (the owner, 2026-10-02: "the screens and pop ups in the customers website
   are sometimes zoomed in or needs to be scrolled right or left ... fit everything without making it look
   unaligned, align all buttons and make them have the same size"). The page never moves sideways; a popup
   never outgrows the screen; a long name, email or link wraps instead of pushing its box wider; every text
   field is at least 16px, so iOS never zooms into the form when it is tapped; and every rider button is one
   height, its words centred. ── */
html:has(body:not(.view-staff)),body:not(.view-staff){overflow-x:clip;}
body:not(.view-staff) :is(img,video,canvas,iframe){max-width:100%;}
body:not(.view-staff) :is(.modal-box,.confirm-box,.bike-info-box,.pin-box,.cust-sheet){max-width:min(560px,calc(100vw - 24px));box-sizing:border-box;}
body:not(.view-staff) :is(.modal-box,.confirm-box,.bike-info-box,.pin-box,.ticket-card,.card,.acc-card,.cu-rv-rider,.mr-row){overflow-wrap:break-word;}
body:not(.view-staff) :is(.modal-box,.confirm-box,.ticket-card,.card) :is(a,bdi,[dir="ltr"]){overflow-wrap:anywhere;}
body:not(.view-staff) :is(input:not([type="checkbox"]):not([type="radio"]):not([type="range"]),select,textarea){font-size:max(16px,1em);}
:where(body:not(.view-staff)) :where(.btn-primary,.btn-secondary,.btn-sm,.btn-wallet,.toggle-btn,.cancel-reason-opt){display:inline-flex;align-items:center;justify-content:center;}
body:not(.view-staff) :is(.btn-primary,.btn-secondary,.btn-sm,.btn-wallet,.toggle-btn,.type-info-btn){min-height:48px;box-sizing:border-box;line-height:1.2;}
body:not(.view-staff) :is(.btn-primary,.btn-secondary,.btn-sm,.btn-wallet){padding-block:0;}
/* A booking card's actions (Edit, Reschedule, Cancel; Rate, Book again) share their row in equal widths and
   step onto a second row when the phone is too narrow for their words, never squeezing them. A popup's two
   answers (Keep booking / Cancel booking) take half the row each. */
body:not(.view-staff) .cu-tk-actions{display:grid;grid-template-columns:repeat(auto-fit,minmax(128px,1fr));gap:8px;}
body:not(.view-staff) .cu-tk-actions>*{width:100%;min-width:0;white-space:nowrap;}
/* ── My Account's emergency card (2026-10-07): the optional second contact sits under the first, past a hairline.
   Each contact's line keeps its words at the start and its buttons at the end; where the row is too narrow for
   both, the buttons step under the words. An empty error line under a saved contact takes no room. Scoped by
   the account tab: the card's own id begins like a hex colour, which the build's colour check reads as one. ── */
body:not(.view-staff) #tab-account .acc-em2{margin-top:18px;padding-top:16px;border-top:1px solid var(--line);}
body:not(.view-staff) #tab-account .acc-em2-t{font-size:var(--fs-15);font-weight:700;color:var(--ink);margin-bottom:4px;}
body:not(.view-staff) #tab-account .run-em-card{flex-wrap:wrap;}
body:not(.view-staff) #tab-account .run-em-card>.cu-f1-min0{flex:1 1 180px;min-width:0;}
body:not(.view-staff) #tab-account .acc-em2-acts{display:flex;flex-wrap:wrap;gap:8px;}
body:not(.view-staff) #tab-account .acc-em2-err:empty{min-height:0;margin:0;}
/* The correction page's emergency contacts: its box is a phone's width at every size, so the number and the
   relationship stack there as they do on a phone (side by side, a desktop left the number some 40px wide). */
body:not(.view-staff) .fx-em .form-row{grid-template-columns:1fr;gap:0;}
/* A freed waitlist place, claimed (#wl-claim, 2026-10-09): the correction card, the time left in the action green */
#wl-claim .wlc-ends{margin:14px 0 16px;font-size:var(--fs-15);color:var(--ink-2);}
#wl-claim .wlc-ends b{color:var(--go);font-variant-numeric:tabular-nums;font-size:var(--fs-20);}
#wl-claim .wlc-mine{display:flex;align-items:center;justify-content:center;text-decoration:none;margin-top:14px;}
#wl-claim .fx-kicker{color:var(--go);}
/* ── Nothing arrives by itself (2026-10-10): no fade-and-rise on a tab, no pulsing dot. What the rider
   touches answers instead (Liquid, 2026-11-07): a dialog they opened settles in on the spring (scale only,
   so its contrast is right from the first frame), see LIQUID below. Today's ticket line stays. ───── */
body:not(.view-staff) :is(.tab-panel.active,.modal-backdrop,.modal-box,.confirm-box,.badge-pop,.badge-pop-box,
  .photo-lightbox,.photo-lightbox img,.pay-menu-popup,.dot-green,.refresh-dot){animation:none;}

/* ── The badge sheet: a name, not a trophy plate ──────────────────────────────────────────────────── */
body:not(.view-staff) .badge-pop-box{border:1px solid var(--line);border-radius:var(--r-sheet);background:var(--card);box-shadow:var(--sh-float);}
body:not(.view-staff) .badge-pop-nm{font-size:var(--fs-20);font-weight:700;font-style:normal;color:var(--ink);font-synthesis:none;margin-bottom:8px;}
body:not(.view-staff) :is(.badge-pop-how,.badge-pop-lvn){font-size:var(--fs-13);font-weight:600;color:var(--ink-2);}
body:not(.view-staff) .badge-pop-new{font-size:var(--fs-13);font-weight:600;color:var(--go);}
body:not(.view-staff) :is(.badge-pop-prog,.badge-lvl-n){font-family:inherit;font-variant-numeric:tabular-nums;}
body:not(.view-staff) :is(.badge-pop-earned,.badge-lvl-n){display:inline-flex;align-items:center;gap:6px;}
body:not(.view-staff) .badge-pop-note{font-style:normal;background:var(--card-2);border-radius:var(--r-ctl);}
body:not(.view-staff) .badge-lvl{border-radius:var(--r-ctl);background:var(--card-2);border-color:var(--line);}

/* ── The session picker: days, each said once, with its sessions as rows (_sessDays, 2026-10-10) ──── */
body:not(.view-staff) .session-cards-grid{grid-auto-rows:auto;gap:20px;}
body:not(.view-staff) .sess-day-h{margin:0 0 8px;font-size:var(--fs-13);font-weight:600;color:var(--ink-2);}
body:not(.view-staff) .sess-day-list{display:grid;grid-auto-rows:1fr;background:var(--card);border:1px solid var(--line);border-radius:var(--r-card);overflow:hidden;}
body:not(.view-staff) .sess-day-list .sess-card{border:0;border-radius:0;border-top:1px solid var(--line);}
body:not(.view-staff) .sess-day-list>.sess-wrap:first-child>.sess-card{border-top:0;}
body:not(.view-staff) .sess-day-list .sess-card:focus-visible{outline-offset:-3px;}
body:not(.view-staff) .sess-day-list .sess-card.sess-selected{box-shadow:inset 0 0 0 2px var(--go);background:var(--go-wash);}
body:not(.view-staff) .sess-card-head .sess-card-time{flex:1;min-width:0;}
body:not(.view-staff) .sess-card-sub{display:flex;align-items:baseline;gap:12px;min-width:0;}
body:not(.view-staff) .sess-card-sub .sess-card-meta{flex:1;min-width:0;}
body:not(.view-staff) .sess-card-spots::before{display:none;}

/* ── Nothing booked: a drawn bike, one line, and the next ride that can be booked (2026-10-10) ────── */
body:not(.view-staff) .rides-zero{display:flex;flex-direction:column;align-items:center;gap:14px;padding:40px 16px 48px;border-top:0;margin-top:16px;text-align:center;}
body:not(.view-staff) .rides-zero-ic{color:var(--ink-3);display:flex;}
