/* ════════════════════════════════════════════════════════════════════════════════════════════════
   LIQUID (2026-11-07, the soft redesign: the user picked "Liquid" for riders). Glass is a material for the
   chrome that content scrolls under - the top bar, the floating tab bar, the Continue bar - and a still
   blur behind a dialog. Every glass surface is solid paper first and turns to glass only where the
   browser blurs (@supports), and solid again when the rider asks for less transparency or more contrast,
   or the phone is short of memory (html.lite, set by the head script). Never more than three blurred
   surfaces on a screen, never inside a scroller, never glass on glass, never an animated blur.
   ════════════════════════════════════════════════════════════════════════════════════════════════ */
@supports (transition-timing-function:linear(0,1)){
  /* a damped spring, about 4% over: calmer than iOS, still alive */
  body:not(.view-staff){--ease-spring:linear(0,.095,.295,.513,.703,.847,.944,1.001,1.029,1.038,1.036,1.029,1.021,1.013,1.007,1.003,1);
    --ease-calm:linear(0,.14,.39,.62,.79,.9,.957,.987,1.001,1.006,1.006,1.004,1.002,1);}
}
:is(html[lang="ar"],html[lang="ur"],html[lang="hi"],html[lang="ne"],html[lang="bn"]) body:not(.view-staff){--glass:var(--glass-hi);}

/* the three glass bars, solid until the browser can blur */
body:not(.view-staff) #topbar#topbar{background:var(--glass-solid);border-bottom:0;box-shadow:0 1px 0 var(--glass-edge);}
body:not(.view-staff) #cust-bottom-nav{background:var(--glass-solid);border-top:0;box-shadow:0 0 0 1px var(--glass-edge),var(--lq-3);}
body:not(.view-staff) :is(.mm-reg-foot,.mm-cart-foot){background:var(--glass-solid);border-top:0;box-shadow:0 0 0 1px var(--glass-edge),var(--lq-2);border-radius:var(--r-sheet);}
@supports ((-webkit-backdrop-filter:blur(1px)) or (backdrop-filter:blur(1px))){
  body:not(.view-staff) #topbar#topbar{background:var(--glass);-webkit-backdrop-filter:var(--glass-fx);backdrop-filter:var(--glass-fx);
    box-shadow:inset 0 -1px 0 var(--glass-edge);}
  body:not(.view-staff) #cust-bottom-nav{background:var(--glass);-webkit-backdrop-filter:var(--glass-fx);backdrop-filter:var(--glass-fx);
    box-shadow:inset 0 1px 0 var(--glass-rim),inset 0 -1px 0 var(--glass-rim-2),0 0 0 1px var(--glass-edge),var(--lq-3);}
  body:not(.view-staff) :is(.mm-reg-foot,.mm-cart-foot){background:var(--glass);-webkit-backdrop-filter:var(--glass-fx);backdrop-filter:var(--glass-fx);
    box-shadow:inset 0 1px 0 var(--glass-rim),0 0 0 1px var(--glass-edge),var(--lq-2);}
}
@media (prefers-reduced-transparency:reduce),(prefers-contrast:more){
  body:not(.view-staff){--glass:var(--glass-solid);--glass-fx:none;--scrim-fx:none;}
}
