/* ── The review's add-ons fold behind their title row and the waiver's words open from theirs (2026-11-09) ── */
body:not(.view-staff) #tab-register .cu-fold-h{margin-bottom:0;}
body:not(.view-staff) #tab-register :is(.cu-ad-tog,.cu-wv-open){display:flex;align-items:center;gap:10px;width:100%;min-height:44px;margin:0;padding:0;border:0;background:none;color:inherit;font:inherit;text-align:start;cursor:pointer;}
body:not(.view-staff) #tab-register :is(.cu-ad-tog,.cu-wv-open)>span:first-child{flex:1;min-width:0;}
body:not(.view-staff) #tab-register :is(.cu-ad-tog,.cu-wv-open) .cu-ic{flex:none;color:var(--ink-2);}
body:not(.view-staff) #tab-register .cu-ad-tog .cu-ic{transform:rotate(90deg);transition:transform .2s var(--ease-spring);}
body:not(.view-staff) #tab-register .cu-ad-tog[aria-expanded="true"] .cu-ic{transform:rotate(-90deg);}
body:not(.view-staff) #tab-register .cu-ad-n{min-width:24px;padding:2px 8px;border-radius:999px;background:var(--go-wash);font-size:var(--fs-13);font-weight:600;text-align:center;font-variant-numeric:tabular-nums;}
body:not(.view-staff) #tab-register #reg-ad-body{margin-top:12px;}
body:not(.view-staff) .wv-dlg-text{max-height:min(56vh,480px);overflow-y:auto;overscroll-behavior:contain;margin:12px 0 4px;font-size:var(--fs-15);line-height:1.6;color:var(--ink-2);}
/* ── ACCOUNT MENU (2026-11-10, the user's picks for the account rework): the profile card above the Account / Stats /
   Badges switch, the wallet and Invite friends as two tiles, grouped rows that say their value (what a page lacks in
   amber) and open small pages; a phone shows the menu or one page, from 900px the two sit side by side. ───────────── */
body:not(.view-staff) #tab-account .acc-id{display:flex;align-items:center;gap:14px;width:100%;margin:4px 0 0;padding:14px 16px;border:1px solid transparent;border-radius:var(--r-card);background:var(--card);box-shadow:var(--pl-1);color:var(--ink);font:inherit;text-align:start;cursor:pointer;}
body:not(.view-staff) #tab-account .acc-id-ph{width:56px;height:56px;border-radius:50%;object-fit:cover;flex:none;}
body:not(.view-staff) #tab-account .acc-id-in{display:inline-flex;align-items:center;justify-content:center;background:var(--go-wash);color:var(--go);font-size:var(--fs-20);font-weight:700;}
body:not(.view-staff) #tab-account .acc-id-txt{flex:1 1 auto;min-width:0;display:flex;flex-direction:column;gap:2px;}
body:not(.view-staff) #tab-account .acc-id-n{font-size:var(--fs-20);font-weight:700;line-height:1.25;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;}
body:not(.view-staff) #tab-account .acc-id-s{font-size:var(--fs-15);color:var(--ink-2);line-height:1.35;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;}
body:not(.view-staff) #tab-account :is(.acc-id,.acc-row)>.cu-ic:last-child{flex:none;color:var(--ink-3);}
body:not(.view-staff) #tab-account :is(.acc-split,.acc-tiles,.acc-tile,.acc-row,.acc-grp,.acc-pg)[hidden]{display:none;}
body:not(.view-staff) #tab-account .acc-tiles{display:flex;flex-wrap:wrap;gap:12px;margin:0 0 20px;}
body:not(.view-staff) #tab-account .acc-tile{flex:1 1 0;min-width:0;display:flex;flex-direction:column;align-items:flex-start;justify-content:space-between;gap:10px;min-height:88px;padding:14px 16px;border:1px solid transparent;border-radius:var(--r-card);background:var(--card);box-shadow:var(--pl-1);color:var(--ink);font:inherit;text-align:start;cursor:pointer;}
body:not(.view-staff) #tab-account .acc-tile-k{display:flex;align-items:center;gap:8px;max-width:100%;font-size:var(--fs-13);font-weight:600;color:var(--ink-2);}
body:not(.view-staff) #tab-account .acc-tile-k .cu-ic{flex:none;color:var(--go);}
body:not(.view-staff) #tab-account .acc-tile-v{max-width:100%;font-size:var(--fs-20);font-weight:700;line-height:1.2;font-variant-numeric:tabular-nums;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;}
body:not(.view-staff) #tab-account .acc-tile-v:empty{display:none;}
body:not(.view-staff) #tab-account .acc-tile-inv{flex:1 0 100%;flex-direction:row;align-items:center;min-height:56px;}
body:not(.view-staff) #tab-account .acc-tile-inv .acc-tile-k{flex:1 1 auto;font-size:var(--fs-15);color:var(--ink);}
body:not(.view-staff) #tab-account .acc-tile-inv>.cu-ic{flex:none;color:var(--ink-3);}
body:not(.view-staff) #tab-account .acc-grp+.acc-grp{margin-top:20px;}
body:not(.view-staff) #tab-account .acc-grp-h{margin:0 0 8px;padding-inline-start:16px;font-size:var(--fs-13);font-weight:600;color:var(--ink-2);}
body:not(.view-staff) #tab-account .acc-list{background:var(--card);border-radius:var(--r-card);box-shadow:var(--pl-1);overflow:hidden;}
body:not(.view-staff) #tab-account .acc-row{position:relative;display:flex;align-items:center;gap:12px;width:100%;min-height:56px;margin:0;padding:10px 16px;border:0;border-radius:0;background:transparent;box-shadow:none;color:var(--ink);font:inherit;font-size:var(--fs-15);font-weight:400;text-align:start;text-decoration:none;cursor:pointer;}
body:not(.view-staff) #tab-account .acc-row:not([hidden])~.acc-row::before{content:'';position:absolute;top:0;inset-inline:52px 0;border-top:1px solid var(--line);}
body:not(.view-staff) #tab-account .acc-row:hover{background:var(--card-2);}
body:not(.view-staff) #tab-account .acc-row:active{background:var(--card-3);}
body:not(.view-staff) #tab-account .acc-row:focus-visible{outline-offset:-2px;}
body:not(.view-staff) #tab-account .acc-row-ic{display:inline-flex;flex:none;width:24px;justify-content:center;color:var(--ink-2);}
body:not(.view-staff) #tab-account .acc-row-t{flex:1 0 auto;max-width:100%;font-weight:500;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;}
body:not(.view-staff) #tab-account .acc-row-v{flex:0 1 auto;min-width:0;max-width:52%;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;color:var(--ink-2);text-align:end;}
body:not(.view-staff) #tab-account .acc-row-v.acc-add{color:var(--amber);font-weight:600;}
body:not(.view-staff) #tab-account :is(.acc-row-red,.acc-row-red .acc-row-ic){color:var(--red);}
/* the pages: a title, then the page's card; a page that is one older card shows that card without its own title */
body:not(.view-staff) #tab-account .acc-pg-h{margin:4px 0 16px;font-size:var(--fs-26);font-weight:700;letter-spacing:-.5px;line-height:1.15;color:var(--ink);}
body:not(.view-staff) #tab-account .acc-pg-h:focus{outline:none;}
body:not(.view-staff) #tab-account .acc-pg :is(.cu-card640,.cu-card640-0){max-width:none;margin:16px 0 0;}
body:not(.view-staff) #tab-account .acc-pg-h+.cu-card640,
body:not(.view-staff) #tab-account .acc-pg-h+div>.cu-card640:first-child{margin-top:0;}
body:not(.view-staff) #tab-account .acc-pg-solo :is(.form-title,.cw-mine-t,.ref-t,.amb-mine-title){display:none;}
body:not(.view-staff) #tab-account .acc-pg-solo .cw-mine-top{justify-content:flex-start;}
body:not(.view-staff) #tab-account .acc-pg-card :is(.form-group,.form-row,.acc-wa){margin:0 0 16px;}
body:not(.view-staff) #tab-account .acc-pg-card .form-row>.form-group{margin:0;}
body:not(.view-staff) #tab-account .acc-pg-card .cu-type-hint{margin-top:8px;}
body:not(.view-staff) #tab-account .acc-pg-card .cu-acc-err:empty{min-height:0;margin:0;}
body:not(.view-staff) #tab-account .acc-wa-k{margin:0 0 6px;font-size:var(--fs-13);font-weight:600;color:var(--ink-2);}
body:not(.view-staff) #tab-account .acc-save{width:100%;margin-top:4px;}
@media (max-width:899px){
  body:not(.view-staff) #tab-account.acc-in-pg :is(.acc-id,.acc-views,.acc-menu){display:none;}
}
@media (min-width:641px){
  body:not(.view-staff) #tab-account .acc-save{width:auto;min-width:180px;}
}
@media (min-width:900px){
  body:not(.view-staff) #tab-account .acc-split{display:grid;grid-template-columns:minmax(300px,380px) minmax(0,1fr);gap:28px;align-items:start;}
  body:not(.view-staff) #tab-account .acc-split:not(.acc-has-pg) .acc-pg[data-acc-pg="personal"]{display:block;}
  body:not(.view-staff) #tab-account :is(.acc-split:not(.acc-has-pg) .acc-row[data-acc-go="personal"],.acc-row[aria-current="page"]){background:var(--go-wash);}
  body:not(.view-staff) #tab-account .acc-pg-h{margin:0 0 14px;font-size:var(--fs-20);letter-spacing:0;}
}
/* The error bar on a rider screen: the toast's dark pill. Its words were the page's dark ink on the bar's fixed dark
   red, all but unreadable, now that the bar carries the way to what an account owes (2026-11-10). */
body:not(.view-staff) .err-bar{background:var(--night);border:0;border-radius:var(--r-ctl);box-shadow:var(--lq-3);}
body:not(.view-staff) .err-bar .undo-bar-text{color:var(--night-ink);font-weight:600;}
body:not(.view-staff) .err-bar .err-bar-detail{color:var(--night-ink-2);}
/* ── Reserve, the 2026-11-10 research (rows 1-19) ───────────────────────────────────────────────── */
/* Details as the 44px "i" on a row (row 17) */
body:not(.view-staff) .sess-wrap .sess-about.sess-i{width:44px;height:44px;justify-content:center;padding:0;inset-inline-start:4px;text-decoration:none;color:var(--ink-2);border-radius:50%;}
body:not(.view-staff) .sess-wrap .sess-about.sess-i:hover{color:var(--ink);}
body:not(.view-staff) .sess-about.sess-i:focus-visible{outline-offset:-4px;border-radius:50%;}
/* the not-yet-open row carries a clock, not grey alone (row 3) */
body:not(.view-staff) .spots-soon{display:inline-flex;align-items:center;gap:5px;}
/* the waitlist said in the bar and on the review before Confirm (row 1) */
body:not(.view-staff) .cu-wl-chip{display:inline-flex;align-items:center;min-height:20px;padding:0 8px;border-radius:999px;box-shadow:inset 0 0 0 1px var(--red-line);color:var(--red);font-size:var(--fs-12);font-weight:600;vertical-align:1px;}
/* a type another rider filled while this one was on the form (TYPE_FULL, 2026-11-11): said on the review */
body:not(.view-staff) .cu-cap-err{margin:6px 0 4px;color:var(--red);font-size:var(--fs-13);font-weight:600;}
/* the step-2 bar's total (row 9) */
body:not(.view-staff) .reg-foot-tot{align-self:center;font-size:var(--fs-17);font-weight:700;color:var(--ink);white-space:nowrap;}
body:not(.view-staff) .reg-foot-tot:empty{display:none;}
/* the height with its unit inside the field (owner Q2, row 6) */
body:not(.view-staff) .cu-unit-row{position:relative;display:flex;align-items:center;}
body:not(.view-staff) .cu-unit-row input{flex:1;padding-inline-end:52px;}
body:not(.view-staff) .cu-unit{position:absolute;inset-inline-end:16px;color:var(--ink-3);font-size:var(--fs-15);pointer-events:none;}
/* Change on the review (row 8), the promo link (row 10) */
body:not(.view-staff) :is(.cu-rv-chg,.cu-promo-link){display:inline-flex;align-items:center;gap:6px;min-height:44px;padding:0 2px;background:none;border:0;color:var(--go);font:inherit;font-weight:600;cursor:pointer;}
body:not(.view-staff) .cu-rv-chg{text-decoration:underline;text-underline-offset:3px;}
body:not(.view-staff) .cu-rv-sec-chg{display:flex;align-items:center;justify-content:space-between;gap:8px;}
/* a tap anywhere on an add-on's row (row 14) */
body:not(.view-staff) .cu-ad-tap{cursor:pointer;}
/* "Book my usual" as a chip, not a full-width bar (row 12) */
body:not(.view-staff) #tab-register .cu-usual{width:auto;display:inline-flex;min-height:44px;padding:0 18px;border-radius:999px;font-size:var(--fs-15);margin-bottom:14px;}
/* one way to show a pick: the green wash and the green mark, on a ride and on a bike (row 17) */
body:not(.view-staff) #tab-register .type-grid .toggle-btn.active{background:var(--go-wash);border-color:var(--go);color:var(--ink);}
body:not(.view-staff) #tab-register .type-grid .toggle-btn.active>.tp-txt::before{background:var(--go);}
body:not(.view-staff) #tab-register .type-pick:has(.toggle-btn.active)>.type-info-btn{background:var(--go-wash);border-color:var(--go);color:var(--ink);}
/* a booking not sent yet: a clock in a quiet disc, no tick (row 2) */
body:not(.view-staff) .bk-pend .bk-ok-disc{display:grid;place-items:center;background:var(--card-3);color:var(--ink-2);}
/* a field with an error keeps its red ring while it is being fixed, not the green one (2026-11-11) */
body:not(.view-staff) :is(input,select,textarea).field-invalid:focus{border-color:var(--red);box-shadow:inset 0 0 0 1px var(--red);}
body:not(.view-staff) :is(input,select,textarea).field-invalid:focus-visible{outline-color:var(--red);}
/* the place gone question (row 13) */
body:not(.view-staff) .pg-dlg .modal-footer{flex-wrap:wrap;}
/* the bar stays put on a phone, and nothing focused hides under it (rows 7, 12) */
@media(max-width:720px){
  body:not(.view-staff).view-customer:has(#tab-register.active .mm-reg-foot) .mm-reg-foot{position:fixed;inset-inline:12px;bottom:max(12px,env(safe-area-inset-bottom));margin:0;}
  body:not(.view-staff).view-customer:has(#tab-register.active .mm-reg-foot) #view-customer .view-main{padding-bottom:calc(112px + env(safe-area-inset-bottom));}
  html.kb-open body:not(.view-staff).view-customer #tab-register .mm-reg-foot{position:static;}
}
html:has(body:not(.view-staff) #tab-register.active .mm-reg-foot){scroll-padding-bottom:calc(120px + env(safe-area-inset-bottom));}
/* ── MY BOOKINGS, THE RESEARCH ROUND (2026-11-10: "do everything" from reports/Rider Bookings page enhancements, the
   owner's four open decisions left out). The date on one line, today's code large, the reference half folded, the
   cancelled bookings kept, four buttons in two columns, numbers that line up. ───────────────────────────────────── */
/* the date and the place: one start-aligned line each, under the number (they were six right-aligned lines beside the
   code); a segment never breaks inside itself, only at its dot */
body:not(.view-staff) :is(#tab-myrides,#tab-register) .ticket-header:has(+:is(.tk-qr-big,.tk-when)){border-bottom:0;padding-bottom:10px;}
body:not(.view-staff) :is(#tab-myrides,#tab-register) .cu-tk-when.tk-when{display:flex;flex-direction:column;gap:3px;margin:0;padding:0 18px 14px;text-align:start;font-size:var(--fs-15);font-weight:500;line-height:1.4;font-variant-numeric:tabular-nums;border-bottom:1px dashed var(--line-2);}
body:not(.view-staff) :is(#tab-myrides,#tab-register) .tk-when :is(.tk-when-d,.tk-when-p){display:flex;flex-wrap:wrap;align-items:baseline;column-gap:7px;row-gap:1px;}
body:not(.view-staff) :is(#tab-myrides,#tab-register) .tk-when .tk-when-d{font-weight:600;color:var(--ink);}
body:not(.view-staff) :is(#tab-myrides,#tab-register) .tk-when .tk-when-p{font-size:var(--fs-13);}
body:not(.view-staff) :is(#tab-myrides,#tab-register) .tk-when :is(.tk-seg,.tk-collect){white-space:nowrap;}
body:not(.view-staff) :is(#tab-myrides,#tab-register) .tk-when .tk-sep{opacity:.55;}
body:not(.view-staff) :is(#tab-myrides,#tab-register) .ticket-card:is(.tk-live,.tk-th) .tk-when{border-bottom-color:var(--night-line);}
body:not(.view-staff) :is(#tab-myrides,#tab-register) .ticket-card:is(.tk-live,.tk-th) .tk-when .tk-when-d{color:var(--night-ink);}
body:not(.view-staff) :is(#tab-myrides,#tab-register) .ticket-card.wl-open .tk-when{padding-top:2px;}
/* today's code: large, centred, on its white tile, under the number */
body:not(.view-staff) :is(#tab-myrides,#tab-register) .tk-qr-big{display:flex;justify-content:center;padding:0 18px 16px;}
body:not(.view-staff) :is(#tab-myrides,#tab-register) .tk-qr-big :is(svg,canvas){border-radius:var(--r-ctl);}
body:not(.view-staff) :is(#tab-myrides,#tab-register) .tk-qr-big .qr-lazy{width:224px;height:224px;}
/* the reference half (the route, the add-ons) behind one Details row; the total stays in view */
body:not(.view-staff) :is(#tab-myrides,#tab-register) .tk-more{margin:8px 0 0;}
body:not(.view-staff) :is(#tab-myrides,#tab-register) .tk-more-btn{display:flex;align-items:center;justify-content:space-between;gap:10px;width:100%;min-height:44px;margin:0;padding:0;border:0;border-top:1px solid var(--line);background:transparent;font:inherit;font-size:var(--fs-15);font-weight:600;color:var(--ink);cursor:pointer;text-align:start;}
body:not(.view-staff) :is(#tab-myrides,#tab-register) .tk-more-btn:focus-visible{outline:2px solid var(--go);outline-offset:2px;border-radius:var(--r-ctl);}
body:not(.view-staff) :is(#tab-myrides,#tab-register) .tk-more-ic{flex:none;width:18px;height:18px;transition:transform .22s var(--ease-calm);}
body:not(.view-staff) :is(#tab-myrides,#tab-register) .tk-more.on .tk-more-ic{transform:rotate(180deg);}
body:not(.view-staff) :is(#tab-myrides,#tab-register) .tk-more-body{padding:2px 0 8px;}
body:not(.view-staff) :is(#tab-myrides,#tab-register) .tk-more-body>:first-child{margin-top:0;}
body:not(.view-staff) :is(#tab-myrides,#tab-register) .ticket-card:is(.tk-live,.tk-th) .tk-more-btn{color:var(--night-ink);border-top-color:var(--night-line);}
body:not(.view-staff) :is(#tab-myrides,#tab-register) .ticket-card:is(.tk-live,.tk-th) .tk-more-btn:focus-visible{outline-color:var(--neon);}
@media (prefers-reduced-motion:reduce){body:not(.view-staff) .tk-more-ic{transition:none;}}
/* the buttons: Calendar and Directions side by side with Share as a square at the end of their row; today's Live map
   takes a row of its own under them */
body:not(.view-staff) :is(#tab-myrides,#tab-register) .cu-tk-btns{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr) 48px;gap:8px;}
body:not(.view-staff) :is(#tab-myrides,#tab-register) .cu-tk-btns :is(.cu-tk-cal,.cu-tk-dir,.cu-tk-live,.cu-tk-share){display:flex;align-items:center;justify-content:center;gap:8px;min-width:0;min-height:48px;padding-inline:8px;font-size:var(--fs-15);font-weight:600;white-space:nowrap;text-decoration:none;}
/* Calendar and Directions take a second line when their label is wider than the half row ("Ajouter au calendrier"
   on a 390px phone): a one-line label ran out of its button into the next one */
body:not(.view-staff) :is(#tab-myrides,#tab-register) .cu-tk-btns :is(.cu-tk-cal,.cu-tk-dir){white-space:normal;line-height:1.2;text-align:center;overflow-wrap:anywhere;}
body:not(.view-staff) :is(#tab-myrides,#tab-register) .cu-tk-btns :is(.cu-tk-cal,.cu-tk-dir)>svg{flex:none;}
body:not(.view-staff) :is(#tab-myrides,#tab-register) .cu-tk-btns .cu-tk-share{grid-column:3;grid-row:1;width:48px;padding:0;}
body:not(.view-staff) :is(#tab-myrides,#tab-register) .cu-tk-btns .cu-tk-share:only-child{grid-column:1/-1;width:auto;}
body:not(.view-staff) :is(#tab-myrides,#tab-register) .cu-tk-btns>.cu-tk-dir:first-child{grid-column:1/3;}
body:not(.view-staff) :is(#tab-myrides,#tab-register) .cu-tk-btns .cu-tk-live{grid-column:1/-1;}
body:not(.view-staff) :is(#tab-myrides,#tab-register) .cu-tk-btns :is(.cu-tk-live,.cu-tk-share) svg{flex:none;width:18px;height:18px;}
/* a narrow phone (320-374px): the two labels may take two lines and lose their marks, rather than run into each other */
@media (max-width:374px){
  body:not(.view-staff) :is(#tab-myrides,#tab-register) .cu-tk-btns :is(.cu-tk-cal,.cu-tk-dir){white-space:normal;line-height:1.2;text-align:center;font-size:var(--fs-13);padding-inline:6px;}
  body:not(.view-staff) :is(#tab-myrides,#tab-register) .cu-tk-btns :is(.cu-tk-cal,.cu-tk-dir)>svg{display:none;}
}
/* the rider rows' small words on the scale's floor (they were 10 and 11px), chips as pills (one was 6px) */
body:not(.view-staff) :is(#tab-myrides,#tab-register) .ticket-card :is(.cu-tr-num,.cu-pay-due,.cu-pay-ok,.cu-tr-wl,.type-badge){font-size:var(--fs-12);}
body:not(.view-staff) :is(#tab-myrides,#tab-register) .ticket-card .type-badge{border-radius:999px;}
/* the choice of maps on an iPhone (_dirPick): two whole-width buttons in the centred dialog */
body:not(.view-staff) .dir-pick-acts{display:grid;gap:10px;padding:4px 20px 20px;}
body:not(.view-staff) .dir-pick-acts a{display:flex;align-items:center;justify-content:center;min-height:48px;font-size:var(--fs-15);font-weight:600;text-decoration:none;}
/* a cancelled booking: one quiet row, dashed like a place not held, who cancelled it in a chip */
body:not(.view-staff) #tab-myrides .mr-cx-list{display:flex;flex-direction:column;gap:8px;}
body:not(.view-staff) #tab-myrides .myrides-grid>.empty-state+.mr-cx-list{margin-top:4px;}
body:not(.view-staff) #tab-myrides .mr-cx{padding:14px 18px;border-radius:var(--r-card);background:var(--card-2);border:1.5px dashed var(--line-2);}
body:not(.view-staff) #tab-myrides .mr-cx-top{display:flex;align-items:center;justify-content:space-between;gap:10px;}
body:not(.view-staff) #tab-myrides .mr-cx-n{min-width:0;font-size:var(--fs-15);font-weight:600;color:var(--ink-2);}
body:not(.view-staff) #tab-myrides .mr-cx-chip{flex:none;padding:3px 10px;border-radius:999px;background:var(--card);border:1px solid var(--red-line);color:var(--red);font-size:var(--fs-12);font-weight:600;}
body:not(.view-staff) #tab-myrides .mr-cx-w{margin-top:3px;font-size:var(--fs-13);color:var(--ink-2);font-variant-numeric:tabular-nums;}
/* painted from the phone's own copy: a mark beside the title, no sentence */
body:not(.view-staff) #tab-myrides .mr-title{display:flex;align-items:center;gap:10px;}
body:not(.view-staff) #tab-myrides .mr-saved{display:inline-flex;flex:none;width:22px;height:22px;color:var(--ink-3);}
body:not(.view-staff) #tab-myrides .mr-saved svg{width:100%;height:100%;}
/* numbers that line up: the ticket's number, money, stage times */
body:not(.view-staff) :is(#tab-myrides,#tab-register) :is(.ticket-num,.cu-tr-num,.cu-tr-money,.cu-tk-total-v,.tk-st-s,.wl-v,.cu-tr-dur,.cu-tr-in,.cu-tr-out){font-variant-numeric:tabular-nums;}
/* a pass out of the stack morphs from its strip (_wlToggle, a View Transition, Baseline since October 2025) */
::view-transition-group(mr-pass){animation-duration:.36s;animation-timing-function:cubic-bezier(.2,.8,.2,1);}
@media (prefers-reduced-motion:reduce){::view-transition-group(*),::view-transition-old(*),::view-transition-new(*){animation:none!important;}}
/* ═══════════════════════════════════ END CUSTOMER SYSTEM ═══════════════════════════════════════ */

/* The MicroMobility logo in the booking card's top start corner (the owner, 2026-09-30; _tkLogo).
   The QR code sits at the end on the My Bookings card, so the start corner is the free one. The
   dark-lettered logo on a light card, the white-lettered one on a dark card. */
.ticket-card>.tk-logo{position:absolute;top:14px;inset-inline-start:16px;z-index:1;line-height:0;pointer-events:none;}
/* My Bookings: the logo heads the number's column, in the flow, and the header starts at the top. */
.ticket-num-block>.tk-logo{display:block;line-height:0;margin-bottom:10px;}
/* The card after booking centres its top line: it starts below the logo, so a long one (the waitlist's)
   never runs under it. A "Bike 2 / 2" label above it is short and sits beside the logo. */
.ticket-card>.tk-logo+.ticket-top{padding-top:68px;}
.ticket-header:has(>.ticket-num-block>.tk-logo){align-items:flex-start;}
.ticket-card .tk-logo img{height:44px;width:auto;}
.ticket-card .tk-logo-d{display:none;}
:is(.ticket-card.tk-live,.ticket-card.ev-snd96,html[data-theme="dark"] body.view-staff .ticket-card) .tk-logo-l{display:none;}
:is(.ticket-card.tk-live,.ticket-card.ev-snd96,html[data-theme="dark"] body.view-staff .ticket-card) .tk-logo-d{display:inline;}

/* ── Staff Settings (2026-10-02): the account's own page; and the bell's one-line-per-thing rows ── */
#tab-settings .set-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(300px,100%),1fr));gap:16px;align-items:start;} /* min(): a phone at Text size 115/130% (zoom) is narrower than 300px */
#tab-settings .set-grid>*{min-width:0;}
#tab-settings .set-card{display:flex;flex-direction:column;gap:10px;margin:0;}
#tab-settings .set-card .form-group{margin:0;}
#tab-settings .set-photo-row{display:flex;align-items:center;gap:14px;}
#tab-settings .set-avatar{width:72px;height:72px;border-radius:50%;flex:none;display:flex;align-items:center;justify-content:center;overflow:hidden;background:rgba(var(--green-rgb),.12);color:var(--green);font-weight:600;font-size:var(--sf-fs-xl);}
#tab-settings .set-avatar img{width:100%;height:100%;object-fit:cover;display:block;}
#tab-settings .set-photo-btns{display:flex;gap:8px;flex-wrap:wrap;}
#tab-settings .set-file{position:relative;overflow:hidden;cursor:pointer;display:inline-flex;align-items:center;}
#tab-settings .set-file-in{position:absolute;inset:0;opacity:0;cursor:pointer;width:100%;height:100%;}
#tab-settings .set-k{font-size:var(--sf-fs-xs);font-weight:600;letter-spacing:0;text-transform:none;color:var(--muted);}
#tab-settings .set-v{font-weight:600;word-break:break-all;margin-top:-6px;}
#tab-settings .set-hint{font-size:var(--sf-fs-xs);color:var(--muted);}
#tab-settings .set-tog .set-hint{display:block;font-weight:400;}
#tab-settings .set-err{font-size:var(--sf-fs-sm);color:var(--red,#c0392b);min-height:0;}
#tab-settings .set-err:empty{display:none;}
#tab-settings .set-hr{border:0;border-top:1px solid var(--border);margin:6px 0;}
#tab-settings .set-card>button{align-self:flex-start;}
#tab-settings .set-togs{display:flex;flex-direction:column;}
#tab-settings .set-tog{display:flex;align-items:center;gap:10px;padding:10px 0;border-bottom:1px solid var(--border);cursor:pointer;font-size:var(--sf-fs-md);text-transform:none;letter-spacing:0;font-weight:600;color:var(--text);margin:0;}
#tab-settings .set-tog:last-child{border-bottom:0;}
#tab-settings .set-tog input{-webkit-appearance:checkbox;appearance:checkbox;width:18px;height:18px;min-height:0;margin:0;flex:none;accent-color:var(--green);}
.op-chip .op-chip-ph{width:20px;height:20px;border-radius:50%;object-fit:cover;display:block;flex:none;}
#nt-panel .nt-row .nt-txt{flex:1;min-width:0;}
#nt-panel .nt-row .nt-ago{flex:none;color:var(--muted);font-size:var(--staff-fs-sm,12px);white-space:nowrap;margin-top:1px;}

/* ── Message templates (Settings, admins, 2026-10-02) ── */
#tab-settings .set-wide{grid-column:1/-1;}
:is(#tab-settings,#tab-community) .tpl-grp{display:flex;flex-direction:column;margin-top:6px;}
:is(#tab-settings,#tab-community) .tpl-row{display:flex;align-items:center;gap:10px;width:100%;padding:10px 0;border:0;border-bottom:1px solid var(--border);background:none;font:inherit;font-size:var(--sf-fs-md);font-weight:600;color:var(--text);text-align:start;cursor:pointer;}
:is(#tab-settings,#tab-community) .tpl-row>span:first-child{flex:1;}
:is(#tab-settings,#tab-community) .tpl-row:hover .tpl-edit{text-decoration:underline;}
:is(#tab-settings,#tab-community) .tpl-own{font-size:var(--staff-fs-sm,12px);font-weight:600;padding:2px 8px;border-radius:var(--sf-r-pill,var(--sf-r-pill));color:var(--green);background:rgba(var(--green-rgb),.1);}
:is(#tab-settings,#tab-community) .tpl-edit{font-size:var(--sf-fs-sm);color:var(--green);}
.rm-langs{display:flex;gap:8px;margin:0 0 10px;}

/* ── Settings > Business / Pricing, saved views, KPI targets, Team accounts (2026-10-09) ── */
#tab-settings .set-views{margin:4px 0 14px;flex-wrap:wrap;}
#tab-settings .biz-pair{border:1px solid var(--border);border-radius:var(--sf-r-ctl);padding:10px 12px;margin:0;display:flex;flex-direction:column;gap:8px;min-width:0;}
#tab-settings .biz-pair legend{font-size:var(--sf-fs-xs);font-weight:600;color:var(--muted);padding:0 4px;}
#tab-settings .biz-checks{border:0;padding:0;margin:0;min-width:0;}
#tab-settings .biz-checks legend{font-size:var(--sf-fs-xs);font-weight:600;color:var(--muted);padding:0;margin-bottom:2px;}
#tab-settings .biz-kpi{display:grid;grid-template-columns:repeat(auto-fit,minmax(160px,1fr));gap:10px;}
#tab-settings .biz-kpi .form-group{margin:0;}
#tab-settings textarea{width:100%;min-height:64px;resize:vertical;}
#tab-settings .ret-prev{font-size:var(--sf-fs-sm);color:var(--text);background:rgba(var(--green-rgb),.08);border-radius:var(--sf-r-ctl);padding:8px 10px;}
#tab-settings .tm-op-acts{display:flex;gap:8px;flex-wrap:wrap;}
#tab-settings .tm-op-acts button,#tab-settings .set-card>button{min-height:44px;}
#tab-settings .pr-table input{width:100%;min-width:84px;max-width:140px;}
#tab-settings .pr-table th[scope="row"]{white-space:nowrap;text-align:start;}
#tab-settings .tm-note{margin:0 0 12px;}
.sv-bar{display:flex;align-items:flex-end;gap:8px;flex-wrap:wrap;margin:8px 0 4px;}
.sv-bar .sv-lbl{display:flex;flex-direction:column;gap:2px;min-width:0;margin:0;}
.sv-bar .sv-pick{max-width:260px;min-height:38px;}
.sv-bar button{min-height:var(--sf-ctl-size);}
.sv-box{max-width:420px;width:calc(100% - 32px);}
.sv-box .modal-footer,.tm-pwd-box .modal-footer{display:flex;gap:8px;justify-content:flex-end;flex-wrap:wrap;}
.kpi-card{margin:0 0 16px;}
.kpi-card .kpi-rows{display:grid;grid-template-columns:repeat(auto-fit,minmax(200px,1fr));gap:12px 18px;}
.kpi-card .kpi-top{display:flex;justify-content:space-between;gap:8px;font-size:var(--sf-fs-sm);color:var(--muted);margin-bottom:6px;}
.kpi-card .kpi-top b{color:var(--text);font-variant-numeric:tabular-nums;}
.kpi-card .kpi-bar{height:8px;border-radius:var(--sf-r-pill,var(--sf-r-pill));background:var(--s3);overflow:hidden;}
.kpi-card .kpi-bar span{display:block;height:100%;width:var(--kpi-w,0%);background:var(--green);border-radius:inherit;}
#tab-team .tm-meta{align-items:center;flex-wrap:wrap;gap:8px;font-size:var(--sf-fs-sm);}
