#tab-team .tm-invite .tm-add{flex-wrap:wrap;}
#tab-team .tm-invite .tm-add input{flex:1 1 200px;min-width:0;}
#tab-team .tm-invite .tm-add select{flex:0 1 180px;min-height:var(--sf-ctl-size);}
.tm-pwd-box{max-width:420px;width:calc(100% - 32px);}
.tm-pwd-box .tm-pwd{font-family:var(--font-mono);font-size:var(--sf-fs-xl);font-weight:600;letter-spacing:0;text-align:center;padding:14px;border:1px dashed var(--border);border-radius:var(--sf-r-ctl);margin:12px 0;user-select:all;}
#tab-messages .sm-assign{display:inline-flex;align-items:center;gap:6px;margin:0;margin-inline-start:auto;}
#tab-messages .sm-assign select{min-height:var(--sf-ctl-size);max-width:200px;}
/* ── Settings > Personal and Display (2026-10-09): the staffer's own choices ── */
.tpl-box .rm-langs{flex-wrap:wrap;}
#tab-settings .set-seg{display:flex;flex-wrap:wrap;gap:8px;}
#tab-settings .set-seg .toggle-btn{min-height:44px;min-width:64px;}
#tab-settings .set-tb{border:0;padding:0;margin:0;min-width:0;display:flex;flex-direction:column;gap:6px;}
#tab-settings .set-tb>button{align-self:flex-start;}
#tab-settings .set-tog input:disabled+span{color:var(--muted);}
/* Text size: the staff layer is drawn in px, so the browser's own font size changes nothing; the staff page is
   zoomed instead (layout, tap targets and pop-ups grow together, and the width a phone lays out shrinks with it). */
html[data-staff-fs="115"] body.view-staff{zoom:1.15;}
html[data-staff-fs="130"] body.view-staff{zoom:1.3;}
/* Density: Compact packs the rows of every staff table and list from tablet width up; a phone keeps its 44px
   targets, and a touch screen's buttons never go under 24px. The Bookings roster keeps its own switch. */
@media (min-width:768px){
  html[data-staff-density="compact"] body.view-staff #view-staff table:not(.queue-table) :is(th,td),
  html[data-staff-density="compact"] body.view-staff #view-staff :is(.bk-table,.pt-table) :is(th,td){padding-top:4px;padding-bottom:4px;}
  html[data-staff-density="compact"] body.view-staff #view-staff :is(.ca-row,.lg-row,.tpl-row,.hist-row){padding-top:6px;padding-bottom:6px;}
  html[data-staff-density="compact"] body.view-staff #view-staff :is(.set-tog,.hl-item){padding-top:6px;padding-bottom:6px;}
  html[data-staff-density="compact"] body.view-staff #view-staff :is(.chart-card,.stat-card,.form-section){padding:12px;}
}
@media (min-width:768px) and (pointer:coarse){
  html[data-staff-density="compact"] body.view-staff #view-staff :is(td,.ca-row,.lg-row) :is(button,a.btn-sm){min-height:24px;min-width:24px;}
}
.rm-langs .toggle-btn{flex:1;}
.tpl-fills{display:flex;flex-wrap:wrap;gap:6px;align-items:center;margin:0 0 8px;}
.tpl-fill{border:1px solid var(--border);background:var(--s3);color:var(--text);border-radius:var(--sf-r-ctl);padding:3px 8px;font:inherit;font-size:var(--sf-fs-xs);font-family:ui-monospace,Menlo,monospace;cursor:pointer;}


/* ── One button size across the staff site (the owner, 2026-10-02: "align all buttons in staff website to be
   the same size and aligned properly"). Every button is 38px high on a desk and 44px on a phone, with one
   padding, type size and corner; its words sit centred on one line. In a dialog's row of buttons each takes
   an equal share of the row. Icon-only buttons stay square. The booking tiles follow the same heights. ── */
/* how a button lays out its words: as weak as a rule can be, so a section's own display:none (a button
   kept off the phone) still wins */
:where(body.view-staff) :where(.btn-primary,.btn-secondary,.btn-sm,.btn-muted,.btn-green,.btn-red,.rq-print,.toggle-btn,.sl-pay){display:inline-flex;align-items:center;justify-content:center;}
body.view-staff :is(.btn-primary,.btn-secondary,.btn-sm,.btn-muted,.btn-green,.btn-red,:is(#tab-queue,#tab-waitlist) .rq-print){
  min-height:var(--sf-ctl-size);padding-top:0;padding-bottom:0;padding-inline:14px;box-sizing:border-box;
  gap:6px;
  font-size:var(--sf-fs-sm);font-weight:600;line-height:1.15;border-radius:var(--sf-r-ctl);vertical-align:middle;text-align:center;
}
body.view-staff :is(#tab-queue,#tab-waitlist) .rq-print{background:var(--sf-card);border:1px solid var(--sf-line);color:var(--text);}
/* the choice buttons (payment, bike type, group, a dialog's options) take the same height, words centred */
body.view-staff :is(.toggle-btn,.sl-pay){min-height:var(--sf-ctl-size);box-sizing:border-box;line-height:1.15;}
body.view-staff .sl-pay{border-radius:var(--sf-r-ctl);padding-block:0;}
body.view-staff :is(.btn-sm,.btn-secondary,.btn-muted)[aria-label]:not(:has(span,b)):empty{width:38px;padding-inline:0;}
body.view-staff :is(#tab-queue,#tab-waitlist) :is(.queue-table .actions-cell,.q-card .rq-flw6)>*{height:38px;min-height:38px;font-size:var(--sf-fs-sm);}
body.view-staff :is(.modal-footer,.chrome-dact)>:is(.btn-primary,.btn-secondary,.btn-sm,.btn-muted,.btn-green,.btn-red,a.btn-secondary){flex:1 1 0;min-width:0;}
body.view-staff :is(.modal-footer,.chrome-dact){display:flex;gap:8px;align-items:stretch;}
/* .ca-actions also holds a list row's many actions (a sign-up's six): each keeps its words' width, the row
   grows them to fill it, and wraps rather than squeezing them */
body.view-staff .ca-actions{display:flex;flex-wrap:wrap;gap:8px;align-items:stretch;}
body.view-staff .ca-actions>:is(.btn-primary,.btn-secondary,.btn-sm,.btn-muted,.btn-green,.btn-red,a.btn-secondary){flex:1 1 auto;}
@media(max-width:767px){
  body.view-staff :is(.btn-primary,.btn-secondary,.btn-sm,.btn-muted,.btn-green,.btn-red,:is(#tab-queue,#tab-waitlist) .rq-print){min-height:44px;}
  body.view-staff :is(.toggle-btn,.sl-pay){min-height:44px;}
  body.view-staff :is(#tab-queue,#tab-waitlist) :is(.queue-table .actions-cell,.q-card .rq-flw6)>*{height:44px;min-height:44px;font-size:var(--sf-fs-sm);}
}

/* ── The roster fits a laptop (2026-10-03): at 1280px the table was ~1560px wide and pushed Check In /
   Return Bike off the screen. Height and size sit under the bike type, the call / WhatsApp pair under
   the rider's number, and the booking time, add-on chips and the price's breakdown wrap instead of
   holding their columns open. The Manage booking tiles keep the owner's equal-size grid (2026-10-02). ── */
:is(#tab-queue,#tab-waitlist) .queue-table .q-type-cell{white-space:nowrap;}
:is(#tab-queue,#tab-waitlist) .queue-table .q-type-cell .q-fit{margin-top:6px;line-height:1.15;}
:is(#tab-queue,#tab-waitlist) .queue-table .q-type-cell .q-size{display:inline-block;margin-inline-start:4px;}
:is(#tab-queue,#tab-waitlist) .queue-table .rq-ccin{margin-top:6px;}
:is(#tab-queue,#tab-waitlist) .queue-table .rq-bkat{white-space:normal;display:block;max-width:6.5em;line-height:1.25;}
:is(#tab-queue,#tab-waitlist) .queue-table .rq-adchip{white-space:normal;}
:is(#tab-queue,#tab-waitlist) .queue-table .rq-adline{white-space:normal;max-width:9em;}
:is(#tab-queue,#tab-waitlist) .queue-table td:has(> .rq-rc),:is(#tab-queue,#tab-waitlist) .queue-table td:has(> .rider-name){min-width:136px;max-width:15em;}
:is(#tab-queue,#tab-waitlist) .queue-table thead th{letter-spacing:0;}
/* The sort headers are buttons in the header cells (2026-10-05): drawn as the header's own words, a
   ring only for the keyboard. */
:is(#tab-queue,#tab-waitlist) .queue-table thead th .q-sort-btn{display:inline;margin:0;padding:0;border:0;border-radius:var(--sf-r-xs);background:transparent none;color:inherit;font:inherit;letter-spacing:inherit;text-transform:inherit;text-align:inherit;white-space:nowrap;cursor:pointer;min-height:0;}
:is(#tab-queue,#tab-waitlist) .queue-table thead th .q-sort-btn:focus-visible{outline:2px solid var(--sf-green-ink,var(--green));outline-offset:2px;}
/* Phone (2026-10-03): the ride strip's select is the one ride picker (it lists past nights too), and the
   page title is dropped - the Bookings pill above already names the page - so the first rider moves up. */
@media (max-width:767px){
  body.view-staff :is(#tab-queue,#tab-waitlist) .filter-sess-dup{display:none;}
  body.view-staff :is(#tab-queue,#tab-waitlist) .q-head-title{display:none;}
}

/* ── Sales lines up with the other sections (2026-10-03): its wrapper carried its own 20px inset, so the
   title and cards jumped sideways when switching from Bookings or Inventory. Category and item names
   take two lines before they are cut ("Supplements…"). ── */
body.view-staff #tab-cashier .sl-wrap{padding-inline:0;}
#tab-cashier .sl-tile-nm{white-space:normal;display:-webkit-box;-webkit-box-orient:vertical;-webkit-line-clamp:2;line-clamp:2;line-height:1.25;overflow-wrap:anywhere;}

/* ── Hand-over (2026-10-03): the bike-number box no longer spans the page; with nobody waiting for a bike
   it folds away, since there is no one to give one to. ── */
body.view-staff .ho-give{max-width:640px;}
body.view-staff .ho-give.ho-give-idle{display:none;}
/* the fleet row's actions: Edit, maybe Found, and the ⋯ menu, on one line (2026-10-03) */
body.view-staff #tab-inventory .actions-cell.flt-acts{flex-wrap:nowrap;min-width:0;}
body.view-staff #tab-inventory .actions-cell.flt-acts>.rq-more{flex:0 0 auto;min-width:36px;}
/* Wide fleet tables scroll sideways inside their box; Manage bike stays pinned at the end so Edit and the
   menu are always on screen (2026-10-03). Phones show cards instead and are left alone. */
@media (min-width:768px){
  body.view-staff #tab-inventory .bk-table :is(thead th,tbody td):last-child{position:sticky;inset-inline-end:0;z-index:2;background:var(--s1);box-shadow:-1px 0 0 var(--border);}
  html[dir="rtl"] body.view-staff #tab-inventory .bk-table :is(thead th,tbody td):last-child{box-shadow:1px 0 0 var(--border);}
  body.view-staff #tab-inventory .bk-table thead th:last-child{background:var(--sf-head,var(--s1));z-index:3;}
}
body.view-staff .dash-empty-go{margin-top:10px;}
/* The Today page's ways on from each session and its added cards (2026-11-06, ST10) */
body.view-staff .dash-row:has(+.dash-jumps){border-bottom:0;padding-bottom:4px;}
body.view-staff .dash-jumps{display:flex;flex-wrap:wrap;gap:6px;padding:0 4px 10px;padding-inline-start:22px;border-bottom:1px solid var(--sf-line2);}
body.view-staff .dash-jumps:last-child{border-bottom:0;}
body.view-staff .dash-more{padding:8px 4px 0;color:var(--muted);font-size:var(--staff-fs-sm);}
/* Team: what an account can do, in words (2026-11-06, ST12) */
body.view-staff .tm-can{display:flex;flex-direction:column;gap:2px;padding:8px 10px;border-inline-start:3px solid var(--sf-line2);background:var(--sf-head);font-size:var(--sf-fs-sm);}
body.view-staff .tm-can-k{font-weight:600;color:var(--muted);}

/* ── The keyboard shortcuts list ("?", 2026-10-03) ── */
.kb-list{display:flex;flex-direction:column;gap:2px;}
.kb-row{display:flex;align-items:center;gap:12px;padding:6px 0;border-bottom:1px solid var(--border);font-size:var(--sf-fs-md);}
.kb-row:last-child{border-bottom:0;}
.kb-row.kb-sub{padding-top:14px;font-weight:600;color:var(--muted);font-size:var(--sf-fs-sm);}
.kb-keys{flex:0 0 92px;display:inline-flex;gap:4px;}
.kb-row kbd{display:inline-block;min-width:22px;padding:2px 6px;border:1px solid var(--border);border-bottom-width:2px;border-radius:var(--sf-r-ctl);background:var(--s2,#f6f6f2);font:600 var(--sf-fs-xs)/1.4 ui-monospace,Menlo,monospace;text-align:center;color:var(--text);}
#bike-modal .bkm-tr:focus-visible{outline-offset:-2px;}

/* WCAG 2.4.11: a control or row that takes the focus is never left under the sticky top bar (or the
   phone's bottom bar): the page scrolls it clear. --topbar-h is the bar's measured height. */
/* On Bookings the night's figures bar, the selection's actions and the table's header stick under the top bar too: the
   padding is the whole stack (--q-stack, measured by _lcStick; 0 while Bookings is not on screen), staff round s10 */
html:has(body.view-staff){scroll-padding-top:calc(var(--topbar-h,56px) + var(--q-stack,0px) + 12px);scroll-padding-bottom:84px;}

/* ════════════════════════════════════════════════════════════════════════
   RUN FOR HER (the owner, 2026-10-05) - a running event for community members.
   The card on the event picker: "themed like this instagram post", picked "C, Blush" - white like
   the MicroMobility Experiences card, the poster's pink washed in from the far corner, the three
   partners' marks as the poster sets them (one picture, assets/runher-partners.webp, so it shrinks as
   one and never leaves the card), the title in the poster's lettering (Marcellus, fonts/fonts.css),
   and the poster's route drawn along the bottom: start and finish, along the water, the 3 km turn and
   the 5 km turn (_runRouteSvg). Every part stays inside the card at any width: the copy wraps, the
   marks scale down with the card and the route is as wide as the card.
   ════════════════════════════════════════════════════════════════════════ */
:root{--rf-pink:#E8628E;--rf-pink-dk:#C2416E;--rf-ink:#14304D;--rf-wash:242,120,159;}
.ev-runher{--ev:#C2416E;--ev-rgb:194,65,110;}
body:not(.view-staff) .ev-runher:not(.landing-event-card){--ev:#C2416E;--ev-rgb:194,65,110;}
body .landing-event-card.ev-runher{
  gap:12px;
  background-color:#fff;
  background-image:radial-gradient(120% 140% at 100% 100%,rgba(var(--rf-wash),.26) 0%,rgba(var(--rf-wash),.1) 38%,rgba(255,255,255,0) 66%);
  border:1px solid rgba(217,79,126,.32);
  box-shadow:0 1px 3px rgba(26,25,25,.22);
  color:var(--rf-ink);
}
html[dir="rtl"] body .landing-event-card.ev-runher{
  background-image:radial-gradient(120% 140% at 0% 100%,rgba(var(--rf-wash),.26) 0%,rgba(var(--rf-wash),.1) 38%,rgba(255,255,255,0) 66%);
}
body .landing-event-card.ev-runher:hover{border-color:var(--rf-pink);transform:none;box-shadow:0 8px 24px rgba(194,65,110,.22);}
body .landing-event-card.ev-runher::before{display:none;}
body .landing-event-card.ev-runher .lec2-copy{width:100%;min-width:0;max-width:100%;}
body .landing-event-card.ev-runher .lec-title{
  font-family:'Marcellus','Space Grotesk','Noto Sans Devanagari','Noto Sans Bengali',Georgia,serif;
  font-weight:400;font-style:normal;text-transform:uppercase;font-size:27px;letter-spacing:.6px;line-height:1.08;
  color:var(--rf-ink);overflow-wrap:anywhere;
}
/* Arabic and Urdu: the poster face has no Arabic letters, and spaced capitals break the joins */
:is(html[lang="ar"],html[lang="ur"]) body .landing-event-card.ev-runher .lec-title{
  font-family:'IBM Plex Sans Arabic',sans-serif;font-weight:700;font-size:23px;letter-spacing:0;text-transform:none;line-height:1.3;
}
body .landing-event-card.ev-runher .rf-meta{
  display:flex;flex-wrap:wrap;align-items:center;gap:4px 9px;margin-top:9px;
  font-size:13px;font-weight:700;color:var(--rf-pink-dk);letter-spacing:.2px;max-width:100%;
}
body .landing-event-card.ev-runher .rf-meta i{width:1px;height:12px;background:rgba(194,65,110,.4);display:inline-block;flex:none;}
body .landing-event-card.ev-runher .rf-logos{height:46px;max-width:100%;}
body .landing-event-card.ev-runher .rf-logos img{height:100%;width:auto;max-width:100%;object-fit:contain;object-position:0 50%;}
html[dir="rtl"] body .landing-event-card.ev-runher .rf-logos img{object-position:100% 50%;}
body .landing-event-card.ev-runher .rf-route{display:block;width:100%;max-width:100%;height:auto;margin-top:auto;overflow:visible;}
.rf-route .rf-line{fill:none;stroke:var(--rf-pink);stroke-width:2.6;stroke-linecap:round;stroke-linejoin:round;}
.rf-route .rf-start{fill:none;stroke:var(--rf-pink);stroke-width:2.2;}
.rf-route .rf-dot{fill:var(--rf-pink);}
.rf-route .rf-turn{fill:#fff;stroke:var(--rf-pink);stroke-width:2;}
.rf-route .rf-pill rect{fill:var(--rf-pink);}
.rf-route .rf-pill text{fill:#fff;font:700 8.6px/1 'Space Grotesk',sans-serif;letter-spacing:.3px;}
.rf-route .rf-pill path{fill:none;stroke:var(--rf-pink);stroke-width:1.2;}
@media (max-width:640px){
  body .landing-event-card.ev-runher .lec-title{font-size:24px;}
  :is(html[lang="ar"],html[lang="ur"]) body .landing-event-card.ev-runher .lec-title{font-size:21px;}
  body .landing-event-card.ev-runher .rf-logos{height:40px;}
}

/* The runner step: the two distances as two large equal buttons, then only what the account lacks. */
.run-panel .run-adult{margin:0 0 14px;font-size:14px;font-weight:600;color:var(--rf-pink-dk);}
.run-panel .run-km{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px;}
.run-panel .run-km .toggle-btn{min-height:56px;font-size:18px;font-weight:700;width:100%;}
.run-panel .run-h{margin:18px 0 8px;font-size:15px;font-weight:700;}
.run-panel .run-sub{margin:-2px 0 12px;font-size:13px;color:var(--muted);}
.run-panel .run-wait{padding:18px 0;color:var(--muted);}
.run-em-card{display:flex;align-items:center;gap:12px;padding:12px 14px;border:1px solid var(--border,rgba(26,25,25,.14));border-radius:10px;}
.run-em-n{font-weight:700;overflow-wrap:anywhere;}
.run-em-m{font-size:13px;color:var(--muted);margin-top:2px;overflow-wrap:anywhere;}
.run-em-who{font-weight:700;margin-bottom:10px;}
.run-km-chip{display:inline-flex;align-items:center;padding:2px 9px;border-radius:999px;font-size:12px;font-weight:700;line-height:1.5;white-space:nowrap;color:var(--rf-pink-dk);background:rgba(var(--rf-wash),.16);}
.run-km-chip.rk-5{color:#fff;background:var(--rf-pink-dk);}

/* ════════════════════════════════════════════════════════════════════════
   VICTORY LAP by Fitness Empire (the owner, 2026-10-17) - a hybrid fitness race run by Kamin Sports.
   The card on the event picker: the owner picked D - white, the race's logo (assets/victory-lap-dark.webp),
   what it is and when, a checkered flag down the end edge, no price. Every part stays inside the card
   at any width: the copy wraps, the logo scales down with the card, the flag keeps its strip.
   ════════════════════════════════════════════════════════════════════════ */
:root{--vl-ink:#0d0d0d;--vl-purple:#5b3fd6;--vl-checker:linear-gradient(45deg,#fff 25%,transparent 25%,transparent 75%,#fff 75%),linear-gradient(45deg,#fff 25%,transparent 25%,transparent 75%,#fff 75%);}
.ev-vlap{--ev:#0d0d0d;--ev-rgb:13,13,13;}
body:not(.view-staff) .ev-vlap:not(.landing-event-card){--ev:#0d0d0d;--ev-rgb:13,13,13;}
body .landing-event-card.ev-vlap{
  flex-direction:row;align-items:stretch;gap:0;padding:0;overflow:hidden;
  background:#fff;border:1px solid rgba(13,13,13,.22);box-shadow:0 1px 3px rgba(26,25,25,.22);color:var(--vl-ink);
}
body .landing-event-card.ev-vlap:hover{border-color:var(--vl-ink);transform:none;box-shadow:0 8px 24px rgba(13,13,13,.18);}
body .landing-event-card.ev-vlap::before{display:none;}
body .landing-event-card.ev-vlap .vl-card-main{flex:1 1 auto;min-width:0;display:flex;flex-direction:column;justify-content:space-between;gap:16px;padding:22px 20px 18px 24px;}
html[dir="rtl"] body .landing-event-card.ev-vlap .vl-card-main{padding:22px 24px 18px 20px;}
body .landing-event-card.ev-vlap .vl-logo{order:0;height:58px;max-width:100%;}
body .landing-event-card.ev-vlap .vl-logo img{height:100%;width:auto;max-width:100%;object-fit:contain;object-position:0 50%;}
html[dir="rtl"] body .landing-event-card.ev-vlap .vl-logo img{object-position:100% 50%;}
body .landing-event-card.ev-vlap .lec2-copy{min-width:0;max-width:100%;}
body .landing-event-card.ev-vlap .lec-title{font-size:16px;font-weight:700;font-style:normal;text-transform:none;letter-spacing:0;line-height:1.3;color:var(--vl-ink);overflow-wrap:anywhere;}
body .landing-event-card.ev-vlap .vl-meta{display:flex;flex-wrap:wrap;align-items:center;gap:4px 9px;margin-top:6px;font-size:13px;font-weight:600;color:#4a4a46;max-width:100%;}
body .landing-event-card.ev-vlap .vl-meta i{width:1px;height:12px;background:rgba(13,13,13,.3);display:inline-block;flex:none;}
body .landing-event-card.ev-vlap .vl-flag{flex:0 0 44px;background-color:var(--vl-ink);background-image:var(--vl-checker);background-size:16px 16px;background-position:0 0,8px 8px;}
@media (max-width:640px){
  body .landing-event-card.ev-vlap .vl-logo{height:50px;}
  body .landing-event-card.ev-vlap .vl-flag{flex-basis:36px;}
}
.ev-name.ev-vlap{color:var(--vl-ink);}
body .lec-wrap .lec-about.ab-vlap{inset-inline-start:25px;} /* under the words (the card's edge and .vl-card-main's padding), not 3-5px off them */
.vl-no-flag{color:var(--vl-ink);}

/* The athlete step: the races as large buttons (name, then on your own / with a partner), the team's three
   ways in, the divisions with their stations, the T-shirt sizes and the 5 km time in even grids. */
.vl-panel .run-adult{color:var(--vl-ink);}
.vl-panel .vl-races{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:8px;}
.vl-panel .vl-race,.vl-divs .vl-div{display:flex;flex-direction:column;align-items:flex-start;gap:3px;width:100%;min-height:56px;padding:10px 12px;text-align:start;
  background:#fff;border:1px solid rgba(26,25,25,.18);color:var(--text,#1A1919);cursor:pointer;font:inherit;}
.vl-panel .vl-race:hover:not(:disabled),.vl-divs .vl-div:hover:not(:disabled){border-color:var(--vl-ink);}
.vl-panel .vl-race.active,.vl-divs .vl-div.active{border:2px solid var(--vl-ink);padding:9px 11px;background:#f6f6f3;}
.vl-panel .vl-race:disabled{opacity:.5;cursor:not-allowed;}
.vl-panel .vl-race-n{font-weight:700;font-size:15px;}
.vl-panel .vl-race-s{font-size:12px;color:var(--muted);}
.vl-divs{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:8px;}
.vl-divs .vl-div-h{display:flex;align-items:baseline;justify-content:space-between;gap:8px;width:100%;}
.vl-divs .vl-div-h b{font-size:15px;}
.vl-divs .vl-div-h span{font-size:13px;font-weight:700;color:var(--vl-purple);white-space:nowrap;}
.vl-div-w{font-size:12px;line-height:1.45;color:var(--muted);}
.vl-locked{padding:10px 12px;border:1px dashed rgba(26,25,25,.3);font-weight:700;}
.vl-locked .vl-div-w{font-weight:400;margin-top:3px;}
.vl-sizes{display:grid;grid-template-columns:repeat(6,minmax(0,1fr));gap:6px;}
.vl-t5{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:6px;}
.vl-sizes .toggle-btn,.vl-t5 .toggle-btn{width:100%;min-height:44px;}
.vl-modes{display:grid;grid-template-columns:repeat(auto-fit,minmax(130px,1fr));gap:6px;}
.vl-modes .toggle-btn{width:100%;min-height:44px;}
.vl-code-row{display:flex;gap:8px;margin-top:8px;}
.vl-code-row input{flex:1 1 auto;min-width:0;font-weight:700;letter-spacing:1px;text-transform:uppercase;}
.vl-peek{display:flex;align-items:flex-start;gap:8px;margin-top:10px;padding:10px 12px;font-size:14px;border:1px solid rgba(26,25,25,.14);}
.vl-peek-ok{border-color:rgba(0,113,63,.4);background:#f1f8f4;color:#06603b;}
.vl-peek-bad{border-color:rgba(180,35,24,.35);background:#fdf1f1;color:#b42318;}
@media (max-width:420px){
  .vl-panel .vl-races,.vl-divs{grid-template-columns:minmax(0,1fr);}
  .vl-sizes{grid-template-columns:repeat(3,minmax(0,1fr));}
}
.vl-chip{display:inline-flex;align-items:center;padding:2px 9px;font-size:12px;font-weight:700;line-height:1.5;color:#fff;background:var(--vl-ink);white-space:normal;}
/* Men only, women only or mixed (2026-10-27): the chip a session wears wherever it is shown (_sgChip). */
.sg-chip{display:inline-flex;align-items:center;padding:2px 9px;font-size:12px;font-weight:700;line-height:1.5;color:#fff;background:#56616b;white-space:nowrap;vertical-align:middle;}
.sg-chip.sg-male{background:#1f6fb8;}
.sg-chip.sg-female{background:#c2185b;}
.vl-rv-sub{display:flex;flex-wrap:wrap;gap:4px 12px;font-size:12px;color:var(--muted);}
.vl-pay-note{margin-top:8px;}

/* The ticket (My Bookings and the one just booked): white, the logo, the checkered strip down the end edge as
   on the card; the team's code large, the partner, the T-shirt, how to pay. */
body:not(.view-staff) :is(#tab-myrides,#tab-register) .ticket-card.tk-th.th-vlap{
  --night:#fff;--night-ink:#0d0d0d;--night-ink-2:rgba(13,13,13,.62);--night-line:rgba(13,13,13,.14);--night-2:#f4f4f1;--neon:#5b3fd6;
  --night-amber:#8A5300;--night-red:#B42318;--night-red-line:rgba(180,35,24,.35);color:var(--night-ink);
  background:#fff;border:1px solid rgba(13,13,13,.28);padding-inline-end:36px;}
body:not(.view-staff) :is(#tab-myrides,#tab-register) .ticket-card.tk-th.th-vlap::before{display:block;content:'';position:absolute;top:0;bottom:0;left:auto;right:0;width:20px;height:auto;
  background-color:var(--vl-ink);background-image:var(--vl-checker);background-size:10px 10px;background-position:0 0,5px 5px;pointer-events:none;}
html[dir="rtl"] body:not(.view-staff) :is(#tab-myrides,#tab-register) .ticket-card.tk-th.th-vlap::before{right:auto;left:0;}
.ticket-card .tk-logo-ev .tk-logo-vlap{height:34px;}
.vl-tk-wrap{margin-top:12px;}
.vl-tk-team{margin-top:12px;padding:12px 14px;border:1px solid rgba(13,13,13,.18);background:#f6f6f3;}
.vl-tk-code{display:flex;align-items:baseline;justify-content:space-between;gap:10px;font-size:12px;font-weight:700;color:var(--muted);}
.vl-tk-code strong{font-size:22px;letter-spacing:1.5px;color:#0d0d0d;}
.vl-tk-p{margin-top:4px;font-size:14px;font-weight:600;}
.vl-tk-btns{margin-top:10px;}
.vl-tk-meta{display:flex;flex-wrap:wrap;gap:4px 14px;margin-top:10px;font-size:13px;color:var(--muted);}

/* ════════════════════════════════════════════════════════════════════════
   ARENA HEROS HYBRID RACE (the owner, 2026-10-28) - by WeSportify, Mile and Gymnation. Black with red, as the
   organisers' poster is, and since 2026-10-29 the poster itself ("add the image to the card dont keep it plain",
   "put the whole theme of the post on the event card and registration pages"): their gorilla logo
   (assets/arena-heros-logo.webp) over the red-lit hall (arena-heros-hall.webp, arena-heros-band.webp), the partners'
   marks (arena-heros-partners.webp), names in the poster's heavy italic capitals (Barlow Condensed 800 italic;
   Arabic, Urdu and the Indian scripts keep their own face, upright), red for every action and a neon red edge.
   The card, the flow (body.ar-skin, _syncArTheme: the race's date, the athlete step, the review, the booked page)
   and the ticket. Every part stays inside its box at any width, in both directions.
   ════════════════════════════════════════════════════════════════════════ */
:root{--ar-ink:#0b0b0b;--ar-red:#e3262f;--ar-red-lt:#ff5a61;--ar-glow:0 0 0 1px rgba(227,38,47,.22),0 0 22px rgba(227,38,47,.3);
  --ar-face:'Barlow Condensed','Barlow',sans-serif;}
.ev-arena{--ev:#e3262f;--ev-rgb:227,38,47;}
body:not(.view-staff) .ev-arena:not(.landing-event-card){--ev:#c81e27;--ev-rgb:200,30,39;}
/* the card: the logo where every card has its mark, the hall behind it darkening down to the words */
body .landing-event-card.ev-arena{flex-direction:column;align-items:flex-start;gap:12px;padding:20px 22px;overflow:hidden;color:#fff;
  background:linear-gradient(180deg,rgba(8,8,10,.1) 0%,rgba(8,8,10,.5) 40%,rgba(8,8,10,.92) 76%),url(/assets/arena-heros-hall.webp) center 40%/cover no-repeat,var(--ar-ink);
  border:1px solid rgba(255,90,97,.72);box-shadow:var(--ar-glow);}
body .landing-event-card.ev-arena:hover{border-color:var(--ar-red-lt);transform:none;box-shadow:0 0 0 1px rgba(255,90,97,.5),0 0 30px rgba(227,38,47,.45);}
body .landing-event-card.ev-arena::before{display:none;}
body .landing-event-card.ev-arena .ar-logo{height:84px;}
body .landing-event-card.ev-arena .ar-logo img{object-position:0 50%;}
html[dir="rtl"] body .landing-event-card.ev-arena .ar-logo img{object-position:100% 50%;}
body .landing-event-card.ev-arena .lec2-copy{width:100%;min-width:0;max-width:100%;}
body .landing-event-card.ev-arena .lec-title{font-family:var(--ar-face);font-size:27px;font-weight:800;font-style:italic;text-transform:uppercase;
  letter-spacing:.3px;line-height:1;color:#fff;overflow-wrap:anywhere;text-shadow:0 2px 12px rgba(0,0,0,.6);}
:is(html[lang="ar"],html[lang="ur"]) body .landing-event-card.ev-arena .lec-title{font-family:'IBM Plex Sans Arabic',sans-serif;font-size:21px;font-weight:700;font-style:normal;text-transform:none;letter-spacing:0;line-height:1.3;}
:is(html[lang="hi"],html[lang="ne"],html[lang="bn"]) body .landing-event-card.ev-arena .lec-title{font-family:var(--font-body);font-size:20px;font-weight:700;font-style:normal;text-transform:none;letter-spacing:0;line-height:1.3;}
body .landing-event-card.ev-arena .ar-meta{display:block;margin-top:8px;overflow:hidden;font-size:13px;font-weight:600;color:rgba(255,255,255,.88);}
body .landing-event-card.ev-arena .ar-sub{display:block;margin-top:6px;font-size:13px;font-weight:700;color:var(--ar-red-lt);}
/* a row of items with a rule between two of them; a line never starts with a rule (the row reaches 10px past its
   box at the start, where its overflow:hidden parent clips the rule each line's first item carries) */
.ar-mi{display:flex;flex-wrap:wrap;align-items:center;row-gap:3px;margin-inline-start:-10px;}
.ar-mi>span{position:relative;padding-inline-start:10px;margin-inline-end:9px;}
.ar-mi>span::before{content:'';position:absolute;inset-inline-start:0;top:50%;width:1px;height:12px;margin-top:-6px;background:currentColor;opacity:.4;}
body .lec-wrap .lec-about.ab-arena{color:#fff;inset-inline-start:23px;} /* under the words: the card's edge and its padding */
@media (max-width:640px){body .landing-event-card.ev-arena .ar-logo{height:76px;}body .landing-event-card.ev-arena .lec-title{font-size:25px;}}
.ev-name.ev-arena{color:#c81e27;}

/* the flow: the page goes black with a red glow from the top; every token the rider screens are drawn with points at
   the poster's palette (the customer system's names and the older ones that read them), so nothing in the steps has
   to know the race has its own colours. Literal light surfaces in the race's own boxes are named after it. */
html:has(> body.ar-skin:not(.view-staff)){--root-paper:#08080a;color-scheme:only dark;}
body.ar-skin:not(.view-staff){
  --paper:#08080a; --card:#131315; --card-2:#1b1b1e; --card-3:#242428;
  --ink:#ffffff; --ink-2:rgba(255,255,255,.76); --ink-3:rgba(255,255,255,.58); --ink-4:rgba(255,255,255,.38);
  --line:rgba(255,255,255,.14); --line-2:rgba(255,255,255,.3);
  --line-3:rgba(255,255,255,.42); /* a field's border, the wallet switch's off track, an open tick's ring: about 4:1 on the card */
  /* the glass bars (the Continue bar) in the race's black, under its white inks; the edge in the poster's red */
  --glass-solid:#0b0b0d; --glass:rgba(11,11,13,.82); --glass-hi:rgba(11,11,13,.9);
  --glass-rim:rgba(255,255,255,.12); --glass-rim-2:rgba(255,255,255,.06); --glass-edge:rgba(227,38,47,.42);
  --go:#e3262f; --go-2:#c81e27; --go-wash:rgba(227,38,47,.14); --neon:#ff5a61;
  --amber:#ffc46b; --amber-2:#ffc46b; --amber-wash:rgba(255,196,107,.12); --red:#ff8a8f; --red-line:rgba(255,138,143,.4);
  --scrim:rgba(0,0,0,.72); --sh-float:0 24px 60px rgba(0,0,0,.6); --accent2:rgba(227,38,47,.45);
  --green-rgb:227,38,47; --tint-rgb:255,255,255; --red-rgb:255,138,143; --orange-rgb:255,196,107; --warn-rgb:255,196,107;
  --vl-ink:#ff5a61; --vl-purple:#ff5a61;
  color-scheme:dark;
  background:radial-gradient(130% 520px at 50% 0%,rgba(227,38,47,.24) 0%,rgba(227,38,47,.07) 45%,rgba(8,8,10,0) 75%) no-repeat,var(--paper);
}
/* the bars around the flow follow it: the header (it re-points its own colours at a heavier weight), the tabs, the sections bar */
body.ar-skin:not(.view-staff) #topbar#topbar{background:#0b0b0d;border-bottom:1px solid rgba(227,38,47,.42);box-shadow:none;}
body.ar-skin:not(.view-staff) #topbar#topbar,
body.ar-skin:not(.view-staff) #topbar#topbar *{--text:#fff;--muted:rgba(255,255,255,.64);--muted-l:rgba(255,255,255,.5);--border:rgba(255,255,255,.16);--tint-rgb:255,255,255;--s1:#0b0b0d;--s2:#18181b;--s3:#18181b;}
body.ar-skin:not(.view-staff) #topbar#topbar .cust-topbar-name{color:#fff;}
body.ar-skin:not(.view-staff) #topbar#topbar :is(.cust-topbar-email,.staff-access-btn){color:rgba(255,255,255,.62);}
body.ar-skin:not(.view-staff) #topbar#topbar :is(.topbar-btn,.lang-toggle,.lang-wrap){color:rgba(255,255,255,.86);} /* the globe too: it was left olive grey on the black bar */
html body.ar-skin:not(.view-staff) #cust-bottom-nav{background:#0b0b0d;border-top:1px solid rgba(227,38,47,.42);}
html body.ar-skin .cust-bnav-btn{color:rgba(255,255,255,.6);}
html body.ar-skin .cust-bnav-btn.active{color:#fff;}
html body.ar-skin .cust-bnav-btn.active::after{background:var(--ar-red-lt);}
/* headings in the poster's face: the step's title, a panel's title, the athlete step's sections */
body.ar-skin:not(.view-staff) :is(#cu,*).page-title{font-family:var(--ar-face);font-size:36px;font-weight:800;font-style:italic;text-transform:uppercase;letter-spacing:.3px;line-height:1;}
body.ar-skin:not(.view-staff) :is(#cu,*):is(.form-title,.run-h){font-family:var(--ar-face);font-size:21px;font-weight:800;font-style:italic;text-transform:uppercase;letter-spacing:.3px;line-height:1.1;}
:is(html[lang="ar"],html[lang="ur"],html[lang="hi"],html[lang="ne"],html[lang="bn"]) body.ar-skin:not(.view-staff) :is(#cu,*):is(.page-title,.form-title,.run-h){font-family:inherit;font-style:normal;text-transform:none;letter-spacing:0;line-height:1.3;}
