body.ar-skin .vl-divs .vl-div:hover:not(:disabled){border-color:var(--ar-red-lt);}
body.ar-skin .vl-divs .vl-div.active{background:rgba(227,38,47,.12);border-color:var(--ar-red);box-shadow:0 0 18px rgba(227,38,47,.32);}
body.ar-skin .vl-divs .vl-div-h span{color:var(--ar-red-lt);}
body.ar-skin .vl-div-w{color:var(--ink-2);}
body.ar-skin .vl-locked{border-color:rgba(255,255,255,.3);}
body.ar-skin .vl-peek{border-color:var(--line-2);}
body.ar-skin .vl-peek-ok{background:rgba(134,239,172,.08);border-color:rgba(134,239,172,.4);color:#86efac;}
body.ar-skin .vl-peek-bad{background:rgba(255,138,143,.08);border-color:rgba(255,138,143,.45);color:#ff8a8f;}
body.ar-skin .vl-chip{background:var(--ar-red);}
/* the banner over every step: the partners' marks across the top, the logo, the race's name, when and where */
.ar-flow-head{position:relative;margin:0 0 18px;padding:14px 18px 16px;overflow:hidden;color:#fff;
  background:linear-gradient(180deg,rgba(8,8,10,.2) 0%,rgba(8,8,10,.62) 55%,rgba(8,8,10,.9) 100%),url(/assets/arena-heros-band.webp) center 30%/cover no-repeat,var(--ar-ink);
  border:1px solid rgba(255,90,97,.6);box-shadow:var(--ar-glow);}
.ar-flow-partners{display:block;height:26px;width:auto;max-width:100%;margin:0 auto 10px;object-fit:contain;}
.ar-flow-main{display:flex;align-items:center;gap:14px;min-width:0;}
.ar-flow-logo{flex:none;height:86px;width:auto;display:block;}
.ar-flow-copy{min-width:0;flex:1 1 auto;}
body:not(.view-staff) :is(#cu,*).ar-flow-name{font-family:var(--ar-face);font-size:28px;font-weight:800;font-style:italic;text-transform:uppercase;letter-spacing:.3px;line-height:1;overflow-wrap:anywhere;text-shadow:0 2px 12px rgba(0,0,0,.6);}
:is(html[lang="ar"],html[lang="ur"]) body:not(.view-staff) :is(#cu,*).ar-flow-name{font-family:'IBM Plex Sans Arabic',sans-serif;font-size:21px;font-weight:700;font-style:normal;text-transform:none;letter-spacing:0;line-height:1.3;}
:is(html[lang="hi"],html[lang="ne"],html[lang="bn"]) body:not(.view-staff) :is(#cu,*).ar-flow-name{font-family:var(--font-body);font-size:20px;font-weight:700;font-style:normal;text-transform:none;letter-spacing:0;line-height:1.3;}
.ar-flow-meta{margin-top:8px;overflow:hidden;font-size:13px;font-weight:600;color:rgba(255,255,255,.88);}
@media (max-width:640px){.ar-flow-head{padding:12px 14px 14px;}.ar-flow-partners{height:22px;}.ar-flow-logo{height:72px;}body:not(.view-staff) :is(#cu,*).ar-flow-name{font-size:23px;}}
/* the ticket: black with the hall's lamps across the top and the neon edge, the logo in the logo slot; the team's
   code box goes dark with it (it was light, and its Send button was white on white) */
body:not(.view-staff) :is(#tab-myrides,#tab-register) .ticket-card.tk-th.th-arena{
  --night:#0b0b0b;--night-2:rgba(255,255,255,.08);--night-ink:#fff;--night-ink-2:rgba(255,255,255,.74);--night-line:rgba(255,255,255,.18);--neon:#ff5a61;
  --night-amber:#ffc46b;--night-red:#ff8a8f;--night-red-line:rgba(255,138,143,.4);
  background:linear-gradient(180deg,rgba(11,11,11,.45) 0,rgba(11,11,11,.88) 150px,#0b0b0b 230px),url(/assets/arena-heros-band.webp) center top/auto 230px repeat-x,var(--ar-ink);
  border:1px solid rgba(255,90,97,.6);box-shadow:var(--ar-glow);color:#fff;}
.ticket-card .tk-logo-ev .tk-logo-arena{height:56px;}
body:not(.view-staff) .ticket-card.th-arena :is(.vl-tk-meta,.vl-pay-note){color:var(--night-ink-2);}
body:not(.view-staff) .ticket-card.th-arena .vl-chip{background:var(--ar-red);}
body:not(.view-staff) .ticket-card.th-arena .vl-tk-team{background:rgba(255,255,255,.05);border-color:rgba(255,90,97,.45);color:#fff;}
body:not(.view-staff) .ticket-card.th-arena .vl-tk-code{color:var(--night-ink-2);}
body:not(.view-staff) .ticket-card.th-arena .vl-tk-code strong{color:#fff;}
.vt-tk{display:grid;gap:8px;margin-top:10px;padding:10px 12px;font-size:13px;line-height:1.45;background:#f5f0fe;border:1px solid rgba(91,63,214,.24);color:#2e1c80;}
.vt-tk-q{font-size:14px;font-weight:700;}
.vt-tk-btns{display:flex;flex-wrap:wrap;gap:8px;}
.vt-tk-btns .btn-sm{border-radius:0;}
.vt-tk-done{display:flex;align-items:center;gap:8px;background:#f1f8f4;border-color:rgba(0,113,63,.35);color:#06603b;font-weight:600;}
.vt-tk-done span{flex:1 1 auto;min-width:0;}
/* Staff: the ticket answer under the race in the roster, the receipt on demand. */
.vt-chip{display:inline-flex;align-items:center;padding:1px 7px;font-size:var(--sf-fs-xs);font-weight:600;line-height:1.5;border:1px solid var(--line);background:var(--s2,#eee);color:var(--muted);}
.vt-chip-have,.vt-chip-paid{background:#e8f5ee;border-color:rgba(0,113,63,.35);color:#06603b;}
.vt-chip-paid{cursor:pointer;font:inherit;font-size:11.5px;font-weight:700;text-decoration:underline;}
.vt-chip-buy{background:#fff4e0;border-color:rgba(138,83,0,.35);color:#8A5300;}
/* a receipt still to check (2026-10-24): staff confirm each one */
.vt-chip-sent{cursor:pointer;font:inherit;font-size:11.5px;font-weight:700;text-decoration:underline;background:#e8f0ff;border-color:rgba(37,84,186,.45);color:#1d3f8f;}
.vt-tk-sent{display:flex;align-items:center;gap:8px;font-weight:600;}
.vt-tk-sent span{flex:1 1 auto;min-width:0;}
.vt-rc-st{margin:4px 0 0;font-size:var(--sf-fs-sm);font-weight:600;color:#06603b;}
.vt-rc-act{display:flex;flex-wrap:wrap;justify-content:flex-end;gap:8px;margin-top:12px;}
.vt-rc-act[hidden],.vt-rc-ask[hidden]{display:none;}
.vt-rc-ask p{margin:12px 0 0;font-size:var(--sf-fs-md);font-weight:600;}
#checkin-modal .ci-vt{display:flex;align-items:center;gap:6px;margin:6px 0;font-size:var(--sf-fs-sm);}
#checkin-modal .ci-vt span{flex:1;min-width:0;overflow-wrap:anywhere;}
.vt-rc-box{max-width:560px;}
.vt-rc-img{display:block;max-width:100%;max-height:70vh;margin:10px auto;object-fit:contain;border:1px solid var(--line);}
.vt-rc-wait{padding:24px 0;text-align:center;color:var(--muted);}
.vt-ae-rc{display:flex;align-items:flex-end;}
.vl-ed-box .vl-divs-sm .vl-div{min-height:48px;}

/* The finisher's badge: the lap ring, purple into black (BDG_SPECIAL.vlap). */
.mr-badge.sp-vlap,.badge-pop-box.sp-vlap{--sp1:#bdbdbd;--sp2:#333333;--sp3:#000000;--spg:120,120,120;--sph:255,255,255;} /* black and white (the owner, 2026-10-27) */
/* Rode with Defe: the ribbon wheel, rose into berry (BDG_SPECIAL.defe). */
.mr-badge.sp-defe,.badge-pop-box.sp-defe{--sp1:#f6c3d6;--sp2:#d782a0;--sp3:#a22b63;--spg:215,130,160;--sph:255,236,243;}
.mr-badge.sp-volunteer,.badge-pop-box.sp-volunteer{--sp1:#8fd0ff;--sp2:#1f7ae0;--sp3:#0b3b82;--spg:31,122,224;--sph:226,241,255;} /* the Volunteer badge */

/* Staff: the race column, the split above the roster, and the Victory Lap dialogs. */
.vl-cell{display:flex;flex-direction:column;align-items:flex-start;gap:3px;min-width:0;}
.vl-cell .vl-shirt{font-size:var(--sf-fs-xs);font-weight:600;color:var(--muted);}
.vl-sub{font-size:var(--sf-fs-xs);color:var(--muted);overflow-wrap:anywhere;}
.vl-code-chip{display:inline-block;padding:0 6px;font-size:var(--sf-fs-xs);font-weight:600;letter-spacing:.5px;border:1px solid rgba(13,13,13,.3);color:var(--text,#1A1919);}
.vl-wait{color:#8A5300;font-weight:600;}
.vl-warn{color:#b42318;font-weight:600;}
.vl-staff-bar{display:flex;flex-wrap:wrap;gap:8px;margin:0 0 12px;}
#vl-staff-host .vl-st-box{width:min(1180px,96vw);max-width:none;max-height:92vh;overflow:auto;}
#vl-staff-host .vl-ae-box{width:min(560px,96vw);max-width:none;max-height:92vh;overflow:auto;}
#vl-staff-host .vl-cf-box{width:min(640px,96vw);max-width:none;max-height:92vh;overflow:auto;}
#vl-staff-host .vl-st-head{display:flex;align-items:flex-start;justify-content:space-between;gap:12px;flex-wrap:wrap;margin-bottom:12px;}
#vl-staff-host .vl-st-head-acts{display:flex;flex-wrap:wrap;align-items:center;gap:8px;}
#vl-staff-host .vl-st-sub{font-size:var(--sf-fs-sm);color:var(--muted);margin-top:2px;}
#vl-staff-host .vl-st-tabs{margin:0 0 12px;}
#vl-staff-host .vl-st-tools{display:flex;flex-wrap:wrap;gap:8px;margin-bottom:12px;}
#vl-staff-host .vl-st-tools input{flex:1 1 220px;min-width:0;}
#vl-staff-host .vl-st-tiles{display:flex;flex-wrap:wrap;gap:8px;margin-bottom:12px;}
#vl-staff-host .vl-st-tile{display:flex;flex-direction:column;gap:2px;padding:8px 12px;border:1px solid var(--border,rgba(26,25,25,.14));min-width:110px;}
#vl-staff-host .vl-st-tile b{font-size:var(--sf-fs-lg);}
#vl-staff-host .vl-st-tile span{font-size:var(--sf-fs-xs);color:var(--muted);}
#vl-staff-host .vl-st-shirts b{font-size:var(--sf-fs-sm);}
#vl-staff-host .vl-st-scroll{overflow-x:auto;max-width:100%;}
#vl-staff-host .vl-st-table{width:100%;border-collapse:collapse;font-size:var(--sf-fs-sm);}
#vl-staff-host .vl-st-table th{text-align:start;font-size:var(--sf-fs-xs);color:var(--muted);font-weight:600;padding:6px 8px;border-bottom:1px solid var(--border,rgba(26,25,25,.14));white-space:nowrap;}
#vl-staff-host .vl-st-table td{padding:7px 8px;border-bottom:1px solid var(--border,rgba(26,25,25,.08));vertical-align:top;}
#vl-staff-host .vl-st-acts{display:flex;flex-wrap:wrap;gap:6px;white-space:nowrap;}
#vl-staff-host .vl-st-none{padding:18px 8px;color:var(--muted);}
#vl-staff-host .vl-st-hint{font-size:var(--sf-fs-sm);color:var(--muted);margin:0 0 10px;}
#vl-staff-host .vl-ae-code{margin-top:8px;width:100%;font-weight:600;letter-spacing:1px;text-transform:uppercase;}
#vl-staff-host .vl-ae-both{display:flex;align-items:center;gap:8px;margin-top:10px;font-size:var(--sf-fs-sm);}
#vl-staff-host .vl-pr-list{display:flex;flex-direction:column;gap:6px;margin-bottom:12px;max-height:46vh;overflow:auto;}
#vl-staff-host .vl-pr-row{display:flex;flex-direction:column;align-items:flex-start;gap:2px;width:100%;padding:10px 12px;text-align:start;background:#fff;border:1px solid var(--border,rgba(26,25,25,.18));cursor:pointer;font:inherit;color:inherit;}
#vl-staff-host .vl-pr-row span{font-size:var(--sf-fs-xs);color:var(--muted);}
/* dark staff theme: the white row held light inherited text (bug hunt 2026-10-28) */
html[data-staff-theme="dark"] #vl-staff-host .vl-pr-row{background:var(--s2);}
#vl-staff-host .vl-pr-row.active{border:2px solid var(--vl-ink);padding:9px 11px;}
/* dark staff theme: the picked row's near-black --vl-ink edge vanished on the dark row; it lights up green instead */
html[data-staff-theme="dark"] #vl-staff-host .vl-pr-row.active{border-color:var(--green);background:var(--sf-select,var(--s2));}
#vl-staff-host .vl-cf-set{border:1px solid var(--border,rgba(26,25,25,.14));padding:10px 12px;margin:0 0 12px;display:flex;flex-wrap:wrap;gap:8px 16px;}
#vl-staff-host .vl-cf-set legend{font-size:var(--sf-fs-sm);font-weight:600;padding:0 4px;}
#vl-staff-host .vl-cf-chk{display:flex;align-items:center;gap:6px;font-size:var(--sf-fs-md);}
#vl-staff-host .vl-cf-one{margin:0 0 12px;}
#vl-staff-host textarea{width:100%;}

/* Staff: the runners split by distance under the Bookings filter bar; a tap shows that distance alone. */
:is(#tab-queue,#tab-waitlist) .run-split{display:flex;flex-wrap:wrap;gap:8px;margin:8px 0 2px;}
:is(#tab-queue,#tab-waitlist) .run-split-b{display:inline-flex;align-items:center;gap:8px;min-height:34px;padding:0 12px;border:1px solid var(--border);border-radius:var(--sf-r-pill,var(--sf-r-pill));background:var(--s1);color:var(--text);font:inherit;font-size:var(--sf-fs-sm);font-weight:600;cursor:pointer;}
:is(#tab-queue,#tab-waitlist) .run-split-b b{min-width:22px;padding:1px 7px;border-radius:var(--sf-r-pill,var(--sf-r-pill));background:rgba(var(--rf-wash),.18);color:var(--rf-pink-dk);text-align:center;}
:is(#tab-queue,#tab-waitlist) .run-split-b.on{border-color:var(--rf-pink-dk);background:rgba(var(--rf-wash),.12);}
.cf-em{border:1px solid var(--border);border-radius:var(--sf-r-ctl,var(--sf-r-ctl));padding:8px 12px 2px;margin:8px 0 0;min-width:0;}
.cf-em legend{padding:0 6px;font-size:var(--sf-fs-xs);font-weight:600;color:var(--muted);}

/* The finisher's badge: the pink ribbon on a pink medal (BDG_SPECIAL.pink), its band drawn thick. */
.bdg-m .rb{fill:none;stroke:currentColor;stroke-width:3.4;stroke-linejoin:round;}
.mr-badge.sp-pink,.badge-pop-box.sp-pink{--sp1:#ffc9da;--sp2:#f2789f;--sp3:#c2416e;--spg:242,120,159;--sph:255,236,243;}
.run-em-acts{display:flex;flex-wrap:wrap;gap:8px;margin-top:10px;}
.run-em-acts a{display:inline-flex;align-items:center;gap:6px;text-decoration:none;}
/* The row menu's Emergency contact popup: the second contact's heading, under the first one's buttons (2026-10-07). */
#confirm-modal .run-em-h2{margin:16px 0 8px;font-size:12px;font-weight:700;color:var(--muted);}

/* ── "About this event" and "Details" (the owner, 2026-10-05: picked 1B, 2B, 3B) ───────────────
   Words under each event card on the picker and under each date's time, each a button of its own
   beside its card (never inside it), set into the card's own bottom padding so the card still opens
   the event or the date wherever it is tapped. The sheet is the bike type's, without the picture,
   with the facts read off the date. */
.landing-events-grid>.lec-wrap{position:relative;display:flex;min-width:0;}
.lec-wrap>.landing-event-card{flex:1 1 auto;width:100%;min-width:0;}
body .lec-wrap.has-about>.landing-event-card{padding-bottom:58px;}
body .lec-wrap .lec-about{position:absolute;inset-inline-start:28px;bottom:18px;z-index:1;margin:0;padding:4px 0;min-height:0;border:0;
  background:transparent none;font-family:var(--font-body);font-size:13px;font-weight:700;letter-spacing:0;text-transform:none;
  text-decoration:underline;text-underline-offset:3px;color:#1A1919;cursor:pointer;}
body .lec-wrap .lec-about.ab-jcc,body .lec-wrap .lec-about.ab-snd96{color:#fff;}
body .lec-wrap .lec-about.ab-runher{color:var(--rf-pink-dk);}
body .lec-wrap .lec-about:focus-visible{outline:2px solid currentColor;outline-offset:3px;border-radius:2px;}
:is(html[lang="ar"],html[lang="ur"]) body .lec-wrap .lec-about{font-family:'IBM Plex Sans Arabic',sans-serif;}
@media (max-width:640px){
  body .lec-wrap.has-about>.landing-event-card{padding-bottom:50px;}
  body .lec-wrap .lec-about{inset-inline-start:20px;bottom:14px;}
}
.session-cards-grid>.sess-wrap,.sess-day-list>.sess-wrap{position:relative;display:flex;min-width:0;}
.sess-wrap>.sess-card{flex:1 1 auto;width:100%;min-width:0;}
body .sess-wrap.has-about>.sess-card{padding-bottom:40px;}
body .sess-about{position:absolute;inset-inline-start:35px;bottom:11px;z-index:1;margin:0;padding:3px 0;min-height:0;border:0;
  background:transparent none;font:inherit;font-size:13px;font-weight:700;text-decoration:underline;text-underline-offset:3px;
  color:var(--ev,#077A4B);cursor:pointer;}
body .sess-about.solo{position:static;display:inline-block;margin-top:10px;}
body .sess-about:focus-visible{outline:2px solid currentColor;outline-offset:3px;border-radius:2px;}
.ev-info .ev-info-kick{color:var(--ev,#077A4B);}
.ev-info .ev-info-text{margin:8px 0 0;}
.ev-info .ev-info-extra{margin:10px 0 0;font-size:14px;line-height:1.5;overflow-wrap:anywhere;}
.ev-info .ev-info-facts{display:grid;gap:7px;margin:14px 0 4px;padding-top:12px;border-top:1px solid var(--border,rgba(26,25,25,.12));}
.ev-info .ev-info-facts>div{display:grid;grid-template-columns:minmax(76px,auto) minmax(0,1fr);gap:10px;font-size:14px;line-height:1.45;}
.ev-info .ev-info-facts dt{font-weight:700;color:var(--muted);}
.ev-info .ev-info-facts dd{margin:0;overflow-wrap:anywhere;}
.ev-info .ev-info-facts a{color:inherit;font-weight:700;text-decoration:underline;text-underline-offset:2px;}

/* ══ BOOKINGS IN COLOUR (the owner, 2026-10-05) ══════════════════════════════════════════════════
   "make the session cards in the bookings page in staff website themed the same way they are themed
   in customer event picker cards, make the bookings rows be colored matching the status of it for
   instance completed green no show or cancelled red, make reserved colored make to be reserved
   colored make paid colored". Staff screens only (body.view-staff), after the staff layer it
   overrides; booth mode keeps its 7:1 inks (the end of this block). */

/* ── The ride chips (Bookings) and ride cards (its Sessions view): each event's own look, as on the
   event picker. The theme class comes from _sfTheme: th-jcc, th-comm (Saturday, Petromin, the pool,
   T100), th-runher, th-snd96, th-event. The background sits in --sf-chip-bg so hover and the
   selected ring never fall back to the plain card the staff layer paints. ── */
body.view-staff .sess-chip-top{display:flex;align-items:center;gap:8px;min-width:0;margin-bottom:4px;}
body.view-staff .sess-chip-top:empty{display:none;}
body.view-staff .sess-chip-top .sess-chip-event{margin-bottom:0;min-width:0;}
body.view-staff :is(.sess-summary-chip,.sess-lc).th-jcc{
  --sf-chip-bg:var(--jcc-chev) right 12px bottom 8px/46px 12px no-repeat,linear-gradient(112deg,var(--jcc-deep) 0%,var(--jcc-navy) 44%,var(--jcc-blue) 100%) #06346F;
  --sf-ring:#0E97D5;border-color:rgba(14,151,213,.45);color:#fff;}
