#mny-modal .mny-box{width:min(480px,100%);max-height:88vh;display:flex;flex-direction:column;padding:0;overflow:hidden;}
#mny-modal .mny-box.mny-wide{width:min(640px,100%);}
#mny-modal .mny-head{display:flex;align-items:center;justify-content:space-between;gap:12px;padding:16px 18px 10px;border-bottom:1px solid var(--border);}
#mny-modal .mny-title{margin:0;font-size:var(--sf-fs-lg);}
#mny-modal .mny-x{min-width:44px;min-height:44px;background:transparent none;border:0;color:var(--muted);font-size:var(--sf-fs-xl);cursor:pointer;border-radius:var(--r-md);}
#mny-modal .mny-x:focus-visible,#mny-modal .mny-chip:focus-visible,#mny-modal .mny-pmb:focus-visible{outline:2px solid var(--green);outline-offset:2px;}
#mny-modal .mny-body{padding:14px 18px;overflow:auto;flex:1;}
#mny-modal .mny-foot{display:flex;justify-content:flex-end;flex-wrap:wrap;gap:8px;padding:12px 18px;border-top:1px solid var(--border);}
#mny-modal .mny-foot button{min-height:44px;}
#mny-modal .mny-sub{font-size:var(--sf-fs-sm);color:var(--muted);margin-bottom:12px;line-height:1.5;}
#mny-modal .mny-lbl,#mny-host .mny-lbl{display:block;font-size:var(--sf-fs-xs);font-weight:600;color:var(--muted);margin:10px 0 6px;}
#mny-modal .mny-in{width:100%;min-height:44px;}
#mny-modal .mny-chips{display:flex;flex-wrap:wrap;gap:8px;}
#mny-modal .mny-chip{min-height:44px;padding:8px 14px;border:1px solid var(--border);border-radius:var(--r-pill);background:var(--s1);color:var(--text);font-weight:600;cursor:pointer;}
#mny-modal .mny-chip.on{border-color:var(--green);background:var(--acsoft);color:var(--green);}
#mny-modal .mny-go[disabled]{opacity:.5;cursor:not-allowed;}
#mny-modal .mny-pm{display:grid;grid-template-columns:1fr 1fr;gap:10px;}
#mny-modal .mny-pmb{min-height:64px;border:1px solid var(--border);border-radius:var(--r-lg);background:var(--s1);color:var(--text);font-size:var(--sf-fs-lg);font-weight:600;cursor:pointer;}
#mny-modal .mny-pmb:hover{border-color:var(--green);}
:is(#mny-modal,#mny-host) .mny-au{list-style:none;margin:0;padding:0;}
:is(#mny-modal,#mny-host) .mny-au-row{padding:10px 0;border-bottom:1px solid var(--border);}
:is(#mny-modal,#mny-host) .mny-au-meta{font-size:var(--sf-fs-xs);color:var(--muted);margin-bottom:4px;}
:is(#mny-modal,#mny-host) .mny-au-who{font-weight:600;color:var(--text);}
:is(#mny-modal,#mny-host) .mny-au-lines{margin:0;padding-inline-start:18px;font-size:var(--sf-fs-sm);line-height:1.6;}
:is(#mny-modal,#mny-host,#an-team-host) .mny-empty{padding:16px 0;color:var(--muted);font-size:var(--sf-fs-sm);}
:is(#mny-modal,#mny-host) .mny-more{text-align:center;padding:12px 0;}
:is(#mny-modal,#mny-host) .mny-link{background:transparent none;border:0;padding:0 2px;color:var(--green);font:inherit;text-decoration:underline;cursor:pointer;min-height:24px;text-align:start;}
#mny-modal .mny-dl{display:grid;grid-template-columns:auto 1fr;gap:6px 14px;margin:0 0 10px;font-size:var(--sf-fs-sm);}
#mny-modal .mny-dl dt{color:var(--muted);}
#mny-modal .mny-dl dd{margin:0;text-align:end;font-weight:600;}
#mny-modal .mny-counts{margin:0 0 8px;padding-inline-start:18px;font-size:var(--sf-fs-xs);line-height:1.7;}
:is(#mny-modal,#mny-host) .mny-grid2{display:grid;grid-template-columns:1fr 1fr;gap:10px 16px;}
:is(#mny-modal,#mny-host,#an-team-host) .mny-over{color:var(--orange);font-weight:600;}
:is(#mny-modal,#mny-host,#an-team-host) .mny-short{color:var(--red);font-weight:600;}
:is(#mny-modal,#mny-host,#an-team-host) .mny-exact{color:var(--green);font-weight:600;}
:is(#mny-modal,#mny-host,#an-team-host) .mny-mut{color:var(--muted);font-size:var(--sf-fs-xs);}
:is(#mny-modal,#mny-host,#an-team-host) .mny-note{color:var(--muted);font-size:var(--sf-fs-xs);}
:is(#mny-host,#an-team-host) .mny-wrap{display:flex;flex-direction:column;gap:12px;}
:is(#mny-host,#an-team-host) .mny-h{display:flex;flex-direction:column;gap:2px;}
:is(#mny-host,#an-team-host) .mny-h3{margin:0;font-size:var(--sf-fs-xl);}
:is(#mny-host,#an-team-host) .mny-h4{margin:8px 0 4px;font-size:var(--sf-fs-md);}
:is(#mny-host,#an-team-host) .mny-filters{display:flex;flex-wrap:wrap;align-items:flex-end;gap:10px;}
:is(#mny-host,#an-team-host,#mny-modal) .mny-fld{display:flex;flex-direction:column;gap:4px;font-size:var(--sf-fs-xs);font-weight:600;color:var(--muted);}
:is(#mny-host,#an-team-host) .mny-fld .filter-select{min-height:44px;}
#mny-host .mny-fld-q{flex:1 1 220px;min-width:0;}
#mny-host .aus-local{display:block;margin:6px 0;}
:is(#mny-host,#an-team-host) .mny-filters button{min-height:44px;}
#mny-host .mny-tiles{display:grid;grid-template-columns:repeat(auto-fill,minmax(130px,1fr));gap:8px;}
#mny-host .mny-tile{border:1px solid var(--border);border-radius:var(--r-lg);padding:10px 12px;background:var(--s1);}
#mny-host .mny-tile-v{font-size:var(--sf-fs-xl);font-weight:600;}
#mny-host .mny-tile-l{font-size:var(--sf-fs-xs);color:var(--muted);font-weight:600;}
#mny-host .mny-tile-s{font-size:var(--sf-fs-sm);font-weight:600;margin-top:2px;}
:is(#mny-host,#an-team-host) .mny-tw{overflow-x:auto;}
:is(#mny-host,#an-team-host) .mny-t{width:100%;border-collapse:collapse;font-size:var(--sf-fs-sm);}
:is(#mny-host,#an-team-host) .mny-t th{text-align:start;font-size:var(--sf-fs-xs);color:var(--muted);padding:6px 8px;border-bottom:1px solid var(--border);white-space:nowrap;}
:is(#mny-host,#an-team-host) .mny-t td{padding:7px 8px;border-bottom:1px solid var(--border);vertical-align:top;}
:is(#tab-history,#cact-host) .lg-open{background:transparent none;border:0;padding:0;color:var(--text);text-align:start;font:inherit;font-size:var(--sf-fs-sm);cursor:pointer;text-decoration:underline;text-decoration-color:var(--border);min-height:24px;}
:is(#tab-history,#cact-host) .lg-open:hover{color:var(--green);}
:is(#tab-history,#cact-host) .lg-amt{font-size:var(--sf-fs-xs);font-weight:600;white-space:nowrap;}
:is(#tab-history,#cact-host) .lg-acct{color:var(--muted);font-weight:600;}
/* A line names the device and the account now (2026-10-09): on a phone the who-part shortens and the action takes
   its own line, so the action text is never squeezed to nothing. */
:is(#tab-history,#cact-host) .lg-who{min-width:0;flex-shrink:1;overflow:hidden;text-overflow:ellipsis;}
@media (max-width:640px){
  :is(#tab-history,#cact-host) .lg-row{flex-wrap:wrap;row-gap:4px;}
  :is(#tab-history,#cact-host) .lg-row .lg-label{flex:1 1 100%;white-space:normal;}
}
:is(#tab-history,#cact-host) .lg-more{text-align:center;padding:12px 0;}
@media (max-width:560px){:is(#mny-modal,#mny-host) .mny-grid2{grid-template-columns:1fr;}}

/* ══ Accessibility and consistency pass (2026-10-09) ═══════════════════════════════════════════
   Page and card titles are real headings now (<h1 class="page-title">, <h2 class="form-title">):
   the browser's heading margins are taken off so they keep the look they had as divs. */
:is(h1,h2).page-title,h2.form-title{margin-top:0;margin-inline:0;}
/* Skip to content: the first Tab stop on a staff page, shown only while it has the focus */
.skip-link{position:fixed;top:8px;inset-inline-start:8px;z-index:10000;transform:translateY(-300%);
  background:var(--sf-card,#fff);color:var(--text);border:2px solid var(--sf-green-ink,#0c7a3d);border-radius:8px;
  padding:10px 16px;font:inherit;font-weight:700;min-height:44px;cursor:pointer;}
.skip-link:focus{transform:none;}
body:not(.view-staff) .skip-link{display:none;}
#staff-main:focus,#staff-main :is(h1,h2)[tabindex="-1"]:focus:not(:focus-visible){outline:medium none;}
/* sortable headers outside Bookings: the header's words are a button (aria-sort on the th) */
body.view-staff th .q-sort-btn{display:inline;margin:0;padding:0;border:0;border-radius:var(--sf-r-xs);background:transparent none;color:inherit;
  font:inherit;letter-spacing:inherit;text-transform:inherit;text-align:inherit;white-space:nowrap;cursor:pointer;min-height:0;}
body.view-staff th .q-sort-btn:focus-visible{outline:2px solid var(--sf-green-ink);outline-offset:2px;}
/* 24px tall hit area (WCAG 2.5.8, staff round s10): an inline box's padding takes no room in the line, so the header keeps its height */
body.view-staff th .q-sort-btn,:is(#tab-queue,#tab-waitlist) .queue-table thead th .q-sort-btn{padding-block:5px;}
/* Settings > This device: theme and keyboard shortcuts */
body.view-staff .set-look{display:grid;gap:12px;margin-top:14px;}
body.view-staff .set-look .form-group{margin:0;}
body.view-staff .set-look select{max-width:320px;}
/* the forecast chip's wind, drawn */
body.view-staff :is(.rq-wx,.rq-wx-warn) .cu-ic{vertical-align:-2px;}
/* the connection banner (was written as an inline cssText) */
#conn-banner{position:fixed;top:0;left:0;right:0;z-index:99999;text-align:center;font-family:var(--font-body);font-size:12px;font-weight:700;
  letter-spacing:.3px;padding:6px 10px;color:#fff;}
#conn-banner.cb-refused{background:var(--red-fill,#a33b2e);}
#conn-banner.cb-pending{background:#8a5c14;}
#conn-banner.cb-offline{background:#b91c1c;box-shadow:0 2px 8px rgba(0,0,0,.4);}
/* One close button (2026-10-09): every dialog's × wears .x-close beside its old class (chrome-x, ca-x, dk-x,
   sl-close, tm-x, bdg-x, flt-px, bkm-mx, ah-close...) and this one look wins over theirs (:is(#_,*) lifts
   it over their #dialog-scoped rules): the muted ×, a 44px target that keeps the header's height. */
body.view-staff .x-close:is(#_x,*){background:transparent none;border:0;border-radius:var(--sf-r-ctl);color:var(--muted);cursor:pointer;
  font-size:var(--sf-fs-xl);line-height:1;padding:0;min-width:44px;min-height:44px;margin:-10px;display:inline-flex;align-items:center;justify-content:center;flex-shrink:0;transition:color .15s;}
body.view-staff .x-close:is(#_x,*):hover{color:var(--text);background:var(--sf-hover);}
body.view-staff .x-close:is(#_x,*):focus-visible{outline:2px solid var(--sf-green-ink);outline-offset:-2px;}
.es-act{margin-top:10px;}
/* Long tables as cards on a phone (2026-10-09): History, Inventory, Analytics' tables, the website editor, the
   catalogue and the venues' users, like the Bookings roster. Each cell's column name comes from data-label
   (_tcLabels). :is(#_x,*) lifts the rules over each table's own #tab-scoped ones. */
@media(max-width:767px){
  body.view-staff table.t-cards:is(#_x,*),body.view-staff table.t-cards:is(#_x,*) :is(tbody,tfoot,tr,td){display:block;width:100%;max-width:100%;min-width:0;box-sizing:border-box;}
  /* the headers stay as a row of chips above the cards, so a phone can still sort by any column */
  body.view-staff table.t-cards:is(#_x,*) thead{display:block;margin-bottom:8px;}
  body.view-staff table.t-cards:is(#_x,*) thead tr{display:flex;flex-wrap:wrap;gap:6px;background:none;border:0;padding:0;margin:0;}
  body.view-staff table.t-cards:is(#_x,*) thead th{display:inline-flex;align-items:center;width:auto;min-height:32px;padding:4px 10px;border:1px solid var(--sf-line2);border-radius:var(--sf-r-pill);background:var(--sf-card);position:static;}
  body.view-staff table.t-cards:is(#_x,*) thead th:empty,body.view-staff table.t-cards:is(#_x,*) thead th:has(> .sr-only:only-child){display:none;}
  body.view-staff table.t-cards:is(#_x,*) :is(tbody,tfoot) tr{background:var(--sf-card);border:1px solid var(--sf-line2);border-radius:var(--sf-r-card);margin-bottom:10px;padding:8px 12px;}
  body.view-staff table.t-cards:is(#_x,*) td{border:none;padding:5px 0;text-align:start;overflow-wrap:anywhere;background:none;white-space:normal;}
  body.view-staff table.t-cards:is(#_x,*) td[data-label]:not([data-label=""]){display:flex;align-items:center;justify-content:space-between;gap:12px;}
  body.view-staff table.t-cards:is(#_x,*) td[data-label]:not([data-label=""])::before{content:attr(data-label);flex:0 1 auto;max-width:45%;
    font-size:var(--staff-fs-sm);font-weight:600;letter-spacing:0;text-transform:none;color:var(--muted);}
  :is(html[lang="ar"],html[lang="ur"]) body.view-staff table.t-cards:is(#_x,*) td[data-label]::before{letter-spacing:0;text-transform:none;}
  body.view-staff :is(.table-wrapper,.an-scroll-x,.an-scroll-x-touch,.vendor-tbl):has(> table.t-cards){overflow-x:visible;border:none;background:none;border-radius:0;}
}
/* ── The staff dark theme, brought back as a choice (Settings > This device > Theme, 2026-10-09) and
   checked against today's screens: the roster's state colours (2026-10-07) were drawn for paper only, so
   on dark each state takes a deep wash of its own hue with the same bright edge, and so do the money
   pills, the status pills and the figures above the roster (2026-10-11, the owner: "make sure the dark
   theme is perfected": the light pills were the brightest thing on a dark page). ── */
html[data-staff-theme="dark"] body.view-staff :is(tr,.q-card).row-waiting{--rs-bg:#15181c;--rs-edge:#5b646b;--rs-line:#2a3038;}
html[data-staff-theme="dark"] body.view-staff :is(tr,.q-card).row-waitlist{--rs-bg:#241a11;--rs-edge:#f97316;--rs-line:#7c3a12;}
html[data-staff-theme="dark"] body.view-staff :is(tr,.q-card).row-toreserve{--rs-bg:#231729;--rs-edge:#e879f9;--rs-line:#6b2172;}
html[data-staff-theme="dark"] body.view-staff :is(tr,.q-card).row-reserved{--rs-bg:var(--sf-plum-row);--rs-edge:var(--sf-plum);--rs-line:var(--sf-plum-line);}
html[data-staff-theme="dark"] body.view-staff :is(tr,.q-card).row-active{--rs-bg:#242013;--rs-edge:#f2b43f;--rs-line:#6b5414;}
html[data-staff-theme="dark"] body.view-staff :is(tr,.q-card):is(.row-done,.row-done-paid){--rs-bg:#13251b;--rs-edge:#25d184;--rs-line:#1d5a3a;}
html[data-staff-theme="dark"] body.view-staff :is(tr,.q-card).row-noshow-cancel{--rs-bg:#281818;--rs-edge:#ff6f66;--rs-line:#6b2424;}
html[data-staff-theme="dark"] body.view-staff :is(.queue-table tbody tr,.queue-mobile-view .q-card):is(.row-waiting,.row-waitlist,.row-toreserve,.row-reserved,.row-active,.row-done,.row-done-paid,.row-noshow-cancel){--muted-l:#a8b0b6;}
html[data-staff-theme="dark"] body.view-staff .queue-table tbody tr:is(.row-waiting,.row-waitlist,.row-toreserve,.row-reserved,.row-active,.row-done,.row-done-paid,.row-noshow-cancel) td{border-bottom-color:rgba(255,255,255,.07);}
/* the money: a deep wash of its colour, its words bright (paid green, pending amber, on the house teal) */
html[data-staff-theme="dark"] body.view-staff .pay-toggle.paid{background:#12371f;border-color:#1f7a45;color:#86efac;}
html[data-staff-theme="dark"] body.view-staff .pay-toggle.paid:hover{background:#174828;}
html[data-staff-theme="dark"] body.view-staff .pay-toggle.pending{background:#3a2f0c;border-color:#8a6a12;color:#fcd34d;}
html[data-staff-theme="dark"] body.view-staff .pay-toggle.pending:hover{background:#4a3c10;border-color:#a8821a;}
html[data-staff-theme="dark"] body.view-staff .pay-toggle.house{background:#0f3533;border-color:#1d7c74;color:#5eead4;}
html[data-staff-theme="dark"] body.view-staff .pay-toggle.house:hover{background:#13443f;}
/* the status pills: the same washes as their rows, a shade brighter so they stand off them */
html[data-staff-theme="dark"] body.view-staff .status-badge.st-waiting{background:#1b2027;color:#d6dbde;box-shadow:inset 0 0 0 1px #4a535b;}
html[data-staff-theme="dark"] body.view-staff .status-badge.st-waitlist{background:#3a2210;color:#fdba74;}
html[data-staff-theme="dark"] body.view-staff .status-badge.st-toreserve{background:#3a1640;color:#f0abfc;}
html[data-staff-theme="dark"] body.view-staff .status-badge.st-reserved{background:var(--sf-plum-wash);color:var(--sf-plum-ink);}
html[data-staff-theme="dark"] body.view-staff .status-badge:is(.st-active,.st-needsbike){background:#3a2f0c;color:#fcd34d;}
html[data-staff-theme="dark"] body.view-staff .status-badge.st-done{background:#12371f;color:#86efac;}
html[data-staff-theme="dark"] body.view-staff .status-badge:is(.st-noshow,.st-cancelled,.st-removed){background:#3d1717;color:#fca5a5;}
/* the figures above the roster: the key in the dark rows' colours */
html[data-staff-theme="dark"] body.view-staff :is(#tab-queue,#tab-waitlist) .stat-chip:is(.sc-waiting,.sc-nothere){--sc-edge:#1b2027;--sc-ink:#e8ebed;}
html[data-staff-theme="dark"] body.view-staff :is(#tab-queue,#tab-waitlist) .stat-chip:is(.sc-waiting,.sc-nothere)::before{box-shadow:inset 0 0 0 1px #7f8890;}
html[data-staff-theme="dark"] body.view-staff :is(#tab-queue,#tab-waitlist) .stat-chip.sc-waitlist{--sc-edge:#f97316;--sc-ink:#fdba74;}
html[data-staff-theme="dark"] body.view-staff :is(#tab-queue,#tab-waitlist) .stat-chip.sc-active{--sc-edge:#f2b43f;--sc-ink:#fcd34d;}
html[data-staff-theme="dark"] body.view-staff :is(#tab-queue,#tab-waitlist) .stat-chip.sc-done{--sc-edge:#25d184;--sc-ink:#86efac;}
/* the scan button: the deep green every other green button wears here (white on #25d184 was 2:1) */
html[data-staff-theme="dark"] body.view-staff .scan-fab{background:#0c7a3d;}
/* The ride chips (Bookings) and ride cards (Sessions) drawn on paper - the community rides, Run for Her,
   the one-off events - turn dark like the rest of the page and keep their own accent: the pattern under
   a dark veil, Run for Her's pink glow, the events' violet corner. The circuit and National Day cards are
   dark already. */
html[data-staff-theme="dark"] body.view-staff :is(.sess-summary-chip,.sess-lc).th-comm{
  --sf-chip-bg:linear-gradient(to bottom right,#101318 0 38%,rgba(16,19,24,.9) 64%,rgba(16,19,24,.74) 100%),var(--mm-pattern) right -10px top -8px/80px auto repeat #101318;
  --sf-ring:#25d184;border-color:rgba(37,209,132,.4);color:var(--text);}
html[dir="rtl"][data-staff-theme="dark"] body.view-staff :is(.sess-summary-chip,.sess-lc).th-comm{
  --sf-chip-bg:linear-gradient(to bottom left,#101318 0 38%,rgba(16,19,24,.9) 64%,rgba(16,19,24,.74) 100%),var(--mm-pattern) left -10px top -8px/80px auto repeat #101318;}
html[data-staff-theme="dark"] body.view-staff :is(.sess-summary-chip,.sess-lc).th-runher{
  --sf-chip-bg:radial-gradient(120% 160% at 100% 100%,rgba(var(--rf-wash),.24) 0%,rgba(var(--rf-wash),.08) 40%,rgba(16,19,24,0) 70%) #101318;
  --sf-ring:#f2789f;border-color:rgba(242,120,159,.4);color:var(--text);}
html[dir="rtl"][data-staff-theme="dark"] body.view-staff :is(.sess-summary-chip,.sess-lc).th-runher{
  --sf-chip-bg:radial-gradient(120% 160% at 0% 100%,rgba(var(--rf-wash),.24) 0%,rgba(var(--rf-wash),.08) 40%,rgba(16,19,24,0) 70%) #101318;}
html[data-staff-theme="dark"] body.view-staff :is(.sess-summary-chip,.sess-lc).th-event{
  --sf-chip-bg:linear-gradient(to bottom right,#101318 0 55%,rgba(var(--sf-plum-rgb),.2) 100%) #101318;
  --sf-ring:var(--sf-plum);border-color:rgba(var(--sf-plum-rgb),.4);color:var(--text);}
html[data-staff-theme="dark"] body.view-staff :is(.sess-summary-chip,.sess-lc):is(.th-jcc,.th-comm,.th-runher,.th-snd96,.th-event,.th-defe5k,.th-yoga).selected,
html[data-staff-theme="dark"] body.view-staff .sess-summary-chip:is(.th-jcc,.th-comm,.th-runher,.th-snd96,.th-event,.th-defe5k,.th-yoga).active-sess{box-shadow:0 0 0 2px var(--sf-ring),0 6px 16px rgba(0,0,0,.5);}
html[data-staff-theme="dark"] body.view-staff .sess-summary-chip.th-runher .sess-chip-event,
html[data-staff-theme="dark"] body.view-staff #tab-sessions .sess-lc.th-runher .ev-chip{color:#f49ac1;border-color:rgba(244,154,193,.5);}
html[data-staff-theme="dark"] body.view-staff .sess-summary-chip.th-event .sess-chip-event,
html[data-staff-theme="dark"] body.view-staff #tab-sessions .sess-lc.th-event .ev-chip{color:var(--sf-plum-ink);border-color:rgba(var(--sf-plum-rgb),.5);}
html[data-staff-theme="dark"] body.view-staff :is(.sess-summary-chip,.sess-lc):is(.th-comm,.th-runher,.th-event) :is(.sess-chip-bar,.sess-lc-bar){background:rgba(255,255,255,.14);}
/* Run for Her's partner marks are navy on the poster: white on the dark chip, as the circuit's mark is */
/* each ride's own colour, as words on dark: the paper inks (circuit blue #2f63ad, the pool's teal, the
   workshop's orange, the events' violet, Run for Her's pink, National Day green) were 2-3.5:1 here */
html[data-staff-theme="dark"] body.view-staff .ev-jcc{--ev:#6ea8ff;--ev-rgb:110,168,255;}
html[data-staff-theme="dark"] body.view-staff .ev-swim{--ev:#2cc5d8;--ev-rgb:44,197,216;}
html[data-staff-theme="dark"] body.view-staff .ev-workshop{--ev:#fb8c4a;--ev-rgb:251,140,74;}
html[data-staff-theme="dark"] body.view-staff .ev-event{--ev:var(--sf-plum);--ev-rgb:var(--sf-plum-rgb);}
html[data-staff-theme="dark"] body.view-staff .ev-runher{--ev:#f2789f;--ev-rgb:242,120,159;}
html[data-staff-theme="dark"] body.view-staff .ev-snd96{--ev:#3ddc84;--ev-rgb:61,220,132;}
/* Victory Lap's race black (#0d0d0d) vanished on dark: its name on the session card, its calendar bar */
html[data-staff-theme="dark"] body.view-staff .ev-vlap{--ev:#ededea;--ev-rgb:237,237,234;}
html[data-staff-theme="dark"] body.view-staff .ev-name.ev-vlap{color:var(--ev);}
html[data-staff-theme="dark"] body.view-staff :is(.dash-dot,.cal-sess).ev-community{--ev:#b48cf0;}
html[data-staff-theme="dark"] body.view-staff :is(.dash-dot,.cal-sess).ev-workshop{--ev:#6ea8ff;}
html[data-staff-theme="dark"] body.view-staff :is(.dash-dot,.cal-sess).ev-snd96{--ev:#3ddc84;}
html[data-staff-theme="dark"] body.view-staff :is(.dash-dot,.cal-sess).ev-jcc{--ev:#e0a84a;}
html[data-staff-theme="dark"] body.view-staff :is(.dash-dot,.cal-sess).ev-event{--ev:var(--sf-plum);}
/* a tag's chip writes its name in the tag's own colour; on dark that colour is lifted toward white so
   a deep violet or navy tag still reads (its tint and edge stay the tag's own) */
html[data-staff-theme="dark"] body.view-staff :is(#tab-community,#tab-customers,#tab-analytics,#new-acct-modal,#confirm-modal,#cust-modal) .cmy-tcf{color:color-mix(in srgb,var(--cmy-tfg,currentColor) 55%,#fff);}
/* Front desk round 2 (2026-10-09): suggested bikes (check-in, Hand-over), desk notes, the desk sheet
   (My shift, Join a party), the check-in title's tag and the NFC tab's "Sent to your open tab" page. */
.bk-sugg{display:flex;flex-wrap:wrap;align-items:center;gap:6px;margin-top:8px;}
.bk-sugg-l{font-size:var(--sf-fs-xs);font-weight:600;color:var(--muted);margin-inline-end:2px;}
.bk-sugg-b{min-height:44px;padding:6px 12px;border:1px solid var(--border);border-radius:var(--sf-r-pill,var(--sf-r-pill));background:var(--s1);color:var(--text);font:inherit;font-size:var(--sf-fs-sm);cursor:pointer;}
.bk-sugg-b:hover{border-color:var(--green);}
.bk-sugg-b:focus-visible{outline:2px solid var(--green);outline-offset:2px;}
:is(#tab-queue,#tab-waitlist) .rq-dnote{font-size:var(--staff-fs-sm,12px);color:var(--orange);font-weight:600;margin-top:3px;max-width:22ch;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;}
#checkin-modal .ci-dnote{display:flex;align-items:center;gap:6px;margin:6px 0;padding:6px 10px;border-radius:var(--r-md,var(--sf-r-ctl));background:rgba(var(--warn-rgb),.12);color:var(--text);font-size:var(--sf-fs-sm);font-weight:600;}
#checkin-modal .ci-dnote span{flex:1;min-width:0;overflow-wrap:anywhere;}
#checkin-modal .ci-ttag{display:inline-block;margin-inline-start:6px;padding:1px 8px;border-radius:var(--sf-r-pill,var(--sf-r-pill));background:rgba(var(--warn-rgb),.16);color:var(--orange);font-size:var(--sf-fs-xs);font-weight:600;vertical-align:middle;}
/* The staff review, 2026-10-28 (batch 2, desk): a booking with no waiver on the roster and in the check-in drawer, a party member
   still to be approved in the drawer's steps, and the waiver the rider agrees to on the desk device (#confirm-modal, centred). */
:is(#tab-queue,#tab-waitlist) .rq-nowv{font-size:var(--staff-fs-sm,12px);color:var(--orange);font-weight:600;margin-top:3px;white-space:nowrap;}
#checkin-modal .ci-nowv{display:flex;align-items:center;flex-wrap:wrap;gap:6px;margin:6px 0;padding:6px 10px;border-radius:var(--r-md,var(--sf-r-ctl));background:rgba(var(--warn-rgb),.12);color:var(--text);font-size:var(--sf-fs-sm);font-weight:600;}
#checkin-modal .ci-nowv span{flex:1;min-width:0;}
#checkin-modal .bkm-stepna{opacity:.6;border-style:dashed;}
#confirm-modal .dky-wv{width:min(94vw,560px);max-height:calc(100dvh - 32px);overflow-y:auto;}
#confirm-modal .dky-wv-top{display:flex;align-items:center;justify-content:space-between;gap:8px;flex-wrap:wrap;margin-bottom:10px;font-size:var(--sf-fs-sm);font-weight:600;color:var(--muted-l);}
#confirm-modal .dky-wv-top select{min-height:var(--sf-ctl-size);}
#confirm-modal .dky-wv-txt{max-height:min(46vh,420px);overflow-y:auto;white-space:pre-line;padding:12px 14px;border:1px solid rgba(var(--tint-rgb),.12);border-radius:var(--sf-r-ctl);background:var(--s3);color:var(--text);font-size:var(--sf-fs-md);font-weight:500;line-height:1.55;}
#confirm-modal .dky-wv-ok{display:flex;align-items:flex-start;gap:10px;margin:14px 0 8px;font-size:var(--sf-fs-md);font-weight:600;color:var(--text);cursor:pointer;}
#confirm-modal .dky-wv-ok input{-webkit-appearance:checkbox;appearance:checkbox;width:24px;height:24px;min-height:0;flex:0 0 24px;margin:0;accent-color:var(--green);}
#confirm-modal .dky-wv-err{margin:4px 0 10px;color:var(--red);font-size:var(--sf-fs-sm);font-weight:600;}
#desk-sheet .dk-sheet{width:min(92vw,480px);max-height:calc(100vh - 40px);max-height:calc(100dvh - 40px);display:flex;flex-direction:column;}
#desk-sheet .chrome-dh10{display:flex;align-items:center;justify-content:space-between;margin-bottom:10px;}
#desk-sheet .chrome-dt{font-size:var(--sf-fs-lg);font-weight:600;margin:0;}
#desk-sheet .chrome-xt{background:transparent none;border:none;color:var(--muted);cursor:pointer;font-size:var(--sf-fs-xl);line-height:1;padding:0 4px;min-width:44px;min-height:44px;}
#desk-sheet .chrome-dact{display:flex;gap:8px;justify-content:flex-end;flex-wrap:wrap;}
#desk-sheet .chrome-dact button{min-height:44px;}
#desk-sheet .dk-sheet-body{overflow-y:auto;margin-bottom:16px;display:flex;flex-direction:column;gap:12px;}
#desk-sheet .dk-sheet-muted{font-size:var(--sf-fs-sm);color:var(--muted);font-weight:600;}
#desk-sheet .eon-sec{padding:10px 14px;background:var(--s3);border-radius:var(--r-md,var(--sf-r-ctl));}
#desk-sheet .eon-h{font-size:var(--sf-fs-xs);font-weight:600;color:var(--muted);text-transform:none;letter-spacing:0;margin-bottom:6px;}
#desk-sheet .eon-list{list-style:none;margin:0;padding:0;display:flex;flex-direction:column;gap:4px;font-size:var(--sf-fs-sm);font-weight:600;}
#desk-sheet .eon-list li{display:flex;justify-content:space-between;gap:10px;}
#desk-sheet .dk-shift-acts li{justify-content:flex-start;font-weight:600;}
#desk-sheet .dk-pj-list{display:flex;flex-direction:column;gap:6px;}
#desk-sheet .dk-pj{min-height:44px;text-align:start;padding:8px 12px;border:1px solid var(--border);border-radius:var(--r-md,var(--sf-r-ctl));background:var(--s1);color:var(--text);font:inherit;font-weight:600;cursor:pointer;}
#desk-sheet .dk-pj:focus-visible{outline:2px solid var(--green);outline-offset:2px;}
.nfc-sent{position:fixed;inset:0;z-index:9999;display:flex;align-items:center;justify-content:center;padding:16px;background:var(--bg);color:var(--text);}
.nfc-sent-box{max-width:420px;width:100%;text-align:center;padding:24px 16px;border:1px solid var(--border);border-radius:var(--r-md,6px);background:var(--s1);}
.nfc-sent-t{font-size:22px;font-weight:900;margin:0 0 10px;}
.nfc-sent-box p{margin:0 0 16px;color:var(--muted);font-weight:600;}
.nfc-sent-box button{min-height:44px;}
/* ── KIOSK MODE (2026-10-09): a desk tablet's self-service screen for walk-ins (#kiosk, drawn by
   _koRender in the kiosk part). Full screen over the staff panel, below the operator's PIN keypad
   (z 290) and the toasts; large type and 56px+ targets for a standing walk-in; staff tokens only. ── */
#kiosk{position:fixed;inset:0;z-index:280;background:var(--sf-card);color:var(--text);overflow-y:auto;-webkit-overflow-scrolling:touch;}
body.kiosk-on{overflow:hidden;}
#kiosk .ko-wrap{min-height:100%;display:flex;flex-direction:column;max-width:760px;margin:0 auto;padding:16px 16px 24px;box-sizing:border-box;}
#kiosk .ko-top{display:flex;align-items:center;justify-content:space-between;gap:12px;padding:6px 0 18px;}
#kiosk .ko-brand{font-weight:600;font-size:var(--sf-fs-xl);letter-spacing:0;}
#kiosk .ko-lang{display:inline-flex;align-items:center;gap:8px;color:var(--muted);}
#kiosk .ko-lang select{min-height:48px;font-size:var(--sf-fs-lg);padding:6px 12px;border:1px solid var(--sf-ctl);border-radius:var(--sf-r-card,var(--sf-r-card));background:var(--sf-card);color:var(--text);}
#kiosk .ko-main{flex:1;outline:medium none;}
#kiosk .ko-h1{font-size:clamp(26px,5vw,38px);line-height:1.15;font-weight:600;margin:8px 0 10px;}
#kiosk .ko-h2{font-size:var(--sf-fs-xl);font-weight:600;margin:22px 0 10px;}
#kiosk .ko-sub{font-size:var(--sf-fs-lg);color:var(--muted);margin:0 0 18px;line-height:1.45;}
#kiosk .ko-choices{display:grid;grid-template-columns:repeat(auto-fit,minmax(240px,1fr));gap:16px;margin-top:22px;}
#kiosk .ko-btn{display:inline-flex;align-items:center;justify-content:center;gap:10px;min-height:60px;padding:12px 22px;border-radius:var(--sf-r-pop,var(--sf-r-pop));font-size:var(--sf-fs-lg);font-weight:600;border:1px solid var(--sf-ctl);background:var(--sf-card);color:var(--text);cursor:pointer;}
#kiosk .ko-btn:disabled{opacity:.5;cursor:default;}
#kiosk .ko-btn:focus-visible,#kiosk .ko-ride:focus-visible,#kiosk .ko-hit:focus-visible,#kiosk .ko-type:focus-visible,#kiosk .ko-back:focus-visible,#kiosk .ko-exit:focus-visible{outline:3px solid var(--green);outline-offset:2px;}
#kiosk .ko-big{min-height:150px;flex-direction:column;font-size:var(--sf-fs-xl);border-width:2px;}
#kiosk .ko-alt{border-color:var(--green);color:var(--sf-green-ink);}
#kiosk .ko-primary{width:100%;margin-top:18px;background:var(--green);border-color:var(--green);color:var(--sf-card);}
#kiosk .ko-ghost{width:100%;margin-top:10px;}
#kiosk .ko-back{display:inline-flex;align-items:center;gap:6px;min-height:48px;padding:0 12px;margin-inline-start:-12px;border:none;background:transparent none;color:var(--muted);font-size:var(--sf-fs-lg);cursor:pointer;}
#kiosk .ko-field{display:flex;flex-direction:column;gap:6px;margin-bottom:14px;flex:1;min-width:0;}
#kiosk .ko-field label,#kiosk .ko-set legend{font-size:var(--sf-fs-lg);font-weight:600;}
#kiosk .ko-field :is(input,select),#kiosk .ko-phone :is(input,select){min-height:56px;font-size:var(--sf-fs-xl);padding:8px 14px;border:1px solid var(--sf-ctl);border-radius:var(--sf-r-card,var(--sf-r-card));background:var(--sf-card);color:var(--text);box-sizing:border-box;width:100%;}
#kiosk .ko-bad :is(input,select){border-color:var(--red);}
#kiosk .ko-row{display:flex;gap:12px;flex-wrap:wrap;}
#kiosk .ko-phone{display:flex;gap:8px;}
#kiosk .ko-phone select{flex:0 0 112px;width:112px;}
#kiosk .ko-pin{letter-spacing:0;text-align:center;font-size:var(--sf-fs-2xl);max-width:240px;}
#kiosk .ko-set{border:1px solid var(--sf-line2);border-radius:var(--sf-r-pop,var(--sf-r-pop));padding:12px 14px 4px;margin:0 0 14px;}
#kiosk .ko-set.ko-bad{border-color:var(--red);}
#kiosk .ko-err{margin:6px 0 4px;padding:12px 14px;border-radius:var(--sf-r-card,var(--sf-r-card));background:rgba(var(--red-rgb),.1);color:var(--red);font-size:var(--sf-fs-lg);font-weight:600;}
#kiosk .ko-empty{margin:14px 0;padding:18px;border-radius:var(--sf-r-pop,var(--sf-r-pop));background:var(--sf-head);font-size:var(--sf-fs-lg);}
#kiosk .ko-note{color:var(--muted);font-size:var(--sf-fs-lg);margin:14px 0 0;}
#kiosk .ko-list{list-style:none;margin:0;padding:0;display:grid;gap:10px;}
#kiosk .ko-hit,#kiosk .ko-ride{width:100%;display:flex;align-items:center;justify-content:space-between;gap:12px;min-height:64px;padding:12px 18px;border:1px solid var(--sf-ctl);border-radius:var(--sf-r-pop,var(--sf-r-pop));background:var(--sf-card);color:var(--text);font-size:var(--sf-fs-xl);font-weight:600;text-align:start;cursor:pointer;}
#kiosk .ko-ride{flex-direction:column;align-items:flex-start;gap:6px;min-height:84px;}
#kiosk .ko-ride-ln{display:inline-flex;align-items:center;gap:8px;font-size:var(--sf-fs-lg);font-weight:600;color:var(--muted);}
#kiosk .ko-ride-tag{font-size:var(--sf-fs-md);font-weight:600;color:var(--sf-green-ink);}
#kiosk .ko-ride.ko-full{opacity:.55;cursor:default;}
#kiosk .ko-types{display:flex;flex-wrap:wrap;gap:10px;padding:4px 0 10px;}
#kiosk .ko-type{min-height:56px;min-width:120px;padding:8px 18px;border-radius:var(--sf-r-card,var(--sf-r-card));border:2px solid var(--sf-ctl);background:var(--sf-card);color:var(--text);font-size:var(--sf-fs-lg);font-weight:600;cursor:pointer;}
#kiosk .ko-type.on{border-color:var(--green);background:rgba(var(--green-rgb),.12);color:var(--sf-green-ink);}
#kiosk .ko-fit{font-size:var(--sf-fs-lg);font-weight:600;color:var(--sf-green-ink);margin:4px 0 6px;}
#kiosk .ko-sess{font-size:var(--sf-fs-lg);margin:0 0 12px;color:var(--muted);}
#kiosk .ko-waiver{max-height:40vh;overflow-y:auto;white-space:pre-line;padding:14px 16px;border:1px solid var(--sf-line2);border-radius:var(--sf-r-pop,var(--sf-r-pop));background:var(--sf-head);font-size:var(--sf-fs-lg);line-height:1.55;}
#kiosk .ko-agree{display:flex;align-items:flex-start;gap:12px;margin:16px 0 4px;font-size:var(--sf-fs-lg);font-weight:600;cursor:pointer;}
#kiosk .ko-agree input{width:28px;height:28px;flex:0 0 28px;margin:0;accent-color:var(--green);}
#kiosk .ko-done{text-align:center;padding-top:6vh;color:var(--sf-green-ink);}
#kiosk .ko-done .ko-h1,#kiosk .ko-done .ko-sub{color:var(--text);}
#kiosk .ko-desk{font-size:var(--sf-fs-xl);font-weight:600;margin:18px 0 6px;color:var(--text);}
#kiosk .ko-foot{display:flex;justify-content:flex-end;padding-top:24px;}
#kiosk .ko-exit{min-height:44px;padding:0 14px;border:none;background:transparent none;color:var(--muted);font-size:var(--sf-fs-md);cursor:pointer;}
#kiosk .dob-row{display:flex;gap:8px;}
#kiosk .dob-row select{min-height:56px;font-size:18px;}
.kiosk-badge{background:rgba(var(--green-rgb),.14);color:var(--sf-green-ink);}
#tab-settings .set-kiosk{margin-top:14px;display:flex;flex-direction:column;gap:6px;align-items:flex-start;}
/* ── Deposits (2026-10-09): the check-in's deposit block, the return's, and the settle dialog ── */
.ci-dep .ci-dep-ref,.ret-dep-keep input{width:100%;box-sizing:border-box;min-height:44px;margin-top:8px;}
.ret-dep-keep{display:flex;gap:8px;flex-wrap:wrap;}
.ret-dep-keep input[type="number"]{flex:0 0 140px;width:140px;}
.ret-dep-keep input[type="text"]{flex:1;min-width:180px;}
.ret-dep,.ci-dep{border-top:1px solid var(--sf-line2);padding-top:10px;}
.br-dep{font-size:var(--sf-fs-xs);font-weight:600;color:var(--orange);margin-inline-start:8px;white-space:nowrap;}
.br-dep-note{margin:10px 0 0;font-size:var(--sf-fs-sm);color:var(--muted);}
#dep-modal .dep-box{max-width:440px;width:calc(100vw - 32px);}
#dep-modal .dep-line{font-weight:600;margin-bottom:10px;}

/* ── Personal data hidden until shown (2026-10-10): the masked value is a button; History > Data access ── */
body.view-staff .pii-m:is(#_x,*){display:inline-flex;align-items:center;position:relative;min-height:24px;margin:0;padding:0 4px;border:0;border-bottom:1px dashed var(--muted);border-radius:0;background:transparent none;color:inherit;font:inherit;letter-spacing:0;cursor:pointer;direction:ltr;unicode-bidi:isolate;}
body.view-staff .pii-m:is(#_x,*)::after{content:'';position:absolute;inset:-10px -4px;}
body.view-staff .pii-m:is(#_x,*):hover{color:var(--green);border-bottom-color:var(--green);}
body.view-staff .pii-m:is(#_x,*):focus-visible{outline:2px solid var(--green);outline-offset:2px;}
body.view-staff .pii-v:focus{outline:medium none;}
#mny-host .pa-review{margin-top:24px;}
#mny-host .pa-stamp{display:flex;flex-wrap:wrap;align-items:center;gap:10px;font-size:var(--sf-fs-sm);color:var(--text);}
#mny-host .pa-stamp.pa-due b{color:var(--orange);}
#mny-host .pa-stamp button{min-height:44px;}
#mny-host .pa-tbl tr.pa-off td{color:var(--muted);}

/* ── Accounts and Members as a list (2026-10-10, the owner: "make the accounts and members pages look like a list
   instead and make it very aligned and organized and equally space") ──
   On a tablet or a laptop every account is one row of the same height, in columns that line up under a header:
   name, email, phone, social accounts, tags and badges, then the same six buttons at the same width. A cell that
   does not fit ends in an ellipsis rather than wrapping (the full value is in Edit and Bookings & history). What
   asks for staff action is a strip under its row (.am-extras), so the rows themselves stay even. A phone keeps
   the card. */
@media (min-width:768px){
  body.view-staff .am-list{border:1px solid var(--border);border-radius:var(--sf-r-card);overflow:hidden;background:var(--sf-card,var(--s1));}
  body.view-staff .am-list :is(.am-cust,.am-head){display:flex;align-items:center;gap:14px;min-height:62px;margin:0;padding:8px 16px;
    border:0;border-bottom:1px solid var(--border);border-radius:0;background:none;box-sizing:border-box;}
  body.view-staff .am-list #am-cust-rows .am-row:last-child>.am-cust:last-child{border-bottom:0;}
  body.view-staff .am-list #am-cust-rows .am-cust:hover{background:rgba(var(--tint-rgb),.025);}
  body.view-staff .am-list :is(.am-cust,.am-head) .am-cust-main{flex:1;min-width:0;display:grid;align-items:center;gap:0 16px;
    grid-template-columns:minmax(150px,1.25fr) minmax(0,1.1fr) 124px minmax(0,1.3fr) minmax(0,1.1fr);}
  body.view-staff .am-list .am-cust-contact{display:contents;}
  body.view-staff .am-list .am-cust-main>*,body.view-staff .am-list .am-cust-contact>*{min-width:0;overflow:hidden;white-space:nowrap;text-overflow:ellipsis;}
  body.view-staff .am-list .am-cust-name{font-size:var(--sf-fs-md);font-weight:600;line-height:20px;}
  /* under the name: the stage pill whole, then where they heard of us and the sorted-on value, each onto a line of
     its own when the column is narrow (2026-11-08: on a laptop the pill was squeezed to "Ne" and "No-s" with the
     next item pressed against it), the same as the tags (the owner, 2026-10-11: "no clipped pills") */
  body.view-staff .am-list .am-c-sub{display:flex;flex-wrap:wrap;align-items:center;gap:2px 8px;line-height:18px;}
  body.view-staff .am-list .am-c-sub>:empty{display:none;}
  body.view-staff .am-list .am-c-sub .am-meta{max-width:100%;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;font-size:var(--sf-fs-xs);margin:0;}
  body.view-staff .am-list .am-c-sub .n6p-stage{display:block;max-width:100%;box-sizing:border-box;overflow:hidden;text-overflow:ellipsis;}
  body.view-staff .am-list :is(.am-c-email,.am-c-phone){font-size:var(--sf-fs-sm);color:var(--text);line-height:20px;}
  body.view-staff .am-list .am-c-phone{font-variant-numeric:tabular-nums;}
  /* every tag and badge shows (2026-10-11, the owner: "i want all the tags to be visible dont show +1 +2"): they wrap
     onto a second line, and the row grows, rather than hide */
  body.view-staff .am-list .am-chips{display:flex;flex-wrap:wrap;align-items:center;gap:4px 6px;margin:0;padding-block:4px;}
  body.view-staff .am-list .am-chips>*{flex:none;}
  body.view-staff .am-list .am-none{color:var(--muted-l,var(--muted));}
  body.view-staff .am-list .am-c-tags{display:flex;align-items:center;white-space:normal;overflow:visible;}
  body.view-staff .am-list .am-c-soc{display:flex;flex-direction:column;align-items:flex-start;justify-content:center;gap:1px;}
  /* the same six buttons, the same width on every row (and an empty slot of that width over them in the header) */
  body.view-staff .am-list .am-cust-actions{flex:none;width:316px;display:flex;justify-content:flex-end;align-items:center;gap:6px;}
  body.view-staff .am-list .am-cust-actions .btn-sm{height:36px;min-height:var(--sf-ctl-size);padding:0;justify-content:center;}
  body.view-staff .am-list .am-cust-actions .btn-sm:is(.am-flag,.am-hist,.am-vcard,.am-bdg-btn){width:32px;}
