.lead-mk{display:inline-flex;align-items:center;justify-content:center;flex:none;margin-inline-start:6px;width:20px;height:18px;background:#1971c2;color:#fff;border-radius:var(--sf-r-xs);vertical-align:middle;}
.sn-ico{display:block;width:14px;height:14px;}
