body:not(.view-staff) .ticket-card.tk-th:is(.th-comm,.th-runher,.th-event,.th-petromin,.th-swim,.th-vlap,.th-defe5k,.th-blood,.th-yoga) .code-k-bd{--code-k:#c8102e;}
