/* the date card: white, the wash from the far corner, the logo, the name, when / how far / where, the cause */
body .sess-card.defe-card{
  gap:6px;padding-top:14px;color:var(--df-ink);
  background-color:#fff;
  background-image:radial-gradient(120% 140% at 100% 100%,rgba(var(--df-wash),.30) 0%,rgba(var(--df-wash),.12) 40%,rgba(255,255,255,0) 68%);
  border:1px solid rgba(162,43,99,.30);border-inline-start:3px solid var(--df-berry);}
html[dir="rtl"] body .sess-card.defe-card{
  background-image:radial-gradient(120% 140% at 0% 100%,rgba(var(--df-wash),.30) 0%,rgba(var(--df-wash),.12) 40%,rgba(255,255,255,0) 68%);}
body .sess-card.defe-card:hover:not(.sess-full){background-color:#FFF7FA;}
body .sess-card.defe-card.sess-selected{background-color:#FCEAF1;border-color:rgba(162,43,99,.6);border-inline-start-color:var(--df-berry);}
.defe-card-top{display:flex;align-items:center;gap:10px;min-width:0;}
.defe-card-logo{height:38px;width:auto;max-width:100%;object-fit:contain;display:block;}
.defe-card-title{font-family:'Space Grotesk',var(--font-body);font-size:19px;font-weight:800;letter-spacing:.6px;text-transform:uppercase;line-height:1.15;color:var(--df-berry);overflow-wrap:anywhere;}
:is(html[lang="ar"],html[lang="ur"]) .defe-card-title{font-family:'IBM Plex Sans Arabic',sans-serif;letter-spacing:0;text-transform:none;}
.defe-card-meta{display:flex;flex-wrap:wrap;align-items:center;gap:3px 9px;font-size:13px;font-weight:600;color:#5b3a4a;min-width:0;}
.defe-card-meta i{width:1px;height:12px;background:rgba(162,43,99,.35);display:inline-block;flex:none;}
.defe-card-foot{display:flex;align-items:center;justify-content:space-between;gap:8px;flex-wrap:wrap;min-width:0;}
.defe-card-cause{display:inline-flex;align-items:center;gap:5px;font-size:12px;font-weight:700;color:var(--df-berry);min-width:0;}
.defe-card-cause .ptn-rb,.defe-flow-sub .ptn-rb{color:var(--df-rose);flex:none;}
/* the flow from the runner step on, and the booked page: berry actions, a blush page */
body.defe5k:not(.view-staff){--go:#A22B63;--go-2:#861F50;--go-wash:rgba(215,130,160,.16);--neon:#F2A9C4;--green-rgb:162,43,99;--accent2:rgba(162,43,99,.45);}
body.defe5k:not(.view-staff) .toggle-btn.active{background:var(--df-berry);border-color:var(--df-berry);color:#fff;}
.defe-flow-head{display:flex;align-items:center;gap:14px;margin:0 0 16px;padding:14px 16px;min-width:0;
  background:radial-gradient(120% 160% at 100% 100%,rgba(var(--df-wash),.32) 0%,rgba(var(--df-wash),.1) 45%,rgba(255,255,255,0) 72%) #fff;
  border:1px solid rgba(162,43,99,.28);border-inline-start:3px solid var(--df-berry);color:var(--df-ink);}
html[dir="rtl"] .defe-flow-head{background:radial-gradient(120% 160% at 0% 100%,rgba(var(--df-wash),.32) 0%,rgba(var(--df-wash),.1) 45%,rgba(255,255,255,0) 72%) #fff;}
.defe-flow-logo{height:46px;width:auto;max-width:34%;object-fit:contain;flex:none;display:block;}
.defe-flow-copy{min-width:0;flex:1 1 auto;}
.defe-flow-name{font-family:'Space Grotesk',var(--font-body);font-size:18px;font-weight:800;letter-spacing:.5px;text-transform:uppercase;color:var(--df-berry);line-height:1.2;overflow-wrap:anywhere;}
:is(html[lang="ar"],html[lang="ur"]) .defe-flow-name{font-family:'IBM Plex Sans Arabic',sans-serif;letter-spacing:0;text-transform:none;}
.defe-flow-sub{display:flex;align-items:center;gap:5px;margin-top:3px;font-size:12.5px;font-weight:600;color:#5b3a4a;}
/* when the kits go out and when the race starts */
.defe-when{display:grid;gap:6px;margin:0 0 14px;padding:10px 12px;background:#FDF1F6;border:1px solid rgba(162,43,99,.22);color:var(--df-ink);}
.defe-when-row{display:flex;flex-wrap:wrap;gap:2px 10px;font-size:13px;line-height:1.4;min-width:0;}
.defe-when-k{font-weight:800;color:var(--df-berry);min-width:110px;}
.defe-when-v{min-width:0;overflow-wrap:anywhere;}
.run-km-chip.defe-km{background:rgba(162,43,99,.1);color:var(--df-berry);border-color:rgba(162,43,99,.35);}
/* "Have you registered for the race?" */
.defe-reg{display:grid;gap:8px;margin:0 0 16px;padding:14px 16px;background:#fff;border:1.5px solid var(--df-berry);color:var(--df-ink);}
.defe-reg-q{font-size:16px;font-weight:800;color:var(--df-berry);}
.defe-reg-sub{font-size:13px;line-height:1.45;color:#5b3a4a;}
.defe-reg-yn{display:flex;gap:8px;}
.defe-reg-yn .toggle-btn{flex:1 1 0;border-radius:0;}
body:not(.view-staff) .defe-reg-yn .toggle-btn.active{background:var(--df-berry);border-color:var(--df-berry);color:#fff;}
body:not(.view-staff) .defe-reg-yn .toggle-btn.active::before{background:#F8D3E1;}
.defe-reg-no{display:grid;gap:8px;}
.defe-reg-code{padding:8px 10px;background:#FDF1F6;border:1px dashed rgba(162,43,99,.5);font-size:13.5px;font-weight:600;line-height:1.45;color:var(--df-ink);}
.defe-reg-code strong{font-size:15px;font-weight:800;letter-spacing:1px;color:var(--df-berry);unicode-bidi:isolate;}
body:not(.view-staff) .defe-reg .defe-reg-link{display:flex;align-items:center;justify-content:center;min-height:44px;border-radius:0;text-decoration:none;background:var(--df-berry);border-color:var(--df-berry);color:#fff;text-align:center;}
body:not(.view-staff) .defe-reg .defe-reg-link:hover{background:var(--df-berry-dk);color:#fff;}
.defe-reg.defe-reg-done{display:flex;align-items:center;gap:10px;border-width:1px;border-color:rgba(162,43,99,.3);background:#FDF1F6;font-size:13.5px;font-weight:600;}
.defe-reg.defe-reg-done .cu-ic{color:var(--df-berry);flex:none;}
.defe-reg.defe-reg-done .btn-sm{border-radius:0;flex:none;}
/* the ticket: white, Defe's wash, the logo as its mark */
body:not(.view-staff) :is(#tab-myrides,#tab-register) .ticket-card.tk-th.th-defe5k{
  --night:#fff;--night-2:#FDF0F5;--night-ink:#3B1328;--night-ink-2:rgba(59,19,40,.66);--night-line:rgba(162,43,99,.2);--neon:#A22B63;
  --night-amber:#8A5300;--night-red:#B42318;--night-red-line:rgba(180,35,24,.35);color:var(--night-ink);
  background:radial-gradient(120% 60% at 100% 100%,rgba(var(--df-wash),.28) 0%,rgba(var(--df-wash),.1) 38%,rgba(255,255,255,0) 66%) #fff;
  border:1px solid rgba(162,43,99,.32);}
html[dir="rtl"] body:not(.view-staff) :is(#tab-myrides,#tab-register) .ticket-card.tk-th.th-defe5k{
  background:radial-gradient(120% 60% at 0% 100%,rgba(var(--df-wash),.28) 0%,rgba(var(--df-wash),.1) 38%,rgba(255,255,255,0) 66%) #fff;}
.ticket-card .tk-logo-ev .tk-logo-defe5k{height:34px;}
.ticket-card .defe-when{margin:10px 0;}
/* staff: the date's chip, and the answer on Bookings */
body.view-staff :is(.sess-summary-chip,.sess-lc).th-defe5k{
  --sf-chip-bg:radial-gradient(120% 160% at 100% 100%,rgba(var(--df-wash),.28) 0%,rgba(var(--df-wash),.1) 40%,rgba(255,255,255,0) 70%) #fff;
  --sf-ring:var(--df-berry);border-color:rgba(162,43,99,.4);color:var(--df-ink);background:var(--sf-chip-bg);}
/* dark staff theme: the white card held the dark desk's light muted text and counts (bug hunt 2026-10-28) */
html[data-staff-theme="dark"] body.view-staff :is(.sess-summary-chip,.sess-lc).th-defe5k{
  --sf-chip-bg:radial-gradient(120% 160% at 100% 100%,rgba(var(--df-wash),.24) 0%,rgba(var(--df-wash),.08) 40%,rgba(16,19,24,0) 70%) #101318;
  --sf-ring:var(--df-rose);border-color:rgba(215,130,160,.4);color:var(--text);}
.rr-chip{display:inline-block;padding:1px 6px;font-size:var(--sf-fs-xs);font-weight:600;border:1px solid;white-space:nowrap;}
.rr-chip.rr-yes{color:#0c6b3a;border-color:rgba(12,107,58,.4);background:rgba(12,107,58,.08);}
.rr-chip.rr-no{color:var(--df-berry);border-color:rgba(162,43,99,.45);background:rgba(162,43,99,.08);}
/* the finisher's badge shares the Defe ride badge's medal colours (.sp-defe, BDG_SPECIAL.defe) */
@media(max-width:400px){.defe-card-title{font-size:17px;}.defe-card-logo{height:32px;}.defe-flow-logo{height:38px;}.defe-when-k{min-width:0;width:100%;}}
/* ════════════════════════════════════════════════════════════════════════
   YOGA (the user, 2026-11-12) - Hatha Yoga for Cyclists with Jassim Alsaady, a date inside MicroMobility
   Experiences. "Sunset Hatha": hatha joins ha, the sun, and tha, the moon, and the first session ends just
   before the sun sets over Jeddah. Warm sand, clay for the sun, the title and every action, sage for the moon,
   deep earth for ink; calm and low in saturation, no neon. The date card (a sun rising from its far corner,
   three breaths around it), the flow from the review on (body.yoga-skin), the ticket, staff's chips and rows.
   ════════════════════════════════════════════════════════════════════════ */
:root{--yg-clay:#B4532F;--yg-clay-dk:#93401F;--yg-sage:#6E8266;--yg-sage-ink:#55684E;--yg-ink:#3B2A20;--yg-ink-2:#6B5446;--yg-sand:#F8F0E5;--yg-cream:#FFFBF5;--yg-glow:236,150,96;}
.ev-yoga{--ev:#B4532F;--ev-rgb:180,83,47;}
body:not(.view-staff) .ev-yoga:not(.landing-event-card){--ev:#B4532F;--ev-rgb:180,83,47;}
html[data-staff-theme="dark"] body.view-staff .ev-yoga{--ev:#E8916A;--ev-rgb:232,145,106;}
/* the date card: cream, the low sun's glow from the far corner, the mark, the name, when / how long / where, who leads it */
body .sess-card.yg-card{
  position:relative;overflow:hidden;isolation:isolate;gap:6px;padding-top:14px;color:var(--yg-ink);
  background-color:var(--yg-cream);
  background-image:radial-gradient(110% 130% at 100% 100%,rgba(var(--yg-glow),.30) 0%,rgba(var(--yg-glow),.12) 38%,rgba(255,251,245,0) 66%);
  border:1px solid rgba(180,83,47,.28);border-inline-start:3px solid var(--yg-clay);}
html[dir="rtl"] body .sess-card.yg-card{
  background-image:radial-gradient(110% 130% at 0% 100%,rgba(var(--yg-glow),.30) 0%,rgba(var(--yg-glow),.12) 38%,rgba(255,251,245,0) 66%);}
body .sess-card.yg-card:hover:not(.sess-full){background-color:#FFF6EC;}
body .sess-card.yg-card.sess-selected,
body:not(.view-staff) .sess-day-list .sess-card.yg-card.sess-selected{background-color:#FBEBDD;border-color:rgba(180,83,47,.6);border-inline-start-color:var(--yg-clay);box-shadow:inset 0 0 0 2px var(--yg-clay);}
body:not(.view-staff) .sess-card.yg-card .sess-tick{box-shadow:inset 0 0 0 1.5px rgba(180,83,47,.45);}
body:not(.view-staff) .sess-card.yg-card.sess-selected .sess-tick{background:var(--yg-clay);box-shadow:none;}
body .sess-card.yg-card:focus-visible{outline:2px solid var(--yg-clay);outline-offset:2px;}
.yg-scene{position:absolute;z-index:-1;bottom:-1px;inset-inline-end:-24px;width:168px;height:84px;pointer-events:none;}
.yg-scene .yg-ring{fill:none;stroke:rgba(180,83,47,.16);stroke-width:1.2;}
.yg-scene .yg-sunb{fill:rgba(var(--yg-glow),.34);}
.yg-card-top{display:flex;align-items:center;gap:10px;min-width:0;}
.yg-card-mark{height:30px;width:auto;display:block;flex:none;}
.yg-card-title{font-family:'Marcellus','Space Grotesk','Noto Sans Devanagari','Noto Sans Bengali',Georgia,serif;font-size:21px;font-weight:400;letter-spacing:.3px;line-height:1.2;color:var(--yg-clay);overflow-wrap:anywhere;}
:is(html[lang="ar"],html[lang="ur"]) .yg-card-title{font-family:'IBM Plex Sans Arabic',sans-serif;font-weight:600;letter-spacing:0;}
.yg-card-meta{display:flex;flex-wrap:wrap;align-items:center;gap:3px 9px;font-size:13px;font-weight:600;color:var(--yg-ink-2);min-width:0;}
.yg-card-meta i{width:1px;height:12px;background:rgba(180,83,47,.35);display:inline-block;flex:none;}
.yg-card-foot{display:flex;align-items:center;justify-content:space-between;gap:8px;flex-wrap:wrap;min-width:0;}
.yg-card-with{font-size:12.5px;font-weight:700;color:var(--yg-sage-ink);min-width:0;overflow-wrap:anywhere;}
/* the flow from the review on, and the booked page: clay actions, a sand wash */
body.yoga-skin:not(.view-staff){--go:#B4532F;--go-2:#93401F;--go-wash:rgba(236,150,96,.16);--neon:#F3C9A8;--green-rgb:180,83,47;--accent2:rgba(180,83,47,.45);}
body.yoga-skin:not(.view-staff) .toggle-btn.active{background:var(--yg-clay);border-color:var(--yg-clay);color:#fff;}
.yg-flow-head{display:flex;align-items:center;gap:14px;margin:0 0 16px;padding:14px 16px;min-width:0;
  background:radial-gradient(120% 160% at 100% 100%,rgba(var(--yg-glow),.30) 0%,rgba(var(--yg-glow),.1) 45%,rgba(255,251,245,0) 72%) var(--yg-cream);
  border:1px solid rgba(180,83,47,.26);border-inline-start:3px solid var(--yg-clay);color:var(--yg-ink);}
html[dir="rtl"] .yg-flow-head{background:radial-gradient(120% 160% at 0% 100%,rgba(var(--yg-glow),.30) 0%,rgba(var(--yg-glow),.1) 45%,rgba(255,251,245,0) 72%) var(--yg-cream);}
.yg-flow-mark{height:40px;width:auto;flex:none;display:block;}
.yg-flow-copy{min-width:0;flex:1 1 auto;}
.yg-flow-name{font-family:'Marcellus','Space Grotesk','Noto Sans Devanagari','Noto Sans Bengali',Georgia,serif;font-size:19px;font-weight:400;letter-spacing:.3px;color:var(--yg-clay);line-height:1.2;overflow-wrap:anywhere;}
:is(html[lang="ar"],html[lang="ur"]) .yg-flow-name{font-family:'IBM Plex Sans Arabic',sans-serif;font-weight:600;letter-spacing:0;}
.yg-flow-sub{margin-top:3px;font-size:12.5px;font-weight:700;color:var(--yg-sage-ink);}
/* who leads it, the level, what to bring: on the ticket */
.yg-know{display:grid;gap:6px;margin:10px 0;padding:10px 12px;background:var(--yg-sand);border:1px solid rgba(180,83,47,.2);border-inline-start:3px solid var(--yg-sage);color:var(--yg-ink);}
.yg-know-row{display:flex;flex-wrap:wrap;gap:2px 10px;font-size:13px;line-height:1.4;min-width:0;}
.yg-know-k{font-weight:800;color:var(--yg-clay-dk);min-width:76px;}
.yg-know-v{min-width:0;overflow-wrap:anywhere;}
/* the ticket: cream, the low sun along its foot, the mark */
body:not(.view-staff) :is(#tab-myrides,#tab-register) .ticket-card.tk-th.th-yoga{
  --night:var(--yg-cream);--night-2:#F6EADC;--night-ink:#3B2A20;--night-ink-2:rgba(59,42,32,.68);--night-line:rgba(180,83,47,.2);--neon:#B4532F;
  --night-amber:#8A5300;--night-red:#B42318;--night-red-line:rgba(180,35,24,.35);color:var(--night-ink);
  background:radial-gradient(120% 55% at 100% 100%,rgba(var(--yg-glow),.30) 0%,rgba(var(--yg-glow),.1) 38%,rgba(255,251,245,0) 66%) var(--yg-cream);
  border:1px solid rgba(180,83,47,.3);}
html[dir="rtl"] body:not(.view-staff) :is(#tab-myrides,#tab-register) .ticket-card.tk-th.th-yoga{
  background:radial-gradient(120% 55% at 0% 100%,rgba(var(--yg-glow),.30) 0%,rgba(var(--yg-glow),.1) 38%,rgba(255,251,245,0) 66%) var(--yg-cream);}
body:not(.view-staff) :is(#tab-myrides,#tab-register) .ticket-card.tk-th.th-yoga .ticket-num{font-family:'Marcellus','Space Grotesk',Georgia,serif;font-weight:400;}
.ticket-card .tk-logo-ev .tk-logo-yoga{height:30px;}
/* staff: the date's chip and the Bookings row's colour */
body.view-staff :is(.sess-summary-chip,.sess-lc).th-yoga{
  --sf-chip-bg:radial-gradient(120% 160% at 100% 100%,rgba(var(--yg-glow),.26) 0%,rgba(var(--yg-glow),.1) 40%,rgba(255,251,245,0) 70%) var(--yg-cream);
  --sf-ring:var(--yg-clay);border-color:rgba(180,83,47,.4);color:var(--yg-ink);background:var(--sf-chip-bg);}
html[data-staff-theme="dark"] body.view-staff :is(.sess-summary-chip,.sess-lc).th-yoga{
  --sf-chip-bg:radial-gradient(120% 160% at 100% 100%,rgba(var(--yg-glow),.22) 0%,rgba(var(--yg-glow),.08) 40%,rgba(16,19,24,0) 70%) #101318;
  --sf-ring:#E8916A;border-color:rgba(232,145,106,.4);color:var(--text);}
body.view-staff .sess-summary-chip.th-yoga .sess-chip-event{font-family:'Marcellus',Georgia,serif;font-weight:400;font-size:var(--sf-fs-xs);letter-spacing:0;color:var(--yg-clay);}
:is(html[lang="ar"],html[lang="ur"]) body.view-staff .sess-summary-chip.th-yoga .sess-chip-event{font-family:'IBM Plex Sans Arabic',sans-serif;font-weight:600;letter-spacing:0;}
html[data-staff-theme="dark"] body.view-staff .sess-summary-chip.th-yoga .sess-chip-event{color:#E8916A;}
body.view-staff :is(#tab-queue,#tab-waitlist) .rq-ev-yoga{--rq-ev:#b4532f;}
html[data-staff-theme="dark"] body.view-staff :is(#tab-queue,#tab-waitlist) .rq-ev-yoga{--rq-ev:#e8916a;}
@media(max-width:400px){.yg-card-title{font-size:19px;}.yg-card-mark{height:26px;}.yg-flow-mark{height:34px;}.yg-know-k{min-width:0;width:100%;}.yg-scene{width:140px;height:70px;}}
/* STAFF COMMENTS (2026-10-23): a staff-only thread on a booking or an application (_scOpen, staff_comments) */
.sc-chip{display:flex;align-items:center;gap:4px;margin-top:3px;max-width:24ch;padding:1px 6px;border:1px solid var(--border);background:var(--surface,transparent);color:var(--text);font:inherit;font-size:var(--staff-fs-sm,12px);cursor:pointer;border-radius:0;}
.sc-chip .sc-chip-t{overflow:hidden;text-overflow:ellipsis;white-space:nowrap;color:var(--muted);font-weight:500;}
.sc-card{display:flex;flex-wrap:wrap;align-items:center;gap:8px;margin-top:8px;}
.sc-card-last{flex:1 1 220px;min-width:0;font-size:13px;overflow-wrap:anywhere;}
/* An application card's newest three comments (2026-11-10), above the button to the whole thread. */
.sc-card-list{flex:1 1 100%;min-width:0;list-style:none;margin:0;padding:0;padding-inline-start:10px;border-inline-start:3px solid var(--sf-line,var(--border));display:flex;flex-direction:column;gap:6px;}
.sc-card-c{font-size:13px;overflow-wrap:anywhere;}
.sc-card-b{white-space:pre-wrap;}
/* A phone shows an application's comments under its name, not below its fifteen answers (the user, 2026-11-10). */
@media(max-width:767px){
  :is(#ca-list,#la-list)>.ca-row{display:flex;flex-direction:column;}
  :is(#ca-list,#la-list)>.ca-row>.ca-head{order:-2;}
  :is(#ca-list,#la-list)>.ca-row>.sc-card-has{order:-1;}
}
.sc-meta{color:var(--muted);font-size:12px;font-weight:600;}
#sc-sheet .sc-sheet{width:min(92vw,520px);max-height:calc(100vh - 40px);max-height:calc(100dvh - 40px);display:flex;flex-direction:column;}
#sc-sheet .sc-hint{font-size:12px;color:var(--muted);font-weight:600;margin-bottom:10px;}
#sc-sheet .sc-list{list-style:none;margin:0 0 12px;padding:0;overflow-y:auto;min-height:40px;display:flex;flex-direction:column;gap:8px;}
#sc-sheet .sc-item{border:1px solid var(--border);padding:8px 10px;}
#sc-sheet .sc-item .sc-meta{display:flex;align-items:center;gap:6px;flex-wrap:wrap;}
#sc-sheet .sc-del{margin-inline-start:auto;}
#sc-sheet .sc-body{margin-top:4px;white-space:pre-wrap;overflow-wrap:anywhere;font-size:14px;}
#sc-sheet .sc-none{color:var(--muted);font-size:13px;}
#sc-sheet .sc-lbl{font-size:13px;font-weight:600;margin-bottom:4px;}
#sc-sheet textarea{width:100%;box-sizing:border-box;resize:vertical;font:inherit;padding:8px;}
/* Round s10 (2026-11-10): the figures bar's places left by bike type and the night's Notes; the notes' and Record incident
   pop-ups (the desk sheet, centred); incidents in the account window and History > Incidents */
body.view-staff :is(#tab-queue,#tab-waitlist) .s10-figs{display:flex;align-items:center;flex-wrap:wrap;gap:6px 8px;padding-inline-start:8px;border-inline-start:1px solid var(--sf-line,var(--border));}
body.view-staff #tab-queue .tyl-row{display:flex;align-items:center;flex-wrap:wrap;gap:4px 10px;font-size:var(--sf-fs-sm);font-weight:600;color:var(--muted);}
body.view-staff #tab-queue .tyl{white-space:nowrap;}
body.view-staff #tab-queue .tyl b{color:var(--text);}
body.view-staff #tab-queue .tyl-0 b{color:var(--orange);}
body.view-staff #tab-queue .tyl-x{color:var(--red);}
body.view-staff #tab-queue .snt-chip{white-space:nowrap;}
@media(max-width:767px){body.view-staff #tab-queue .s10-figs,body.view-staff #tab-queue .tyl-row{flex-wrap:nowrap;}}
body.view-staff #walkin-modal .tyl-wi{display:block;font-size:var(--sf-fs-xs);font-weight:600;opacity:.8;}
body.view-staff :is(#desk-sheet,#cust-modal,#tab-history) :is(.snt-list,.inc-list){list-style:none;margin:0;padding:0;display:flex;flex-direction:column;gap:8px;}
body.view-staff :is(#desk-sheet,#cust-modal,#tab-history) :is(.snt-item,.inc-li){border:1px solid var(--border);border-radius:var(--r-md,var(--sf-r-ctl));padding:8px 10px;}
body.view-staff :is(#desk-sheet,#cust-modal,#tab-history) :is(.snt-item,.inc-li) .sc-meta{display:flex;align-items:center;gap:6px;flex-wrap:wrap;}
body.view-staff #desk-sheet .snt-acts{margin-inline-start:auto;display:inline-flex;gap:6px;}
body.view-staff :is(#desk-sheet,#cust-modal,#tab-history) :is(.snt-body,.inc-note){margin-top:4px;white-space:pre-wrap;overflow-wrap:anywhere;font-size:var(--sf-fs-md);}
body.view-staff #desk-sheet .snt-none{color:var(--muted);font-size:var(--sf-fs-sm);}
body.view-staff #desk-sheet .snt-lbl{display:block;font-size:var(--sf-fs-sm);font-weight:600;margin:0 0 4px;}
body.view-staff #desk-sheet :is(.snt-new,.inc-form){display:flex;flex-direction:column;gap:6px;}
body.view-staff #desk-sheet :is(.snt-new,.inc-form) textarea{width:100%;box-sizing:border-box;resize:vertical;font:inherit;padding:8px;}
body.view-staff #desk-sheet .inc-kinds{display:flex;flex-wrap:wrap;gap:6px;}
body.view-staff #desk-sheet .inc-k{min-height:44px;padding:0 12px;border:1.5px solid var(--border);border-radius:var(--r-md,var(--sf-r-ctl));background:var(--s1);color:var(--text);font:inherit;font-weight:600;cursor:pointer;}
body.view-staff #desk-sheet .inc-k[aria-pressed="true"]{border-color:var(--green);background:rgba(var(--green-rgb),.12);color:var(--green);}
body.view-staff #desk-sheet .inc-k:focus-visible{outline:2px solid var(--green);outline-offset:2px;}
body.view-staff #desk-sheet .inc-err{color:var(--red);font-size:var(--sf-fs-sm);font-weight:600;}
body.view-staff #desk-sheet .inc-err:empty{display:none;}
body.view-staff #cust-modal .inc-list{margin-bottom:10px;}
body.view-staff .rmt-chip.rmt-inc{color:var(--orange);display:inline-flex;align-items:center;gap:4px;}
body.view-staff #tab-dashboard .snt-dash-b{white-space:normal;overflow-wrap:anywhere;}
/* Night checklists (staff round s10, second batch, D10): the opening and close-night lists in the centred desk sheet,
   the Dashboard's prompt and Settings' editor. Tokens only: --fs-*, --sf-r-*, no raw font sizes, weights 600 at most.
   An item is a grid: its mark (or the tick's box) in the first column, the reason and the way to do it under the words. */
body.view-staff #desk-sheet .ck-body{display:flex;flex-direction:column;gap:8px;}
body.view-staff #desk-sheet #ck-foot{display:contents;}
body.view-staff #desk-sheet .ck-prog{font-weight:600;color:var(--muted);}
body.view-staff #desk-sheet .ck-prog.ck-all{color:var(--green);}
body.view-staff #desk-sheet .ck-note{color:var(--muted);font-size:var(--fs-sm);}
body.view-staff #desk-sheet .ck-h{margin:4px 0 0;font-size:var(--fs-sm);font-weight:600;color:var(--muted);}
body.view-staff #desk-sheet .ck-list{list-style:none;margin:0;padding:0;display:flex;flex-direction:column;gap:6px;}
body.view-staff #desk-sheet .ck-li{display:grid;grid-template-columns:22px minmax(0,1fr);align-items:center;gap:2px 8px;border:1px solid var(--border);border-radius:var(--sf-r-ctl);padding:6px 10px;background:var(--s1);}
body.view-staff #desk-sheet .ck-li.ck-done{border-color:rgba(var(--green-rgb),.35);}
body.view-staff #desk-sheet .ck-li>:is(.ck-why,.ck-acts){grid-column:2;}
body.view-staff #desk-sheet .ck-li>.ck-tick{grid-column:1/-1;}
body.view-staff #desk-sheet .ck-mk{display:inline-flex;justify-content:center;}
body.view-staff #desk-sheet .ck-mk.ck-ok{color:var(--green);}
body.view-staff #desk-sheet .ck-mk.ck-no{color:var(--orange);}
body.view-staff #desk-sheet .ck-mk.ck-wait{color:var(--muted);}
body.view-staff #desk-sheet .ck-l{font-weight:600;overflow-wrap:anywhere;}
body.view-staff #desk-sheet .ck-why{color:var(--muted);font-size:var(--fs-sm);overflow-wrap:anywhere;}
body.view-staff #desk-sheet .ck-tick{display:flex;align-items:center;gap:8px;min-height:44px;padding:0;border:0;background:none;color:var(--text);font:inherit;text-align:start;cursor:pointer;}
body.view-staff #desk-sheet .ck-tick svg{flex:none;color:var(--muted);}
body.view-staff #desk-sheet .ck-tick[aria-checked="true"] svg{color:var(--green);}
body.view-staff #desk-sheet .ck-tick:disabled{cursor:default;}
body.view-staff #desk-sheet .ck-tick:focus-visible{outline:2px solid var(--green);outline-offset:2px;border-radius:var(--sf-r-xs);}
body.view-staff #desk-sheet .ck-acts{display:flex;flex-direction:column;align-items:flex-start;gap:6px;margin-top:4px;}
body.view-staff #desk-sheet .ck-owe-r{display:flex;flex-wrap:wrap;align-items:center;justify-content:space-between;gap:6px;align-self:stretch;overflow-wrap:anywhere;}
body.view-staff #desk-sheet .ck-left{display:inline-flex;align-items:center;gap:4px;}
body.view-staff #desk-sheet .ck-left[aria-pressed="true"]{background:var(--sf-select);border-color:var(--text);color:var(--text);}
body.view-staff #desk-sheet .ck-open{display:flex;flex-direction:column;gap:4px;padding:8px 10px;border:1px solid rgba(var(--warn-rgb),.45);border-radius:var(--sf-r-ctl);background:rgba(var(--warn-rgb),.07);color:var(--orange);font-size:var(--fs-sm);overflow-wrap:anywhere;}
body.view-staff #ck-set .ck-set-grid{display:grid;grid-template-columns:minmax(0,1fr);gap:12px;margin-top:8px;}
@media (min-width:768px){body.view-staff #ck-set .ck-set-grid{grid-template-columns:repeat(2,minmax(0,1fr));}}
body.view-staff #ck-set .ck-set-ol{list-style:none;margin:0 0 8px;padding:0;display:flex;flex-direction:column;gap:6px;}
body.view-staff #ck-set .ck-set-row{display:flex;align-items:center;gap:6px;}
body.view-staff #ck-set .ck-set-row input{flex:1 1 auto;min-width:0;}
body.view-staff #ck-set .ck-mv{display:inline-flex;align-items:center;justify-content:center;min-width:36px;}
body.view-staff #ck-set .ck-dn svg{transform:rotate(180deg);}
body.view-staff #ck-set .ck-set-foot{display:flex;align-items:center;gap:10px;flex-wrap:wrap;margin-top:8px;}
/* Victory Lap Doubles teams read as one (2026-10-25): the chip, and the team's rows framed and tinted together */
.vl-dbl-chip{display:inline-block;padding:0 6px;font-size:var(--sf-fs-xs);font-weight:600;background:#5b3fd6;color:#fff;}
.queue-table tbody tr.vl-dbl td,.vl-st-table tr.vl-dbl td{background-image:linear-gradient(rgba(91,63,214,.08),rgba(91,63,214,.08));}
.queue-table tbody tr.vl-dbl-alt td,.vl-st-table tr.vl-dbl-alt td{background-image:linear-gradient(rgba(91,63,214,.16),rgba(91,63,214,.16));}
.queue-table tbody tr.vl-dbl-t td,.vl-st-table tr.vl-dbl-t td{border-top:2px solid #5b3fd6;}
.queue-table tbody tr.vl-dbl-b td,.vl-st-table tr.vl-dbl-b td{border-bottom:2px solid #5b3fd6;}
.q-card.vl-dbl{outline:2px solid #5b3fd6;outline-offset:-2px;background-image:linear-gradient(rgba(91,63,214,.08),rgba(91,63,214,.08));}
.q-card.vl-dbl.vl-dbl-alt{background-image:linear-gradient(rgba(91,63,214,.16),rgba(91,63,214,.16));}
/* On Bookings every row and card also wears a row colour, whose background shorthand (0,3,4) wiped the team's tint
   and whose faint border-bottom-color (dark 0,4,5) greyed the closing rule: lay the tint over the row colour and
   outrank both (bug hunt 2026-10-28). Plain class selectors only (roster restyle budget); the comment mark's pattern cell
   and card keep their own background, and the opaque fallback keeps the pinned cells solid. */
:root body.view-staff .queue-table tbody tr.vl-dbl td:not(.cm-cell){background:linear-gradient(rgba(91,63,214,.08),rgba(91,63,214,.08)) var(--rs-bg,var(--s1));}
:root body.view-staff .queue-table tbody tr.vl-dbl.vl-dbl-alt td:not(.cm-cell){background:linear-gradient(rgba(91,63,214,.16),rgba(91,63,214,.16)) var(--rs-bg,var(--s1));}
:root body.view-staff .queue-table tbody tr.vl-dbl-b.vl-dbl-b td{border-bottom:2px solid #5b3fd6;}
:root body.view-staff .queue-mobile-view .q-card.vl-dbl:not(.cm-row-mark){background:linear-gradient(rgba(91,63,214,.08),rgba(91,63,214,.08)) var(--rs-bg,var(--s1));}
:root body.view-staff .queue-mobile-view .q-card.vl-dbl.vl-dbl-alt:not(.cm-row-mark){background:linear-gradient(rgba(91,63,214,.16),rgba(91,63,214,.16)) var(--rs-bg,var(--s1));}

/* ══ STAFF TIDY (2026-10-27) ═══════════════════════════════════════════════════════════════════════════
   The owner's engineer: "make the staff panel more organized, it looks very cluttered and not aligned
   properly". One page pattern for every section (title and description, the actions at its end, the
   section's tabs under it, then the content), one control height, and on Bookings the list where the
   eye lands: at 1280×900 the first booking used to start below the screen, under nine stacked blocks. */

/* ── Bookings: the view tabs under the title; the live-location switch at the row's end ── */
body.view-staff :is(#tab-queue,#tab-waitlist) .q-views{display:flex;align-items:center;gap:8px;flex-wrap:wrap;}
body.view-staff :is(#tab-queue,#tab-waitlist) .q-views>.live-share{margin:0;margin-inline-start:auto;flex-wrap:nowrap;}
body.view-staff :is(#tab-queue,#tab-waitlist) .q-views>.live-share .filter-select{width:auto;min-width:0;}
body.view-staff :is(#tab-queue,#tab-waitlist) .q-views>.live-share .am-meta:empty{display:none;}

/* ── Bookings: the night's figures as one bar that stays in view: the live three, then the rest and the
   overdue line. Expected and On Bike were the same numbers twice; the live buttons wear their colours. ── */
body.view-staff :is(#tab-queue,#tab-waitlist) .q-live-count{flex-wrap:wrap;gap:6px 8px;padding:6px 8px;margin:0 0 12px;}
body.view-staff :is(#tab-queue,#tab-waitlist) .q-lc-nums{display:flex;align-items:center;gap:2px 4px;flex-wrap:nowrap;}
body.view-staff :is(#tab-queue,#tab-waitlist) .q-live-count .q-lc-btn{min-height:var(--sf-ctl-size);padding:0 10px;border-radius:var(--sf-r-ctl);gap:7px;}
body.view-staff :is(#tab-queue,#tab-waitlist) .q-live-count .q-lc-active::before,
body.view-staff :is(#tab-queue,#tab-waitlist) .q-live-count .q-lc-waiting::before{content:'';width:8px;height:8px;border-radius:50%;flex-shrink:0;}
body.view-staff :is(#tab-queue,#tab-waitlist) .q-live-count .q-lc-active::before{background:#d4a017;}
body.view-staff :is(#tab-queue,#tab-waitlist) .q-live-count .q-lc-waiting::before{background:#fff;box-shadow:inset 0 0 0 1px #9aa29d;}
html[data-staff-theme="dark"] body.view-staff :is(#tab-queue,#tab-waitlist) .q-live-count .q-lc-active::before{background:#f2b43f;}
html[data-staff-theme="dark"] body.view-staff :is(#tab-queue,#tab-waitlist) .q-live-count .q-lc-waiting::before{background:#1b2027;box-shadow:inset 0 0 0 1px #7f8890;}
body.view-staff :is(#tab-queue,#tab-waitlist) .q-live-count .stat-strip{margin:0;flex-wrap:wrap;gap:6px;padding-inline-start:8px;border-inline-start:1px solid var(--sf-line);}
body.view-staff :is(#tab-queue,#tab-waitlist) .q-live-count .stat-chip{min-height:32px;padding:0 10px;border-radius:var(--sf-r-ctl);}
/* While the live channel is down: when this device's copy was last read (staff round s10, item 8). Small text, never a bar. */
body.view-staff :is(#tab-queue,#tab-waitlist) .q-live-count .q-lc-upd{font-size:var(--sf-fs-xs);color:var(--muted);white-space:nowrap;padding-inline:4px;}
body.view-staff :is(#tab-queue,#tab-waitlist) .q-live-count .overdue-banner{margin:0;margin-inline-start:auto;padding:0 4px 0 10px;min-height:38px;gap:10px;border-radius:var(--sf-r-ctl);}
body.view-staff :is(#tab-queue,#tab-waitlist) .q-live-count .overdue-banner .btn-sm{min-height:30px;}
/* an approval ride's funnel has no live three: it stands alone, the same height */
body.view-staff :is(#tab-queue,#tab-waitlist)>.stat-strip .stat-chip{min-height:32px;border-radius:var(--sf-r-ctl);}

/* ── Bookings: the rides as one tidy grid of equal cards, each a few lines tall (they were up to 297px of
   cards in three sizes; tonight's leads by its ring and type now, not by its size) ── */
body.view-staff :is(#tab-queue,#tab-waitlist) .sess-summary-bar.sess-bar-desktop{display:grid;grid-template-columns:repeat(auto-fill,minmax(220px,1fr));gap:8px;margin:0 0 12px;}
body.view-staff :is(#tab-queue,#tab-waitlist) .sess-bar-desktop .sess-summary-chip{min-width:0;max-width:none;padding:6px 10px;gap:8px;align-items:flex-start;}
body.view-staff :is(#tab-queue,#tab-waitlist) .sess-bar-desktop .sess-summary-chip.today-sess{padding:6px 10px;}
body.view-staff :is(#tab-queue,#tab-waitlist) .sess-bar-desktop .sess-summary-chip.today-sess .sess-chip-date{font-size:var(--sf-fs-sm);font-weight:600;}
body.view-staff :is(#tab-queue,#tab-waitlist) .sess-bar-desktop .sess-chip-date{font-size:var(--sf-fs-xs);}
body.view-staff :is(#tab-queue,#tab-waitlist) .sess-bar-desktop .sess-chip-top{gap:6px;margin-bottom:1px;}
body.view-staff :is(#tab-queue,#tab-waitlist) .sess-bar-desktop .sess-chip-top .smk{width:20px;height:20px;border-radius:var(--sf-r-ctl);}
body.view-staff :is(#tab-queue,#tab-waitlist) .sess-bar-desktop .sess-chip-bf{margin-top:0;}
/* smaller and more compact (2026-11-10, the user): four lines, not six. The status sits at the end of the name's line
   (its own column took the card's whole height and pushed every line into ~190px), the meeting place and series follow
   the time, and the fill bar shares its line with the places left. */
body.view-staff .sess-chip-top .sess-chip-badge{flex:none;margin-inline-start:auto;}
body.view-staff .sess-chip-top .sess-chip-badge [class^="badge-"]{font-size:var(--sf-fs-xs);}
body.view-staff .sess-chip-date .ssx{font-weight:500;color:var(--muted);vertical-align:bottom;}
body.view-staff .sess-chip-date .ssx-place{margin-inline-start:6px;} /* its pin parts it from the time: a dot left dangling when the place wrapped */
body.view-staff .sess-summary-chip:is(.th-jcc,.th-snd96) .sess-chip-date .ssx{color:rgba(255,255,255,.82);}
body.view-staff .sess-chip-date .ssx-place bdi{max-width:150px;}
body.view-staff .sess-chip-foot{display:flex;align-items:center;gap:8px;min-width:0;margin-top:3px;}
body.view-staff .sess-chip-foot .sess-chip-bar{flex:1 1 auto;min-width:30px;margin:0;}
body.view-staff .sess-summary-chip .sess-chip-foot .n6c-left{flex:none;margin:0;font-size:var(--sf-fs-xs);line-height:1.2;white-space:nowrap;}
/* the circuit's chevrons sit in the card's end corner, on the bar's line: the line stops short of them */
body.view-staff .sess-summary-chip.th-jcc .sess-chip-foot{padding-inline-end:50px;}

/* ── Saved views sit in the search row, after its buttons, not on a row of their own (Bookings, History,
   Workshop, Messages, the action log, Accounts) ── */
body.view-staff .filter-row>.sv-bar,body.view-staff .lg-bar>.sv-bar{display:flex;flex-wrap:nowrap;align-items:center;gap:8px;margin:0;}
body.view-staff .lg-bar>.sv-bar .sv-lbl .filter-field-lbl,body.view-staff .filter-row>.sv-bar .sv-lbl .filter-field-lbl{position:absolute;width:1px;height:1px;margin:-1px;padding:0;overflow:hidden;clip:rect(0 0 0 0);white-space:nowrap;border:0;}
body.view-staff .filter-row>.sv-bar .sv-pick,body.view-staff .lg-bar>.sv-bar .sv-pick{max-width:200px;}

/* ── Bookings table: every cell starts at the top (a party's cells sat in the middle), the call and
   WhatsApp pair beside the number, and each Manage booking tile in one place on every row: the select box
   top left, the main action top right, ⋯ under the box and the envelope under the action. A row with no
   box keeps its action on the right; it used to slide left into the box's place. ── */
body.view-staff :is(#tab-queue,#tab-waitlist) .queue-table td,
body.view-staff :is(#tab-queue,#tab-waitlist) .queue-table td.rq-vm{vertical-align:top;}
body.view-staff :is(#tab-queue,#tab-waitlist) .queue-table td .rider-sub{display:inline-flex;align-items:center;gap:4px;vertical-align:middle;margin-top:4px;}
body.view-staff :is(#tab-queue,#tab-waitlist) .queue-table td .rq-ccin{display:inline-flex;vertical-align:middle;margin:4px 0 0;margin-inline-start:8px;}
@media(max-width:767px){
  /* the rider's name on its own line: the call, WhatsApp, status and payment cluster beside it left the
     name 0-31px ("Omar Hassan" read "O..", a walk-in's name nothing at all) */
  body.view-staff :is(#tab-queue,#tab-waitlist) .q-card .rq-crow>.rq-sb8{flex-wrap:wrap;row-gap:8px;}
  body.view-staff :is(#tab-queue,#tab-waitlist) .q-card .rq-crow .rq-cl{flex:1 1 100%;}
  body.view-staff :is(#tab-queue,#tab-waitlist) .q-card .rq-crow .rq-cname{max-width:none;}
  body.view-staff :is(#tab-queue,#tab-waitlist) .q-card .rq-crow .rq-cr{flex:1 1 100%;}
  body.view-staff :is(#tab-queue,#tab-waitlist) .q-card .rq-crow .rq-cr .rq-end{margin-inline-start:auto;}
  /* the header's actions as equal cells, three to a row (they ran off the screen's edge) */
  body.view-staff :is(#tab-queue,#tab-waitlist) .sf-head-actions{display:grid !important;grid-template-columns:repeat(3,minmax(0,1fr));gap:6px;overflow:visible;width:100%;}
  body.view-staff :is(#tab-queue,#tab-waitlist) .sf-head-actions>*{width:100%;min-width:0;margin:0;}
  body.view-staff :is(#tab-queue,#tab-waitlist) .sf-head-actions>button{justify-content:center;padding-inline:6px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;}
  /* the views as equal cells; the live-location switch on its own row */
  body.view-staff :is(#tab-queue,#tab-waitlist) .q-views{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:6px;}
  body.view-staff :is(#tab-queue,#tab-waitlist) .q-views>.filter-pill{width:100%;min-width:0;justify-content:center;}
  body.view-staff :is(#tab-queue,#tab-waitlist) .q-views>.live-share{grid-column:1/-1;margin:0;}
  body.view-staff :is(#tab-queue,#tab-waitlist) .q-views>.live-share .filter-select{flex:1 1 auto;}
  /* the night's figures stay one line while they stick: the live three first, the rest a swipe away */
  body.view-staff :is(#tab-queue,#tab-waitlist) .q-live-count{flex-wrap:nowrap;overflow-x:auto;scrollbar-width:none;-webkit-overflow-scrolling:touch;}
  body.view-staff :is(#tab-queue,#tab-waitlist) .q-live-count::-webkit-scrollbar{display:none;}
  body.view-staff :is(#tab-queue,#tab-waitlist) .q-live-count .stat-strip{flex-wrap:nowrap;overflow:visible;padding-bottom:0;}
  body.view-staff :is(#tab-queue,#tab-waitlist) .q-live-count .q-lc-btn{min-height:44px;}
  body.view-staff :is(#tab-queue,#tab-waitlist) .q-live-count>*{flex:0 0 auto;}
}
/* the table inside its box at 1280px (it overhung by 30px): tighter cells, a narrower price breakdown, and
   the room given to the rider, whose call and WhatsApp pair now sits beside the number.
   2026-11-08: it hung out again, 30px in light and dark, 54px in booth (Return Bike off the screen) and 22px in
   Arabic. Each column is as wide as its widest one-line item (a party's Mark paid, To be reserved, On the house,
   Bike owner, the sort headers), and from 1280 the box (969px inside) does not scroll, so the header can stick to
   the page. Those items already summed 17px past it on a busy night; the Soft Solid look's IBM Plex Sans set each
   3-5px wider. Cells keep 4px a side; Mark paid, the pay buttons and the bike type badges take the Manage booking
   tiles' 8px (Mark paid had the 38px buttons' 14px); the rider keeps 140px. At 1280: 36px to spare in light and
   dark, 12 in booth, 42 in Arabic. */
body.view-staff :is(#tab-queue,#tab-waitlist) .queue-table th,
body.view-staff :is(#tab-queue,#tab-waitlist) .queue-table td{padding-inline:4px;}
body.view-staff :is(#tab-queue,#tab-waitlist) .queue-table td>.rider-name{min-width:140px;}
body.view-staff :is(#tab-queue,#tab-waitlist) .queue-table .rq-gpaid,
body.view-staff :is(#tab-queue,#tab-waitlist) .queue-table .pay-toggle,
body.view-staff :is(#tab-queue,#tab-waitlist) .queue-table .q-type-cell .type-badge{padding-inline:8px;}
body.view-staff :is(#tab-queue,#tab-waitlist) .queue-table .rq-bkat{max-width:5em;}
body.view-staff :is(#tab-queue,#tab-waitlist) .queue-table .rq-adline{max-width:7.5em;}
/* a ride card's date and time wrap rather than lose the time to an ellipsis, onto the lines they need: a clamp at two
   cut "Start 6 AM" off a gathering ride's two times on a 220px card (2026-10-27) */
body.view-staff :is(#tab-queue,#tab-waitlist) .sess-bar-desktop .sess-chip-date{white-space:normal;display:block;overflow:hidden;line-height:1.3;}
/* an empty result count took a row's gap under the search row */
body.view-staff .filter-bar>.result-count:empty{display:none;}
body.view-staff :is(#tab-queue,#tab-waitlist,#tab-sessions) .filter-bar{margin-bottom:12px;}
body.view-staff :is(#tab-queue,#tab-waitlist) .queue-table .rq-gname{max-width:5.4em;white-space:normal;display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;line-height:1.25;overflow-wrap:anywhere;}
@media(min-width:1024px){
  body.view-staff :is(#tab-queue,#tab-waitlist) .queue-table-desktop-wrap .queue-table th{top:calc(var(--staff-top) + var(--q-lc-h,0px) + var(--q-bk-h,0px));} /* under the selection's actions too (round two, _lcStick) */
}
body.view-staff :is(#tab-queue,#tab-waitlist) .sess-bar-desktop .sess-chip-date bdi{white-space:nowrap;}
@media(max-width:767px){
  /* the title back on a phone (2026-10-03 dropped it because the Bookings tab above named the page; the tabs
     sit under the title in every view now, so they stay put when switching views) */
  body.view-staff :is(#tab-queue,#tab-waitlist) .q-head-title{display:block;}
  body.view-staff :is(#tab-queue,#tab-waitlist)>.overdue-banner{margin:0 0 12px;}
}
@media(max-width:767px){body.view-staff :is(#tab-queue,#tab-waitlist) .sf-head-actions{padding-bottom:0;}}
@media(max-width:767px){
  /* in the phone's two-cell search rows (Customers, Community) the saved views take a row of their own */
  #tab-community .filter-row>.sv-bar,#tab-customers .filter-row>.sv-bar{grid-column:1/-1;width:100%;}
