@media (max-width:767px){
  /* the header's action cells: a long label takes two lines (Arabic's "Approve all (1)" was cut at both
     ends - centred text in a flex button gets no ellipsis) */
  body.view-staff :is(#tab-queue,#tab-waitlist) .sf-head-actions>button{white-space:normal;line-height:1.15;text-align:center;}
  /* Sales: quantity and unit price share the row equally; at one third the stepper's 44px buttons left the
     quantity field about 20px and its number out of sight (in every language and theme) */
  body.view-staff #tab-cashier .sl-row9>.sl-f1,
  body.view-staff #tab-cashier .sl-row9>.sl-f2{flex:1 1 0;min-width:0;}
}

/* ── STAFF TIDY: the five left over (2026-10-27, "fix them") ── */

/* The figures at the top of a section never leave one alone on a row: _figFit measures each grid and sets
   its columns (--fig-c) and how many of them a figure spans (--fig-s, or --fig-w for the slightly wider
   ones in the last rows, where seven on a phone read 3 + 2 + 2). Without it the grid keeps the auto-fit
   above. */
body.view-staff :is(.dash-kpis,.stats-row).fig-fit{grid-template-columns:repeat(var(--fig-c),minmax(0,1fr));}
body.view-staff :is(.dash-kpis,.stats-row).fig-fit>*{grid-column:span var(--fig-s);}
body.view-staff :is(.dash-kpis,.stats-row).fig-fit>.fig-wide{grid-column:span var(--fig-w);}

/* Bookings on a tablet or a laptop with the rail open (768-1279px): the roster scrolls in its box, and Manage
   booking stays pinned at its end as the booking number is at its start, so Check In is on screen on every
   row (it was 200-300px off the box's edge). A row's own colour fills it: every roster row has one. */
@media (min-width:768px) and (max-width:1279px){
  body.view-staff :is(#tab-queue,#tab-waitlist) .queue-table-desktop-wrap .queue-table td.rq-mng{position:sticky;inset-inline-end:0;z-index:2;box-shadow:-1px 0 0 var(--border);}
  body.view-staff :is(#tab-queue,#tab-waitlist) .queue-table-desktop-wrap .queue-table th.rq-mng{position:sticky;inset-inline-end:0;z-index:4;box-shadow:0 1px 0 var(--border),-1px 0 0 var(--border);}
  html[dir="rtl"] body.view-staff :is(#tab-queue,#tab-waitlist) .queue-table-desktop-wrap .queue-table td.rq-mng{box-shadow:1px 0 0 var(--border);}
  html[dir="rtl"] body.view-staff :is(#tab-queue,#tab-waitlist) .queue-table-desktop-wrap .queue-table th.rq-mng{box-shadow:0 1px 0 var(--border),1px 0 0 var(--border);}
  body.view-staff .queue-table td.rq-mng{background-color:var(--s1);}
}

/* A pinned cell takes its row's colour. It needs a solid fill to hide the columns sliding under it, and the
   fills were the table's plain colour: History's Manage Record and the fleet's Manage bike stayed white on a
   striped row and on the row under the pointer, and the fleet's state washes (in use, no rider, picked)
   stopped at both pinned ends. The washes now sit on the cells as an image layer over whatever fills them;
   the stripe and the pointer's colour reach the pinned cells. */
@media (min-width:768px){
  body.view-staff #tab-history .queue-table tbody tr:nth-child(odd) td.hist-act{background:var(--sf-zebra);}
  body.view-staff #tab-history .queue-table tbody tr:hover td.hist-act{background:var(--sf-hover);}
  body.view-staff #tab-inventory .bk-table tbody tr:nth-child(odd) td:last-child{background-color:var(--sf-zebra);}
  body.view-staff #tab-inventory .bk-table tbody tr:hover td:last-child{background-color:var(--sf-hover);}
  /* (a phone's fleet rows are cards, whose own background is the wash: they keep it) */
  body.view-staff #tab-bikes .bk-table tbody tr:is(.flt-bg-warn,.flt-bg-blue,.flt-bg-out,.flt-bg-sel){background:none;}
  body.view-staff #tab-bikes .bk-table tbody tr.flt-bg-warn>td{background-image:linear-gradient(rgba(var(--warn-rgb),.06),rgba(var(--warn-rgb),.06));}
  body.view-staff #tab-bikes .bk-table tbody tr.flt-bg-blue>td{background-image:linear-gradient(rgba(var(--blue-rgb),.025),rgba(var(--blue-rgb),.025));}
  body.view-staff #tab-bikes .bk-table tbody tr.flt-bg-out>td{background-image:linear-gradient(rgba(var(--red-rgb),.025),rgba(var(--red-rgb),.025));}
  body.view-staff #tab-bikes .bk-table tbody tr.flt-bg-sel>td{background-image:linear-gradient(rgba(var(--green-rgb),.07),rgba(var(--green-rgb),.07));}
}
/* Dark: the stripe and the pointer's colour are see-through white (2% and 6%), so on a striped row the pinned
   booking number showed the height and the date sliding under it. In the tables they are the same colours
   made solid: the white mixed into the table's own. */
html[data-staff-theme="dark"] body.view-staff .queue-table tbody{--sf-zebra:color-mix(in srgb,#fff 2%,var(--s1));--sf-hover:color-mix(in srgb,#fff 6%,var(--s1));}

/* The Petromin page: a status pill's count kept no space from its word ("All3", "Not arrived1": a pill is a flex
   box, which drops the space before the count's own element); on a phone the page's buttons are equal cells, as
   the Bookings header's are, two to a row or the three in one (they sat in ragged rows at the screen's right). */
body.view-staff #pm-host .filter-pill>.iv-o7{margin-inline-start:.35em;}
@media (max-width:767px){
  body.view-staff #pm-host .iv-pm-btns{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:6px;width:100%;}
  body.view-staff #pm-host .iv-pm-btns.pm-n3{grid-template-columns:repeat(3,minmax(0,1fr));}
  body.view-staff #pm-host .iv-pm-btns.pm-n5>.btn-sm:last-child{grid-column:1/-1;} /* five (an admin's, with Form steps): the last a whole row, not half of one */
  body.view-staff #pm-host .iv-pm-btns>.btn-sm{width:100%;min-width:0;margin:0;padding-inline:6px;white-space:normal;line-height:1.15;text-align:center;justify-content:center;}
}
/* The Arena Heros race: you must have a partner (the owner, 2026-11-02): said loud on the card, the athlete step and the review */
.ar-must{margin:0 0 14px;padding:10px 12px;border:2px solid #e3262f;background:rgba(227,38,47,.14);font-size:14px;font-weight:800;line-height:1.4;color:#fff;}
body.ar-skin:not(.view-staff) .vl-panel .run-adult.ar-must{color:#fff;}
body .landing-event-card.ev-arena .ar-must{display:block;margin:8px 0 0;padding:6px 8px;font-size:13px;color:#fff;}
/* its ticket is black: the transfer's box and the note where the code will be read on black, the button in the race's red */
.ticket-card.th-arena .vt-tk{background:#1c1c1c;border-color:rgba(227,38,47,.55);color:#fff;}
.ticket-card.th-arena .vt-tk-q,.ticket-card.th-arena .cu-tk-cue{color:#fff;}
.ticket-card.th-arena .vt-tk .btn-primary{background:#e3262f;border-color:#e3262f;color:#fff;}
.ticket-card.th-arena .qr-hold{background:rgba(255,255,255,.07);border-color:rgba(255,255,255,.3);}
.ticket-card.th-arena .qr-hold span{color:#fff;}

/* ══ THE BLOOD DONATION EVENT (2026-11-03) ════════════════════════════════════════════════════════════════
   One look from the event card to the ticket, the waiver and the pop-ups too: body.bld-skin (_syncBldTheme) re-points the
   customer system's colours at the --bld-* tokens, the ticket wears them through th-blood. The hosts' marks stay on their
   white plate in every state: the Ministry of Sport's guide wants its colour logo on white, never on a dark, patterned or
   foreign-coloured ground. Nothing decorative runs under the plate. Buttons stay square. */
:root{--bld-a:#0B1F16;--bld-a2:#173A2A;--bld-on:#fff;--bld-ac:#08683F;--bld-wash:rgba(3,254,138,.14);--bld-a-rgb:11,31,22;--bld-paper:#EEF6F2;--bld-card:#fff;--bld-card2:#E6F2EC;--bld-card3:#D6E8DE;--bld-ink:#0B1F16;--bld-ink2:rgba(11,31,22,.76);--bld-ink3:rgba(11,31,22,.66);--bld-ink4:rgba(11,31,22,.42);--bld-line:rgba(11,31,22,.14);--bld-line2:rgba(11,31,22,.3);--bld-tint-rgb:11,31,22;--bld-scheme:light;--bld-r:0px;--bld-bar:#fff;--bld-bar-line:rgba(11,31,22,.3);--bld-bar-ink:#0B1F16;--bld-bar-ink2:rgba(11,31,22,.66);--bld-bar-soft:rgba(11,31,22,.14);--bld-bar-tint:11,31,22;--bld-bar-ac:#08683F;--bld-head-bg:#fff;--bld-head-ink:#0B1F16;--bld-head-ink2:rgba(11,31,22,.72);--bld-head-title:#0B1F16;--bld-head-line:rgba(11,31,22,.14);--bld-c-bg:#fff;--bld-c-line:#BFD4C9;--bld-c-ink:#0B1F16;--bld-c-ink2:rgba(11,31,22,.72);--bld-c-title:#0B1F16;--bld-c-ac:#08683F;--bld-c-plate:rgba(11,31,22,.1);--bld-c-ac-staff:#08683F;--bld-t-bg:#fff;--bld-t-2:#E6F2EC;--bld-t-ink:#0B1F16;--bld-t-ink2:rgba(11,31,22,.7);--bld-t-line:rgba(11,31,22,.14);--bld-t-ac:#0B1F16;--bld-t-edge:#BFD4C9;--bld-t-red:#B42318;}
.ev-blood{--ev:var(--bld-ac);}
html:has(> body.bld-skin:not(.view-staff)){--root-paper:var(--bld-paper);color-scheme:var(--bld-scheme);}
body.bld-skin:not(.view-staff){
  --paper:var(--bld-paper);--card:var(--bld-card);--card-2:var(--bld-card2);--card-3:var(--bld-card3);
  --ink:var(--bld-ink);--ink-2:var(--bld-ink2);--ink-3:var(--bld-ink3);--ink-4:var(--bld-ink4);
  --line:var(--bld-line);--line-2:var(--bld-line2);
  --go:var(--bld-a);--go-2:var(--bld-a2);--go-wash:var(--bld-wash);--neon:var(--bld-ac);
  --amber:var(--bld-ac);--amber-2:var(--bld-ac);--amber-wash:var(--bld-wash);--on-green:var(--bld-on);
  --accent2:var(--bld-line2);--green-rgb:var(--bld-a-rgb);--tint-rgb:var(--bld-tint-rgb);
  color-scheme:var(--bld-scheme);background:var(--bld-paper);}
/* the bars around the flow */
body.bld-skin:not(.view-staff) #topbar#topbar{background:var(--bld-bar);border-bottom:1px solid var(--bld-bar-line);box-shadow:none;}
