body.bld-skin:not(.view-staff) #topbar#topbar .cust-topbar-name{color:var(--bld-bar-ink);}
body.bld-skin:not(.view-staff) #topbar#topbar :is(.cust-topbar-email,.staff-access-btn){color:var(--bld-bar-ink2);}
body.bld-skin:not(.view-staff) #topbar#topbar :is(.topbar-btn,.lang-toggle){color:var(--bld-bar-ink);}
body.bld-skin:not(.view-staff) #topbar#topbar .chrome-av{background:var(--bld-bar-soft);border-color:var(--bld-bar-soft);color:var(--bld-bar-ink);}
