html body.bld-skin .cust-bnav-btn.active::after{background:var(--bld-bar-ac);}
/* what the customer system paints in its own green */
body.bld-skin:not(.view-staff) .btn-primary,body.bld-skin:not(.view-staff) .btn-primary:hover{color:var(--bld-on);}
body.bld-skin:not(.view-staff) .pg-btn:not(:disabled){color:var(--bld-on);}
body.bld-skin:not(.view-staff) .toggle-btn.active{background:var(--bld-a);border-color:var(--bld-a);color:var(--bld-on);}
body.bld-skin:not(.view-staff) .toggle-btn.active::before{background:var(--bld-on);}
body.bld-skin:not(.view-staff) #tab-register .cu-prog-b i{background:var(--bld-a);}
body.bld-skin:not(.view-staff) input[type="checkbox"]{accent-color:var(--bld-a);}
body.bld-skin:not(.view-staff) select option{background:var(--bld-card);color:var(--bld-ink);}
body.bld-skin:not(.view-staff) #tab-register .cu-sole-card{background:var(--bld-card);border-inline-start-color:var(--bld-ac);}
body.bld-skin:not(.view-staff) #tab-register .cu-c-green{color:var(--bld-ac);}
body.bld-skin:not(.view-staff) #tab-register a:not([class]){color:var(--bld-ac);}
body.bld-skin:not(.view-staff) .wg-agree.on{border-color:var(--bld-ac);background:var(--bld-wash);}
body.bld-skin:not(.view-staff) .sg-list .cu-ic,body.bld-skin:not(.view-staff) .wg-ln .cu-ic{color:var(--bld-ac);}
/* one corner for every card of the flow, and square controls: inputs read as the selects beside them */
body.bld-skin:not(.view-staff) :is(.wg-sess,.sg-list,.wg-agree,.wg-text,.pg-box,.reg-side,.form-section,.cu-sole-card){border-radius:var(--bld-r);}
body.bld-skin:not(.view-staff) :is(input[type="text"],input[type="tel"],input[type="email"]){border-radius:0;}
/* every block of a step on one line, left and right: the bar of buttons kept 4px in from the column */
body.bld-skin:not(.view-staff) #tab-register .mm-reg-foot{padding-inline:0;background:var(--bld-paper);}
