#door-page .zg-figs{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:8px;}
#door-page .zg-fig{padding:12px 8px;background:var(--sf-card);border:1px solid var(--sf-line);border-radius:var(--sf-r-card);text-align:center;color:var(--muted);font-size:var(--fs-sm);overflow-wrap:anywhere;}
#door-page .zg-fig b{display:block;color:var(--text);font-size:var(--fs-xl);font-weight:600;line-height:1.2;font-variant-numeric:tabular-nums;}
