#door-page .zg-scan{display:flex;align-items:center;justify-content:center;gap:10px;min-height:56px;font-size:var(--fs-md);border-radius:var(--sf-r-card);}
#door-page .zg-find{display:flex;gap:8px;margin:0;}
#door-page .zg-find input{flex:1 1 auto;min-width:0;min-height:48px;font-size:var(--fs-md);}
#door-page .zg-find button{min-height:48px;}
#door-page .zg-list{list-style:none;margin:8px 0 0;padding:0;display:grid;gap:6px;}
#door-page .zg-row{display:flex;flex-wrap:wrap;align-items:center;gap:6px 10px;width:100%;min-height:48px;padding:8px 12px;background:var(--sf-card);border:1px solid var(--sf-line);border-radius:var(--sf-r-ctl);color:var(--text);font:inherit;text-align:start;cursor:pointer;}
#door-page .zg-row:focus-visible{outline:2px solid var(--green);outline-offset:2px;}
#door-page .zg-rn{flex:1 1 auto;min-width:0;font-weight:600;overflow-wrap:anywhere;}
#door-page .zg-card{display:grid;gap:12px;padding:14px;background:var(--sf-card);border:1px solid var(--sf-line2);border-radius:var(--sf-r-sheet);box-shadow:var(--sf-sh-1);}
#door-page .zg-h2{margin:0;font-size:var(--fs-md);font-weight:600;}
#door-page .zg-rider{display:grid;gap:8px;}
#door-page .zg-rider+.zg-rider{padding-top:12px;border-top:1px solid var(--sf-sep);}
#door-page .zg-name{font-size:var(--fs-lg);font-weight:600;line-height:1.3;overflow-wrap:anywhere;}
#door-page .zg-sess{color:var(--orange);font-size:var(--fs-sm);font-weight:500;}
#door-page .zg-spec b{font-size:var(--fs-md);font-weight:600;}
#door-page .zg-in{width:100%;min-height:52px;font-size:var(--fs-md);border-radius:var(--sf-r-card);}
#door-page .zg-why{padding:10px 12px;border:1px solid currentColor;border-radius:var(--sf-r-ctl);background:var(--sf-sunken);font-weight:600;}
#door-page .zg-ok{color:var(--sf-green-ink);}
#door-page .zg-warn{color:var(--orange);}
#door-page :is(.zg-err,.zg-why.zg-err){color:var(--red);}
