#confirm-modal .ss-cust-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(170px,1fr));gap:2px 12px;}
#confirm-modal .ss-tog{display:flex;align-items:center;gap:8px;min-height:36px;font-size:var(--sf-fs-sm);font-weight:600;cursor:pointer;text-transform:none;letter-spacing:0;margin:0;}
#confirm-modal .ss-tog input{-webkit-appearance:checkbox;appearance:checkbox;width:18px;height:18px;min-height:0;padding:0;margin:0;flex:none;accent-color:var(--green);} /* inputs are appearance:none site-wide: ask for the native box */
