/* ══ THE DESK, SECOND ROUND (2026-11-07: BK10 pace line, BK14 places left, OT04 bike prep, OT06 first ride, OT08 check-in states) ══ */
/* the muted words are the staff's --muted (--text-2 is defined nowhere, so its #555 fallback won: 2.4:1 on the
   dark theme's cards and bar, 1.7-1.9:1 on the circuit's navy and the National Day green) */
.sess-summary-chip .n6c-left{display:block;font-size:var(--sf-fs-xs);font-weight:600;color:var(--muted);margin-top:2px;}
.sess-summary-chip .n6c-left.n6c-full{color:var(--red,#c92a2a);}
/* on the dark cards (the circuit, the National Day ride), in every staff theme, the places left wear the light
   words of the lines above them, and a light red when the night is full */
body.view-staff .sess-summary-chip.th-jcc .n6c-left{color:var(--jcc-cyan-lt);}
body.view-staff .sess-summary-chip.th-snd96 .n6c-left{color:var(--snd-mut);}
body.view-staff .sess-summary-chip:is(.th-jcc,.th-snd96) .n6c-left.n6c-full{color:#fca5a5;}
.n6c-pace{display:flex;flex-wrap:wrap;align-items:center;gap:4px 6px;font-size:var(--sf-fs-sm);color:var(--muted);padding:4px 0 2px;}
.n6c-first{display:inline-flex;align-items:center;margin-inline-start:6px;padding:1px 6px;font-size:var(--sf-fs-xs);font-weight:600;line-height:16px;background:#b35c00;color:#fff;border-radius:var(--sf-r-xs);vertical-align:middle;white-space:nowrap;}
.n6c-st{display:inline-block;margin-top:3px;padding:1px 6px;font-size:var(--sf-fs-xs);font-weight:600;line-height:16px;border-radius:var(--sf-r-xs);color:#fff;white-space:nowrap;}
.n6c-st-amber{background:#b35c00;}.n6c-st-blue{background:#1864ab;}.n6c-st-violet{background:#6741d9;}
.n6c-st-teal{background:#087f5b;}.n6c-st-pink{background:#c2255c;}.n6c-st-grey{background:#495057;}
.n6c-st-pick{display:grid;grid-template-columns:1fr;gap:8px;margin-top:10px;}
.n6c-st-opt{display:flex;flex-direction:column;align-items:flex-start;gap:2px;min-height:44px;padding:8px 12px;border:2px solid transparent;border-radius:var(--sf-r-xs);color:#fff;cursor:pointer;text-align:start;font:inherit;}
.n6c-st-opt small{font-size:var(--sf-fs-xs);opacity:.9;}
.n6c-st-opt.active{border-color:var(--text,#111);box-shadow:0 0 0 2px #fff inset;}
.n6c-st-set .n6c-st-row{display:grid;grid-template-columns:minmax(0,2fr) minmax(0,1fr) minmax(0,1.3fr);gap:6px;margin-top:6px;}
.n6c-co-list,.n6c-ft-list{list-style:none;margin:6px 0 0;padding:0;}
.n6c-co-list li{padding:4px 0;border-top:1px solid var(--border,#ddd);}
.n6c-co-late{font-size:var(--sf-fs-xs);color:var(--muted);}
.n6c-dlg{max-width:640px;width:calc(100vw - 32px);}
.n6c-prep-wrap{overflow-x:auto;margin-top:10px;}
.n6c-prep{border-collapse:collapse;width:100%;font-size:var(--sf-fs-md);}
.n6c-prep th,.n6c-prep td{padding:6px 8px;border-bottom:1px solid var(--border,#ddd);text-align:start;}
.n6c-prep .num{text-align:end;font-variant-numeric:tabular-nums;}
.n6c-prep .n6c-0{color:var(--text-3,#999);}
.n6c-prep .n6c-short{background:rgba(201,42,42,.12);color:var(--red,#c92a2a);}
