.n6c-ft-acts{display:flex;gap:6px;flex:none;}
@media (max-width:600px){.n6c-ft-row{flex-direction:column;align-items:stretch;}.n6c-st-set .n6c-st-row{grid-template-columns:1fr;}}
/* ── People review (2026-11-06): the account window as a profile, stages, notes, duplicates ── */
.n6p-bar{display:flex;flex-wrap:wrap;gap:6px;margin-top:8px;}
.n6p-bar .n6p-act{display:inline-flex;align-items:center;gap:6px;border-radius:0;text-decoration:none;}
