.n6p-st-views .btn-secondary{border-radius:0;}
.n6p-pin{display:flex;align-items:center;gap:4px;margin-top:3px;max-width:26ch;padding:1px 6px;border:1px solid var(--orange);background:transparent none;color:var(--orange);font:inherit;font-size:var(--staff-fs-sm,12px);font-weight:600;cursor:pointer;border-radius:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;text-align:start;}
.ci-drawer-bg .n6p-pin{max-width:none;white-space:normal;margin:6px 0;}
