body.view-staff .spk{position:relative;display:block;min-width:0;max-width:100%;}
body.view-staff select[data-spk]{position:absolute!important;inset-inline-start:0;bottom:0;width:1px!important;height:1px!important;min-width:0!important;min-height:0!important;padding:0!important;margin:0!important;border:0!important;opacity:0!important;pointer-events:none!important;}
body.view-staff .spk-btn{display:flex;align-items:center;gap:8px;width:100%;min-height:var(--sf-ctl-size,38px);padding:4px 10px;border:1px solid var(--sf-line,var(--border));border-radius:var(--sf-r-ctl,var(--sf-r-ctl));background:var(--sf-card,var(--s1));color:var(--text);font:400 var(--sf-fs-md)/1.3 var(--sf-font,inherit);text-align:start;cursor:pointer;}
body.view-staff .spk-btn:hover{border-color:var(--sf-ctl-h,var(--border));}
body.view-staff .spk-btn:focus-visible{outline:2px solid var(--green);outline-offset:2px;}
