#spk-pop .spk-q{-webkit-appearance:none;appearance:none;width:100%;box-sizing:border-box;min-height:var(--sf-ctl-size,38px);padding:0 12px;border:1px solid var(--sf-line,var(--border));border-radius:var(--sf-r-ctl,var(--sf-r-ctl));background:var(--sf-card,var(--s1));color:var(--text);font:400 var(--sf-fs-md)/1.3 var(--sf-font,inherit);}
