:is(#sto-modal,#sto-pe,#pay-rf) .confirm-box{max-height:calc(100vh - 40px);max-height:calc(100dvh - 40px);display:flex;flex-direction:column;}
:is(#sto-modal,#sto-pe,#pay-rf) .chrome-dbody{overflow-y:auto;min-height:0;display:flex;flex-direction:column;gap:12px;}
